window.DATA_READER_SHANG = [{"num": 1, "title_en": "Self Introduction", "title_zh": "自我介绍", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My name is Robert. My friends call me Bob. I am twenty years old. I am Chinese. I come from Beijing. There are six people in my family. I have one younger sister and two older brothers. We are not rich, but we are a happy family."], "zh": ["我叫罗伯特。我的朋友们都叫我鲍勃。我20岁，中国人，籍贯北京，家里有六口人。我有一个妹妹和两个哥哥。我们虽不富有，但家庭却很幸福。"]}, "dialog": null, "vocab": [{"num": 1, "word": "name", "phonetic": "[neɪm]", "pos": "n.", "meaning": "名字", "examples": [{"en": "What's your name, please?", "zh": "请问你叫什么名字？"}], "sub_entries": []}, {"num": 2, "word": "friend", "phonetic": "[frend]", "pos": "n.", "meaning": "朋友", "examples": [{"en": "He has many friends.", "zh": "他有许多朋友。"}], "sub_entries": []}, {"num": 3, "word": "call", "phonetic": "[kɔːl]", "pos": "vt.", "meaning": "称，叫（名）", "examples": [{"en": "Cindy calls her doll Baby.", "zh": "辛蒂把她的洋娃娃叫做宝贝。"}], "sub_entries": []}, {"num": 4, "word": "Chinese", "phonetic": "[tarˈniz]", "pos": "a.", "meaning": "中国人的&n.中国人", "examples": [], "sub_entries": []}, {"num": 5, "word": "come", "phonetic": "[kam]", "pos": "vi.", "meaning": "来自", "examples": [{"en": "I come from Japan.", "zh": "我是日本人。"}], "sub_entries": ["come from...", "来自于"]}, {"num": 6, "word": "people", "phonetic": "[ˈpip!]", "pos": "n.", "meaning": "人们", "examples": [{"en": "There are many people at the station.", "zh": "车站里有许多人。"}, {"en": "There is only one people in the room. (×) → There is only one person in the room. (○)", "zh": "房间里只有一个人。"}], "sub_entries": []}, {"num": 7, "word": "family", "phonetic": "[ˈfemall]", "pos": "n.", "meaning": "家庭", "examples": [{"en": "He has a large family.", "zh": "他家里人口很多。"}], "sub_entries": []}, {"num": 8, "word": "younger sister", "phonetic": "", "pos": "短语", "meaning": "妹妹", "examples": [], "sub_entries": ["older sister", "姐姐", "younger brother", "弟弟", "older brother", "哥哥"]}, {"num": 9, "word": "rich", "phonetic": "[rit]", "pos": "a.", "meaning": "富有的", "examples": [{"en": "The old man is rich, but he is not happy.", "zh": "这位老先生很有钱，但他却不快乐。"}], "sub_entries": []}, {"num": 10, "word": "happy", "phonetic": "[ˈhapi]", "pos": "a.", "meaning": "快乐的", "examples": [{"en": "I feel happy when I am with you.", "zh": "跟你在一起时，我就感到快乐。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍动词call作不完全及物动词的用法，以及表示 年龄及籍贯的说法。", "items": [{"num": 1, "title": "My friends call me Bob.", "body": ["（我的朋友们都叫我鲍勃。）call [ kol]vt.称.....为...…. 此处的call在语法中称为不完全及物动词；换言之，call仍是及物动词，之后应接宾语，但意思仍不完全，故须置名词于该宾语之后，以补足句意的完整。该名 词称为宾语补足语。", "例：They call the little girl...（×，句意不完整）（他们称这小女孩为...）", "→They call the little girl Mary. (○)（他们称这小女孩为玛丽。）"]}, {"num": 2, "title": "I am twenty years old.", "body": ["（我20岁。）", "a. 此类句子结构为：", "人+be动词+数字+year(s)+old 某人几岁了", "例：My baby boy is one year old.（我的小宝贝一周岁了。）", "He is twenty-five years old.（他25岁。）", "b. 在上列例句中i的old亦可用of age取代。", "He is twenty-five years old.", "=He is twenty-five years of age.*age[ed3]n.年纪", "c. 谈到age还有-一个很好的用法：", "look young for one's age", "=look younger than one really is 看起来比实际年纪年轻", "例：You look young for your age.", "=You look younger than you really are.（你看起来比实际年纪要年轻。）"]}, {"num": 3, "title": "I am Chinese.", "body": ["=I am a Chinese.（我是中国人。）第一例中的Chinese是形容词，之前不置不定冠词\"a\"；第二例中的Chinese则作名词，之前须置\"a”。"]}, {"num": 4, "title": "There are six people in my family.", "body": ["（我家里有六口人。）", "a. there 置于句首，之后接be 动词（is，are）时，作“有”解。句型如下：", "thereis+单数名词+表示场所的介词短语 there are+复数名词+表示场所的介词短语", "例：There is a book on the desk.（桌上有一本书。）", "There are thirty students in my class.（我班上有30个学生。）", "b. there[oer]一字则是副词，本意为“那里”", "例：Put the book there.（把书放在那里。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}, {"num": 4, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 2, "title_en": "Nice to Meet You", "title_zh": "幸会", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mike", "speaker_zh": "迈克", "en": "Hi! My name is Mike.", "zh": "嗨！我叫迈克。"}, {"speaker_en": "Nancy", "speaker_zh": "南希", "en": "Hi! I'm Nancy. Nice to meet you.", "zh": "嗨！我叫南希。幸会。"}, {"speaker_en": "Mike", "speaker_zh": "迈克", "en": "Nice to meet you, too.", "zh": "幸会。"}, {"speaker_en": "Nancy", "speaker_zh": "南希", "en": "Where are you from?", "zh": "你是什么地方人？"}, {"speaker_en": "Mike", "speaker_zh": "迈克", "en": "I'm from Shanghai. And you?", "zh": "我是上海人。你呢？"}, {"speaker_en": "Nancy", "speaker_zh": "南希", "en": "I'm from Chicago.", "zh": "我是芝加哥人。"}]}, "vocab": [{"num": 1, "word": "(It's) kind of you.", "phonetic": "", "pos": "日常口语", "meaning": "幸会。", "examples": [], "sub_entries": ["=(I'm) Glad to meet you."]}, {"num": 2, "word": "nice", "phonetic": "[naɪs]", "pos": "a.", "meaning": "好的", "examples": [], "sub_entries": []}, {"num": 3, "word": "meet", "phonetic": "[miːt]", "pos": "vt.", "meaning": "遇见", "examples": [], "sub_entries": []}, {"num": 4, "word": "too", "phonetic": "[tuː]", "pos": "adv.", "meaning": "也", "examples": [], "sub_entries": []}, {"num": 5, "word": "Where are you from?", "phonetic": "", "pos": "日常口语", "meaning": "你是什么地方人？", "examples": [], "sub_entries": ["=Where do you come from?"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请依个人情况回答下列问题", "questions": ["1. What do your friends call you?", "My", "2. How old are you?", "I", "3. Are you Chinese?", "Yes,", "4. How many people are there in your family?", "There are", "5. How many brothers and sisters do you have?", "I", "6. Where are you from?", "1"], "answers": ["范例:1.My friends call me Johnny.", "2. I am twenty-eight years old.", "3. Yes, I am Chinese.", "4. There are six people in my family.", "5. I have two brothers and one sister.", "6. I am from Beijing."]}}, {"num": 3, "title_en": "My Family", "title_zh": "我的家人", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My father is a teacher. He works during the day. My mother is a nurse. She works at night. They only see each other on the weekends. My brothers, my sister and I don't work. We are students. Because my parents have to work, we do the housework. But we never complain."], "zh": ["我爸爸是老师。他白天上班。妈妈则是护士。她晚上上班。他们只有在周末才会碰面。哥哥、妹妹和我没有上班。我们都是学生。因为爸妈要上班，家事都由我们来做。但我们从不埋怨。"]}, "dialog": null, "vocab": [{"num": 1, "word": "father", "phonetic": "[ˈfao]", "pos": "n.", "meaning": "父亲", "examples": [], "sub_entries": []}, {"num": 2, "word": "teacher", "phonetic": "[ˈtitfo]", "pos": "n.", "meaning": "老师", "examples": [], "sub_entries": []}, {"num": 3, "word": "work", "phonetic": "[wɜːrk]", "pos": "vi.", "meaning": "工作", "examples": [{"en": "My mother works in a hospital.", "zh": "我妈妈在医院里工作。"}], "sub_entries": []}, {"num": 4, "word": "during", "phonetic": "[ˈdjuriɡ]", "pos": "prep.", "meaning": "在...的时候", "examples": [{"en": "Cats sleep during the day.", "zh": "猫儿白天的时候睡觉。"}], "sub_entries": []}, {"num": 5, "word": "day", "phonetic": "[de]", "pos": "n.", "meaning": "白天", "examples": [], "sub_entries": []}, {"num": 6, "word": "mother", "phonetic": "[ˈmao]", "pos": "n.", "meaning": "母亲", "examples": [], "sub_entries": []}, {"num": 7, "word": "nurse", "phonetic": "[n3s]", "pos": "n.", "meaning": "护士", "examples": [], "sub_entries": []}, {"num": 8, "word": "see", "phonetic": "[siː]", "pos": "vt.", "meaning": "看见，和.…....见面", "examples": [{"en": "I see my friends on the weekends.", "zh": "我都是在周末和朋友们见面。"}], "sub_entries": []}, {"num": 9, "word": "weekend", "phonetic": "[ˈwikend]", "pos": "", "meaning": "n．周末（星期六和星期日不需", "examples": [{"en": "The pool is closed this weekend.", "zh": "本周末这个游泳池关闭。"}], "sub_entries": ["上班的时间）"]}, {"num": 10, "word": "student", "phonetic": "[ˈstjudant]", "pos": "n.", "meaning": "学生", "examples": [], "sub_entries": []}, {"num": 11, "word": "because", "phonetic": "[biˈkoz]", "pos": "conj.", "meaning": "因为", "examples": [{"en": "Tom is not here because he is sick.", "zh": "汤姆不在这里；因为他生病了。"}], "sub_entries": []}, {"num": 12, "word": "parents", "phonetic": "[ˈperants]", "pos": "n.", "meaning": "父母", "examples": [], "sub_entries": []}, {"num": 13, "word": "do", "phonetic": "[du]", "pos": "vt.", "meaning": "做", "examples": [], "sub_entries": []}, {"num": 14, "word": "housework", "phonetic": "[ˈhaus.wɚk]", "pos": "n.", "meaning": "家事", "examples": [{"en": "Housework is really boring.", "zh": "家事实在是令人觉得乏味。"}], "sub_entries": []}, {"num": 15, "word": "never", "phonetic": "[ˈnev]", "pos": "adv.", "meaning": "从不", "examples": [{"en": "Father never eats breakfast.", "zh": "爸爸从来不吃早餐。"}], "sub_entries": []}, {"num": 16, "word": "complain", "phonetic": "[kamˈplen]", "pos": "vi.", "meaning": "抱怨", "examples": [{"en": "Father is always busy, but he never complains.", "zh": "我爸爸总是很忙，可是他从来不抱怨。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍人称代词的种类及其用法，并介绍介词 during、代词eachother 及助动词have to的用法。", "items": [{"num": 1, "title": "My father is a teacher. He works during the day.", "body": ["（我爸爸是老师。他白天上班。）", "上例中He为阳性的代词，代替Myfathero", "在本课中，我们特别介绍了人称代词的用法。下面的", "表格可帮助读者熟悉各种人称代词的用法：", "数", "单", "数", "复", "数", "格", "主格", "宾", "格", "主格", "人称", "宾格", "第一人称", "I（我）", "me(我)", "we(我们）", "us(我们）", "第二人称", "you（你，你", "you（你，你）", "you（你们）", "you（你们）", "阳性", "he(他)", "him(他）", "第三", "they（他们；them（他们；", "人称", "阴性", "she(她）", "her(她）", "她们：", "她们：", "中性", "it（它）", "它们）", "it(它）", "它们）", "注意", "a.以上表格中主格项目内的人称代词在句中要作主", "语，宾格项目内的人称代词则作宾语。", "例：Peter likes music. He is a musician.", "（彼得喜欢音乐。他是音乐家。）", "Peter and I are teachers. We teach at the", "same school.", "（彼得和我都是老师。我们在同一所学校任", "教。）", "I have a younger sister. I love she very", "much.（x）", "→ I have a younger sister. I love her very", "much.(○)", "（我有一个妹妹。我很爱她。）", "You and Peter are from Japan. You", "lare", "Japanese.", "（你和彼得来自日本。你们是日本人。）", "b.it是中性代词，可用来代替任何单数的动植物或其", "他无生命的东西（如书，电扇等）。", "例： I see a tree there. It is very tall.", "（我看到那边有棵树。它很高。）", "This book is interesting. I enjoy reading", "it.", "（这本书很有趣，我很喜欢看。）"]}, {"num": 2, "title": "during the day 与 at night 的对称用法", "body": ["during the day（在白天）与 at night（在晚上）是一对常用的对称短语。以上两个短语亦可以用 by day 和 by night 取代。", "例：John sleeps during the day and works at night.", "= John sleeps by day and works by night.（约翰白天睡觉晚上工作。）"]}, {"num": 3, "title": "They only see each other on the weekends.", "body": ["（他们只有在周末才会碰面。）", "a. 上句中的eachother是代词，表示两者的“彼 此”的意思，在句中只作宾语。句中的主语必须限 定为两者。", "例：John and Mary are a couple. They love each other.（约翰和玛丽是一对夫妇。他们彼此相爱。）", "b. one another亦是代词，但表示三者或三者以上的“彼此”，在句中亦只作宾语。句中的主语必须为 三个或三个以上的人物。", "例：Mary and her three older sisters live", "together. They love one another.（玛丽和她三个姐姐住在一起。她们彼此相亲 相爱。）"]}, {"num": 4, "title": "Because my parents have to work, we do the housework.", "body": ["（因为爸妈要上班，家事都由我们来做。）此处haveto为助动词，表示“必须、不得不”的意 思。must亦为助动词，表示“必须”，但与have to 有所区别：", "must常指义务或责任上的“必须”；haveto则有“强制”或“非做不可”的意味。", "例：We must love our country.（我们必须爱国。）", "Youhave to finish all the work beforeyou may go home.（你必须做完所有的工作才能回家。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 4, "title_en": "What Do You Do?", "title_zh": "你是做什么的？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Tony", "speaker_zh": "托尼", "en": "What do you do, Jenny?", "zh": "詹妮，你是做什么的？"}, {"speaker_en": "Jenny", "speaker_zh": "詹妮", "en": "I'm a secretary. And you?", "zh": "我是秘书。你呢？"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "I'm a construction worker.", "zh": "我是建筑工人。"}, {"speaker_en": "Jenny", "speaker_zh": "詹妮", "en": "Do you like your work?", "zh": "你喜欢你的工作吗？"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Yes, I do. How about you?", "zh": "是的，喜欢。你呢？"}, {"speaker_en": "Jenny", "speaker_zh": "詹妮", "en": "Well, I want to be an actress.", "zh": "嗯，我想当演员。"}]}, "vocab": [{"num": 1, "word": "What do you do?", "phonetic": "", "pos": "日常口语", "meaning": "你是做什么的？", "examples": [], "sub_entries": ["=What's your occupation?", "*occupation [ˌɑkjuˈpeɪʃən] n. 职业"]}, {"num": 2, "word": "secretary", "phonetic": "[ˈsekra.ter1]", "pos": "n.", "meaning": "秘书", "examples": [], "sub_entries": []}, {"num": 3, "word": "construction worker", "phonetic": "[kanˈstrakfan.wɚk]", "pos": "n.", "meaning": "建筑工人", "examples": [], "sub_entries": []}, {"num": 4, "word": "How", "phonetic": "", "pos": "", "meaning": "about you?你呢?", "examples": [{"en": "A: I like music. And you? [How about you? B: Me, too.", "zh": "甲：我喜欢音乐。你呢？）（乙：我也喜欢。"}], "sub_entries": ["=And you?"]}, {"num": 5, "word": "want to + 动词原形", "phonetic": "", "pos": "", "meaning": "想要...", "examples": [{"en": "I want to see him now.", "zh": "我想要现在就见他。"}, {"en": "He wants to be an English teacher.", "zh": "他想要当英文老师。"}], "sub_entries": []}, {"num": 6, "word": "actress", "phonetic": "[ˈaektris]", "pos": "n.", "meaning": "女演员", "examples": [], "sub_entries": ["actor['ekto]n.男演员"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请于下列空格中填入适当的字", "questions": ["My father", "1", "a farmer.1", "a construction worker. We", "3", "very busy. We work", "4", "the week. I", "5", "a sister. She", "6", "a student.", "7", "sister", "8", "to be a secretary."], "answers": ["解答1.is", "2. am", "3. are", "4. during", "5.have", "6. is", "7. My", "8. wants"]}}, {"num": 5, "title_en": "Tony and His Family", "title_zh": "托尼和他的家人", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["I have a good friend. His name is Tony. He has an older sister. Her name is Tina. Their parents are Mr. and Mrs. Wang. Tony also has a dog. Its name is Rover. The Wangs are my neighbors. We live on the same street. The Wangs are very nice. I am lucky because the Wangs are such good neighbors."], "zh": ["我有个好朋友。他叫托尼。他有个姐姐。她的名字是蒂娜。他们的父母是王氏夫妇。托尼还有条狗。它叫来福。王家是我的邻居。我们住在同一条街。王家人很好。我很幸运，因为我有王家这么好的邻居。"]}, "dialog": null, "vocab": [{"num": 1, "word": "have", "phonetic": "[haev]", "pos": "vt.", "meaning": "有（用于 I、you 或复数的主语之后）", "examples": [{"en": "I have a wonderful family.", "zh": "我有个美满的家庭。"}], "sub_entries": ["has [hæz] vt. 有（用于 he、she、it 等第三人称单数主语之后）"]}, {"num": 2, "word": "good", "phonetic": "[ɡud]", "pos": "a.", "meaning": "好的；善良的", "examples": [{"en": "Judy is a good singer.", "zh": "朱迪是一位好歌手。"}], "sub_entries": []}, {"num": 3, "word": "her", "phonetic": "[h3]", "pos": "pron.", "meaning": "她的", "examples": [], "sub_entries": []}, {"num": 4, "word": "their", "phonetic": "[ocr]", "pos": "pron.", "meaning": "他们的", "examples": [], "sub_entries": []}, {"num": 5, "word": "also", "phonetic": "[ˈslso]", "pos": "adv.", "meaning": "也", "examples": [{"en": "Bob is my teacher and he is also my friend.", "zh": "鲍勃是我的老师，也是我的朋友。"}], "sub_entries": []}, {"num": 6, "word": "dog", "phonetic": "", "pos": "n.", "meaning": "狗", "examples": [], "sub_entries": []}, {"num": 7, "word": "the Wangs", "phonetic": "[ðə ˈwæŋz]", "pos": "n.", "meaning": "王氏一家人", "examples": [], "sub_entries": ["=the Wang family"]}, {"num": 8, "word": "neighbor", "phonetic": "[ˈnebɚ]", "pos": "n.", "meaning": "邻居", "examples": [{"en": "Mr. Smith is our next-door neighbor.", "zh": "史密斯先生是我们的隔壁邻居。"}], "sub_entries": []}, {"num": 9, "word": "live", "phonetic": "[liv]", "pos": "vi.", "meaning": "住", "examples": [{"en": "I live in the country.", "zh": "我住在乡下。"}], "sub_entries": []}, {"num": 10, "word": "same", "phonetic": "[sem]", "pos": "a.", "meaning": "相同的", "examples": [{"en": "Jane and I go to the same school.", "zh": "简和我上同－所学校。"}], "sub_entries": []}, {"num": 11, "word": "street", "phonetic": "", "pos": "n.", "meaning": "街", "examples": [], "sub_entries": []}, {"num": 12, "word": "very", "phonetic": "[ˈveri]", "pos": "adv.", "meaning": "很，非常地", "examples": [{"en": "My neighbors are very noisy.", "zh": "我的邻居非常吵。"}], "sub_entries": []}, {"num": 13, "word": "nice", "phonetic": "[naɪs]", "pos": "a.", "meaning": "好的；善良的", "examples": [], "sub_entries": []}, {"num": 14, "word": "lucky", "phonetic": "[ˈlakr]", "pos": "a.", "meaning": "幸运的", "examples": [{"en": "The lucky boy has a new bicycle.", "zh": "那个幸运的男孩有一辆新的自行车。"}], "sub_entries": []}, {"num": 15, "word": "such", "phonetic": "[sat]", "pos": "a.", "meaning": "如此的，那样的", "examples": [{"en": "Today is such a beautiful day.", "zh": "今天天气真好。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍表示“有“的have 及thereis 的用法，并介 绍所有格代词，及表示“也”的副词too及also的使 用区别。", "items": [{"num": 1, "title": "Ihave a good friend．我有个好朋友。", "body": ["注意:", "a. have是及物动词，表示“有”的意思。使用have 时，主语一定是表示“人或动物”的名词或代词。", "例： John has two dogs.（约翰有两条狗。）", "They have many friends.（他们有很多朋友。）", "b. 在Lesson1中我们會提到\"There is..\"\"There are..\"亦表示“有”的意思，但用法与have不 同。初学英语的读者很容易犯下列错误：", "中文：房间里有个男孩。英文：In the room has a boy.（×)理由：In the room是表示场所的短语，不能作主 语，使用时应于句首置Thereis或There are，然后置名词，再将表示场所的短语置 于句尾。此时就须改为下面的句子结构：", "There is a boy in the room. (○)（房间里有个男孩。）On the desk have three books.(x）", "→There are three books on the desk.(○)（桌上有三本书。）"]}, {"num": 2, "title": "Her name is Tina.", "body": ["（她叫蒂娜。）上句中的Her是所有格代词，作“她的”解。使用 时可将her 视为形容词，之后接名词。", "例：Mary is my classmate. Her English is very good.（玛丽是我同班同学。她的英文很棒。）", "我们可从下列表格及例句了解这些所有格代词的种类 及用法：", "数 单数 复数", "my（我的）", "our（我们的）", "your（你/你的）", "your（你们/你们的）", "所有格", "his（他的）", "their(他们的）", "代词", "her（她的）", "their（她们的）", "its（它的）", "their(它们的）", "例：That is my book.（那是我的书。）", "Their teacher is strict.（他们的老师很严。）John and his younger sister love their father.（约翰和他妹妹很爱他们的爸爸。）My dog wags its tail when it sees me.（我的小狗见到我时都会摇尾巴。）"]}, {"num": 3, "title": "Tony also has a dog.", "body": ["=Tony has a dog, too.（托尼也有条狗。）also与too均为副词，表示“也”的意思。但使用 时，too置于句尾，其前要有逗号。而also则置于一 般动词前；若与be动词或助动词并用时，则also 应置于该be动词或助动词之后。", "例：", "一般动词：He likes music. I also like it.", "=He likes music. I like it ，too.（他喜欢音乐。我也喜欢。）be 动词:He is a student. I am also a student.", "=He is a student. I am, too.（他是学生。我也是。）助动词：He can sing. I can also sing.", "=He can sing. I can, too.（他会唱歌。我也会）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 6, "title_en": "Is This Your Dog?", "title_zh": "这是你的狗吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mrs. Lee", "speaker_zh": "李太太", "en": "Is this your dog?", "zh": "这是你的狗吗？"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Yes, it is. Why?", "zh": "是的。怎么了？"}, {"speaker_en": "Mrs. Lee", "speaker_zh": "李太太", "en": "Well, your dog chases my cat.", "zh": "嗯，你的狗追我的猫。"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Oh, I'm sorry.", "zh": "噢，真抱歉。"}, {"speaker_en": "Mrs. Lee", "speaker_zh": "李太太", "en": "Please keep your dog on a leash.", "zh": "请把你的狗用皮带拴好。"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Yes, ma'am.", "zh": "是的，太太。"}]}, "vocab": [{"num": 1, "word": "why.", "phonetic": "[hwai/ wa1]", "pos": "adv.", "meaning": "为什么", "examples": [], "sub_entries": []}, {"num": 2, "word": "chase", "phonetic": "[tfes]", "pos": "vt.", "meaning": "追捕", "examples": [], "sub_entries": []}, {"num": 3, "word": "sorry", "phonetic": "[ˈsorn]", "pos": "a.", "meaning": "抱的，遗憾的", "examples": [], "sub_entries": []}, {"num": 4, "word": "please", "phonetic": "[pliz]", "pos": "adv.", "meaning": "请", "examples": [{"en": "Please open the door. (○) / Please you open the door. (×)", "zh": "请开门。（注意：千万不要造 Please you open the door 这种中式英文句子。）"}, {"en": "Open the door, please.", "zh": "请开门。"}], "sub_entries": ["please作“请”解时是个礼貌语，其用法有二：", "a. 置于句首，之后接动词原形。", "b. 置于句尾，之前加逗号。"]}, {"num": 5, "word": "keep", "phonetic": "[kip]", "pos": "vt.", "meaning": "&vi.保持（一种状态）", "examples": [], "sub_entries": []}, {"num": 6, "word": "leash", "phonetic": "[lij]", "pos": "n.", "meaning": "（系狗的）皮带", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请于下列空格填入适当的字", "questions": ["I", "1", "a sister.", "2", "name is Patty. I also", "3", "a brother.", "4", "nameisJohn.We", "two neighbors.", "6", "names are Tim and Ted. Tim", "has a", "dog.", "7", "tail is beautiful. Ted has a cat.", "8", "eyes are big. We all like Tim and Ted. They", "are", "9", "good neighbors."], "answers": ["解答1.have", "2.Her 3.have 4.His", "5.have", "6.Their 7. Its", "8.Its", "9.our"]}}, {"num": 7, "title_en": "Tony and Tina", "title_zh": "托尼和蒂娜", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Tony and Tina are very different. Tony likes music. Tina doesn't. Tony is an athlete. Tina isn't. On the other hand, Tina likes movies, but Tony doesn't. She is a good student, but he isn't. Tony and Tina are brother and sister, but are they alike? No, they aren't. They're very different."], "zh": ["托尼和蒂娜非常不同·托尼喜欢音乐，蒂娜却不喜欢·托尼是个运动员，蒂娜则不是。另一方面，蒂娜喜欢电影，但托尼则不喜欢。她是好学生，但他却不是。托尼和蒂娜是兄妹，但他们相似吗？不，他们不相似。他们大不相同。"]}, "dialog": null, "vocab": [{"num": 1, "word": "different", "phonetic": "[ˈdifarant]", "pos": "a.", "meaning": "不同的", "examples": [{"en": "A horse and a mule are very different.", "zh": "马和骡大不相同。"}], "sub_entries": []}, {"num": 2, "word": "like", "phonetic": "[laik]", "pos": "vt.", "meaning": "喜欢", "examples": [{"en": "The little boy likes ice cream very much.", "zh": "那小男孩很喜欢冰淇淋。"}], "sub_entries": []}, {"num": 3, "word": "music", "phonetic": "[ˈmjuzik]", "pos": "n.", "meaning": "音乐（不可数）", "examples": [], "sub_entries": []}, {"num": 4, "word": "athlete", "phonetic": "[ˈθlit]", "pos": "n.", "meaning": "运动员", "examples": [], "sub_entries": []}, {"num": 5, "word": "movie", "phonetic": "[ˈmuv1]", "pos": "n.", "meaning": "电影", "examples": [], "sub_entries": []}, {"num": 6, "word": "but", "phonetic": "[bat]", "pos": "conj.", "meaning": "但是", "examples": [], "sub_entries": [": Fred is poor, but he is happy.", "（弗雷德很穷，但他却很快乐。）"]}, {"num": 7, "word": "alike", "phonetic": "[alark]", "pos": "a.", "meaning": "相同的，相似的", "examples": [], "sub_entries": ["使用本单词时，不可置于名词前。", ": John and Peter are alike brothers.(×)", "→John and Peter are alike in many ways.(○)", "（约翰和彼得在许多方面很相似。）"]}], "grammar": {"intro": "本课介绍省略句的形成，不定冠词a及an的用法，介 词短语ontheotherhand的用法，及表示相对关系的 名词之前省略冠词的用法。", "items": [{"num": 1, "title": "Tony likes music. Tina doesn't.", "body": ["（托尼喜欢音乐，蒂娜却不喜欢。）Tony is an athlete. Tina isn't.（托尼是个运动员，蒂娜则不是。）以上两句中的\"Tina doesn't.”及\"Tina isn't.”均为 省略句。省略句的功能就是省略两句重复的部分，使 句子结构简单又不失清楚的涵义。省略句形成的先决 条件是：", "a. 两句的结构必须相同（亦即两句有相同的时态及动", "词），第二句方可形成省略句。", "b. 第一句若为肯定句，第二句则为否定句；第一句若 为否定句，第二句则为肯定句。形态有三：", "a. be动词", "例: He is a good student. She is not a good student.", "-> He is a good student. She isn't.", "=He is a good student, but she isn't.（他是好学生，但她却不是。）", "b. 助动词（如can、will等）", "例：He cannot do it. She can do it.", "--→ He cannot do it. She can.", "=He cannot do it, but she can.（他不能做这事，但她却能。）", "c. 动词", "此时省略句要按主语的人称分置助动词do或 does，用来代替第一句中的动词。", "例：He likes music. I do not like music.", "→He likes music. I don't.", "= He likes music, but I don't.（他喜欢音乐，但我却不喜欢。）I do not like music. He likes music.-I do not like music. He does.", "=I don't like music, but he does.（我不喜欢音乐，但他却喜欢。）"]}, {"num": 2, "title": "Tony is an athlete.", "body": ["（托尼是个运动员。）注意上句名词athlete之前的冠词是an 而非a。a．一般而言，可数名词若为单数形时，之前要有不定 冠词（a，an）表示单数的概念。", "例:This is book.（×）", "→This is a book.(○)（这是本书。）There is an ox there. (×)-→ There is an ox there. (○)（那里有只公牛。）", "b. a 置于辅音起首的单词前，而 an 则置于元音起首 的单词前。book [ buk ], ox [ aks ], athlete ['æθlit]由上列音标得知book 起首为辅音，ox与 athlete 为元音，故应说abook、anox、an athlete。"]}, {"num": 3, "title": "On the other hand, Tina likes movies, but Tony doesn't.", "body": ["（另一方面，蒂娜喜欢电影，但托尼则不喜欢。）on theotherhand是介词短语，表示“另一方面来 说”或“话又说回来”，有副词的功能，通常置于句 首，修饰整个句子。", "例：He is poor at English. On the other hand, he speaks French very well.（他英文很差。但话又说回来，他法语讲得很 好。）"]}, {"num": 4, "title": "Tina doesn't.（蒂娜则不。）", "body": ["=Tina does not. Tina isn't.（蒂娜不是。）", "=Tina is not. No，they aren't.（不，他们不是。）", "=No, they are not. They'revery different.（他们大不相同。）", "=They _are very different. 以上各句旨在强调be动词及助动词do（与I、they丶you、we或其他复数主语并用）、does（与 he、she、it 或其他单数主语并用）与not的缩写 形·这种缩写在英文的写作或口语中极为普遍。", "a. be动词与not并用时：", "is not→isn't [ˈɪznt]are not → aren't [ɑrnt]am not 无缩写形。：He is not a teacher.", "=He isn't a teacher.（他不是老师。）", "They are not happy.", "=They aren't happy.（他们不快乐。）", "b. do、does与not并用时：", "do not → don't [don't], does not → doesn't [ˈdʌznt] 1.usaop ← 1ou saop: They do not like music.", "=They don't like music.（他们不喜欢音乐。）", "I do not like coffee.", "=I don't like coffee.（我不喜欢咖啡。）", "She does not like tea.", "=She doesn't like tea.（她不喜欢茶。）"]}, {"num": 5, "title": "They are brother and sister.", "body": ["（他们是兄妹／姐弟。）上句中brother与sister是可数名词，照理本句应 为：", "They are a brother and a sister. 但两个名词所表示的是相对的关系，如父子、兄妹、母子等，这些名词之前的不定冠词就应省略·故我们 应说：", "They are | brother and sister. mother and son. father and daughter. teacher and student.（他们是兄妹／母子／父女／师生。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 8, "title_en": "Do You Speak Spanish?", "title_zh": "你会说西班牙语吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Joe", "speaker_zh": "乔", "en": "Do you speak Spanish?", "zh": "你会说西班牙语吗？"}, {"speaker_en": "Jeannie", "speaker_zh": "吉妮", "en": "No, I don't.", "zh": "我不会。"}, {"speaker_en": "Joe", "speaker_zh": "乔", "en": "Does he speak Spanish?", "zh": "他会说西班牙语吗？"}, {"speaker_en": "Jeannie", "speaker_zh": "吉妮", "en": "Yes, he does.", "zh": "是的，他会。"}, {"speaker_en": "Joe", "speaker_zh": "乔", "en": "Is he from Spain?", "zh": "他是西班牙人吗？"}, {"speaker_en": "Jeannie", "speaker_zh": "吉妮", "en": "No, he isn't. He's from Mexico.", "zh": "不，他不是。他是墨西哥人。"}]}, "vocab": [{"num": 1, "word": "speak", "phonetic": "[spik]", "pos": "vt.", "meaning": "说（某种语言）", "examples": [], "sub_entries": []}, {"num": 2, "word": "Spanish", "phonetic": "[ˈspanj]", "pos": "n.", "meaning": "西班牙语", "examples": [], "sub_entries": []}, {"num": 3, "word": "Spain", "phonetic": "[spen]", "pos": "n.", "meaning": "西班牙", "examples": [], "sub_entries": []}, {"num": 4, "word": "Mexico", "phonetic": "[ˈmeksi.ko]", "pos": "n.", "meaning": "墨西哥", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请于下列空格填入适当的字", "questions": ["Bob and Carl are brothers, but they", "1", "different. Bob", "2", "quiet. Carl _3_. Carl watches", "TV. Bob", "4. Bob reads books. Carl", "5.Bob", "and", "6", "teacherarefriends. Carland", "7", "teacher", "8"], "answers": ["解答1.are", "2.is", "3. isn't", "4. doesn't", "5.doesn't", "6.his", "7. his", "8. aren't"]}}, {"num": 9, "title_en": "A Busy Family", "title_zh": "忙碌的家庭", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["It's a busy day at the Wangs' house. Mr. Wang is fixing his bike. Mrs. Wang is writing a letter. Tina is reading a book. Tony is exercising. Even the dog is busy. It's chasing a cat. The cat is running for its life. The Wangs are busy, but they're having fun."], "zh": ["王家今天很忙·王先生在修他的自行车。王太太在写信。蒂娜在看书。托尼在运动。甚至狗也很忙碌。它在追一只猫。猫在逃命。王氏一家人很忙，但他们都很愉快。"]}, "dialog": null, "vocab": [{"num": 1, "word": "busy", "phonetic": "[bizi]", "pos": "a.", "meaning": "忙碌的", "examples": [{"en": "I am busy with my work.", "zh": "我忙着工作。"}], "sub_entries": []}, {"num": 2, "word": "day", "phonetic": "[de]", "pos": "n.", "meaning": "日子", "examples": [], "sub_entries": []}, {"num": 3, "word": "house", "phonetic": "[haʊs]", "pos": "n.", "meaning": "房子", "examples": [], "sub_entries": []}, {"num": 4, "word": "fix", "phonetic": "[fiks]", "pos": "vt.", "meaning": "修理", "examples": [{"en": "My uncle is fixing my broken watch.", "zh": "我叔叔正在修理我坏掉的手表。"}], "sub_entries": []}, {"num": 5, "word": "bike", "phonetic": "[baik]", "pos": "n.", "meaning": "自行车（=bicycle['baisikl])", "examples": [], "sub_entries": []}, {"num": 6, "word": "write", "phonetic": "[rait]", "pos": "vt.", "meaning": "写", "examples": [{"en": "I am writing a letter to my friend.", "zh": "我正在写信给我的朋友。"}], "sub_entries": []}, {"num": 7, "word": "letter", "phonetic": "[let]", "pos": "n.", "meaning": "信", "examples": [], "sub_entries": []}, {"num": 8, "word": "read", "phonetic": "[rid]", "pos": "vt.", "meaning": "阅读，看（文章、书等）", "examples": [{"en": "My father is reading the newspaper.", "zh": "我的父亲正在看报纸。"}], "sub_entries": []}, {"num": 9, "word": "book", "phonetic": "[buk]", "pos": "n.", "meaning": "书", "examples": [], "sub_entries": []}, {"num": 10, "word": "exercise", "phonetic": "[ˈcksa.saiz]", "pos": "vi.", "meaning": "运动", "examples": [{"en": "I exercise in the park every morning.", "zh": "我每天早上都到公园运动。"}], "sub_entries": []}, {"num": 11, "word": "even", "phonetic": "[ˈivan]", "pos": "adv.", "meaning": "甚至", "examples": [{"en": "Even father likes ice cream.", "zh": "甚至连我父亲都喜欢冰淇淋。"}], "sub_entries": []}, {"num": 12, "word": "chase", "phonetic": "[tes]", "pos": "vt.", "meaning": "追逐", "examples": [{"en": "The policeman is chasing the thief.", "zh": "警察在追小偷。"}], "sub_entries": []}, {"num": 13, "word": "cat", "phonetic": "[kat]", "pos": "n.", "meaning": "猫", "examples": [], "sub_entries": []}, {"num": 14, "word": "run", "phonetic": "[ran]", "pos": "vi.", "meaning": "跑", "examples": [], "sub_entries": []}, {"num": 15, "word": "life", "phonetic": "[laif]", "pos": "n.", "meaning": "生命", "examples": [], "sub_entries": []}, {"num": 16, "word": "fun", "phonetic": "[fn]", "pos": "n.", "meaning": "乐趣（不可数）", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课主要介绍现在进行时的形成及用法，并介绍其他相关 的重点。", "items": [{"num": 1, "title": "It's a busy day at the Wangs' house.", "body": ["（王家今天很忙。）", "a. It's a busy day.", "= It is a busy day. （今天是一个忙碌的日子。）", "此处的It是代词，用来代替“今天”、“此刻”。常用于\"It is + 时间名词\"的句子结构中。", "例: It's Monday. （今天是星期一。）", "例: What time is it? （现在几点了？）", "例: It's ten o'clock. （现在是10点钟。）", "b. at the Wangs' house 在王家的住所", "在上列短语中，at[æt]是介词，表示“在...之处”的意思。之后所接的宾语，多为表示家（house）、车站（station）、邮局（post office）、杂货店（grocery store）等建筑物的名词。", "例：There are many people at the train station. （火车站有好多人。）", "c. the Wangs' house 王家的住所", "the Wangs'是所有格，译成“王氏一家人的”，相当于所有格代词their（他们的）。专有名词（如John、Peter）或表示“人”的普通名词（如my father、the boy）形成所有格时，要在这些专有名词或普通名词之后加\"'s\"，之后再接名词，即：", "John's book（约翰的书）", "my father's work（我父亲的工作）", "the boy's dog（这个男孩的狗）", "但专有名词或普通名词之后有\"s\"形成复数时，则表示所有格的符号\"'\"应置于“s”之后，即：", "the Lins' house（林家）", "the boys' father（这些男孩子们的父亲）", "故我们应说\"the Wangs' house\"，而非\"the Wang's house\"。"]}, {"num": 2, "title": "Mr. Wang is fixing his bike.", "body": ["（王先生在修他的自行车。）", "Mrs. Wang is writing a letter. （王太太在写信。）", "以上两句均属动词时态中现在进行时的句型。这种时态相当于中文“现在正在...”的意思，形成的方式如下：", "主词 + am / is / are + 现在分词", "a. 在造例句之前，我们得先谈谈现在分词的形成方式：", "动词原形加-ing → 现在分词", "1）绝大部分的动词原形可直接加-ing即成现在分词，如：", "do（做）→ doing", "teach（教书）→ teaching", "2）但若动词原形以不发音的e结尾时，要先删除e，再加-ing，如：", "write[rait]（写）→ writing", "chase[tʃes]（追逐）→ chasing", "make[mek]（制造）→ making", "3）若动词原形为单音短音节，且以一个辅音字母结尾时，应将该字母双写，再加-ing，如：", "run[rʌn]（跑）→ running", "sit[sɪt]（坐）→ sitting", "b. 有了以上了解后，我们现在就可造出下列现在进行时的例子：", "Mary is writing a letter. （玛丽正在写信。）", "They are doing their homework. （他们正在做功课。）", "I am running in the yard. （我正在院子里跑步。）"]}, {"num": 3, "title": "...but they're having fun.（·..….但他们很愉快。）", "body": ["have fun是固定的用语，表示“玩得愉快”、“过得愉快”之意，可不要逐字翻译成“有乐趣”。\"they're having fun.\"是现在进行时，照理应译成“他们现在正玩得愉快”，但此处为求译文顺畅，只译成“他们很愉快”即可。", "例：I have fun every day. （我每天都过得很愉快。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 10, "title_en": "What Are You Doing?", "title_zh": "你在做什么？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "Hi, Bob. What are you doing?", "zh": "嗨，鲍勃。你在做什么？"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "I'm watching TV. How about you?", "zh": "我在看电视。你呢？"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "I'm doing my homework.", "zh": "我在做功课。"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "You are a good student, Betty. 贝蒂和鲍勃在讲电话。", "zh": "贝蒂，你是个好学生。"}]}, "vocab": [{"num": 1, "word": "watch", "phonetic": "[watf]", "pos": "vt.", "meaning": "看，观赏（电视、比赛等）", "examples": [], "sub_entries": []}, {"num": 2, "word": "TV", "phonetic": "[ˈtiˈvi]", "pos": "n.", "meaning": "电视（television [ˈteləˌvɪʒən] 的缩写形）", "examples": [], "sub_entries": []}, {"num": 3, "word": "homework", "phonetic": "[ˈhoʊmwɜːrk]", "pos": "n.", "meaning": "家庭作业（不可数）", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请于下列空格中填入适当的字", "questions": ["The Wangs", "1_in the park. Mr. Wang is", "a magazine. Mrs. Wang is 3a", "a song. Tony", "and 4friends are5baseball. Tina is6a", "letter. Rover is 7a cat. Everyone is 8fun in", "the park, except the cat."], "answers": ["解答1.are", "2.reading", "3. singing", "4.his", "5. playing", "6.writing(或reading)", "7. chasing", "8. having"]}}, {"num": 11, "title_en": "My Foreign Classmates", "title_zh": "我的外籍同学", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["There are several foreign students in my class. John is American. He's from the United States. Laura is Spanish. She's from Spain. Chen and Huang are Chinese, but they are not from China. They're from Malaysia. They're overseas Chinese. We're from different countries, but we all get along well."], "zh": ["我班上有几名外籍学生。约翰是美国人。他来自美国·劳拉是西班牙人。她来自西班牙。小陈和小黄是中国人，但他们却非来自中国。他们来自马来西亚。他们是华侨。我们来自不同的国家，不过我们都相处得很好。"]}, "dialog": null, "vocab": [{"num": 1, "word": "foreign", "phonetic": "[forin]", "pos": "a.", "meaning": "外国的，外籍的", "examples": [{"en": "I like to see foreign movies.", "zh": "我喜欢看外国电影。"}], "sub_entries": []}, {"num": 2, "word": "classmate", "phonetic": "[klas.met]", "pos": "n.", "meaning": "同班同学", "examples": [], "sub_entries": []}, {"num": 3, "word": "several", "phonetic": "[ˈssvaral]", "pos": "a.", "meaning": "儿个的", "examples": [{"en": "There are several Americans in my class.", "zh": "我的班上有好几个美国人。"}], "sub_entries": []}, {"num": 4, "word": "class", "phonetic": "[klaes]", "pos": "n.", "meaning": "班级", "examples": [], "sub_entries": []}, {"num": 5, "word": "American", "phonetic": "[aˈmerikan]", "pos": "a.", "meaning": "美国籍的", "examples": [], "sub_entries": []}, {"num": 6, "word": "the United States (of America)", "phonetic": "", "pos": "短语", "meaning": "美利坚合众国，美国", "examples": [], "sub_entries": ["united [juˈnaɪtɪd]a.联合的", "state[stet]n.美国的一州", "美国全名称为 the United States of America。.-般", "均以 the United States、the States 或 the U.S.", "称呼。"]}, {"num": 7, "word": "Spanish", "phonetic": "[ˈspenf]", "pos": "a.", "meaning": "西班牙籍的", "examples": [], "sub_entries": []}, {"num": 8, "word": "Spain", "phonetic": "[spen]", "pos": "n.", "meaning": "西班牙", "examples": [], "sub_entries": []}, {"num": 9, "word": "Chinese", "phonetic": "[tjalˈniz]", "pos": "a.", "meaning": "中国籍的", "examples": [], "sub_entries": []}, {"num": 10, "word": "China", "phonetic": "[ˈtfaina]", "pos": "n.", "meaning": "中国]", "examples": [], "sub_entries": []}, {"num": 11, "word": "Malaysia", "phonetic": "[male3a]", "pos": "n.", "meaning": "马来西亚", "examples": [], "sub_entries": []}, {"num": 12, "word": "overseas", "phonetic": "[.ovaˈsiz]", "pos": "a.", "meaning": "在海外的", "examples": [{"en": "Amy is an overseas student.", "zh": "艾米是-一个留学生。"}], "sub_entries": []}, {"num": 13, "word": "country", "phonetic": "[ˈkantri]", "pos": "n.", "meaning": "国家", "examples": [{"en": "I love my country.", "zh": "我爱我的国家。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍表示国籍的说法。", "items": [{"num": 1, "title": "John is American.", "body": ["（约翰是美国人。）", "Laura is Spanish.（劳拉是西班牙人。）Chen and Huang are Chinese.（小陈和小黄是中国人。）上列三句中，American、Spanish与Chinese 均作 形容词，分别表示“美国籍的”、“西班牙籍的”““中国籍的”；但American与Chinese均可作可数 名词，此时之前应分别置不定冠词\"an\"和\"a\"，即 an American（美国人）、a Chinese（中国人），但American 的复数形为Americans，而Chinese 的复数形仍为Chinese。", "例：John is American.（American为形容词）", "=John is an American.（American为名词）（约翰是美国人。）They are American.（American为形容词）", "=They are Americans.(Americans 为名词）（他们是美国人。）Peter is Chinese.(Chinese为形容词）", "=Peter is Chinese.（Chinese为名词）（彼得是中国人。）They are Chinese.（Chinese 为形容词，亦可 视作复数名词）（他们是中国人。）I see five Chinese there.（Chinese为复数名 词）（我看到那边有五个中国人。）但Spanish只作形容词用，故：", "He is a Spanish.（×)", "→ He is Spanish.（○)（他是西班牙人。）I see five Spanish there.（x）-→I see five Spanish people there. (○)（我看到那里有五名西班牙人。）因此为了避免犯类似上面的错误，英美人士多用国籍 的形容词来表示某人是哪一国人。", "例：He is British.", "They are British.（他／他们是英国人。）We are Danish.（我们是丹麦人。）"]}, {"num": 2, "title": "She's from Spain.", "body": ["=She is from Spain.（她来自西班牙。）", "They're from Malaysia.", "=They are from Malaysia.（他们来自马来西亚。）以上两句中的 She's及They're分别等于She is及 Theyare。人称代词作主语与be动词并用时，可采 下列缩写形，这些缩写形在口语中最为常用：", "I am →I'm [aim ]我是 you are -→ you're [ jur ]你是／你们是 he is →he's [hiz ]他是 she is →she's [Jiz ]她是 it is → it's [ its ]它是 we are →we're [ wir ]我们是 they are→they're[er ]他们是", "例: I am not a student.", "= I'm not a student.（我不是学生。）", "He is a good teacher.", "= He's a good teacher.（他是好老师。）", "It is a beautiful dog.", "= It's a beautiful dog.（它是只很漂亮的狗。）"]}, {"num": 3, "title": "...but we all get along well.", "body": ["（...·….不过我们都相处得很好。）以上这两短语却有两个语法重点，兹分述如下：", "a. we all我们大家", "此处的all[ol]是形容词，译成“全部的”或“所 有的”，修饰三个或三个以上的人或东西。与代词 并用时，置于该代词之后；与普通名词并用时，通 常置于该普通名词前；与专有名词并用时，通常置 于该专有名词之后。", "1）代词：", "例: They all like music.（他们都喜欢音乐。）", "I like them all.（他们我全都喜欢。）", "2）普通名词：", ": All the boys like music.（这些男孩都喜欢音乐。）", "3）专有名词：", "：Peter, Paul and Mary all like music.（彼得、保罗和玛丽全都喜欢音乐。）both[boθ]亦是形容词，用来修饰两个的人或东 西，可译成“二者都”。", "例: John and Peter are good friends. They both like music.（约翰和彼得是好朋友。他们两个都喜欢音 乐。）", "All my parents can sing.（×，本句话暗示 可能有两爸·一妈或三爸五妈的）", "→ Both my parents can sing. (○)（我父母都会唱歌。）", "b. get along 相处(along[alon])这个短语之后亦可接介词with，再接人作宾语，即：", "get along with+人 与某人相处", "例: He has a bad temper. I can't get along with him.（他脾气坏。我没法与他相处。）", "Do you and your sister get along well?（你和你妹妹处得好吗？）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 12, "title_en": "Where's Chen from?", "title_zh": "小陈是哪一国人？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "A", "speaker_zh": "甲", "en": "Where's Chen from?", "zh": "小陈是哪一国人？"}, {"speaker_en": "B", "speaker_zh": "乙", "en": "He's from Malaysia.", "zh": "他是马来西亚人。"}, {"speaker_en": "A", "speaker_zh": "甲", "en": "Really? He looks Chinese.", "zh": "真的吗？他看起来像中国人。"}, {"speaker_en": "B", "speaker_zh": "乙", "en": "As a matter of fact, he is Chinese, but he really is from Malaysia.", "zh": "事实上，他是中国人，不过他来自马来西亚。"}, {"speaker_en": "A", "speaker_zh": "甲", "en": "That's very interesting.", "zh": "真有趣。"}]}, "vocab": [{"num": 1, "word": "really", "phonetic": "[ˈriali]", "pos": "adv.", "meaning": "真正地", "examples": [], "sub_entries": []}, {"num": 2, "word": "look", "phonetic": "[lʊk]", "pos": "vi.", "meaning": "看起来（之后接形容词）", "examples": [{"en": "He looks happy today.", "zh": "他今天看起来很快乐。"}], "sub_entries": []}, {"num": 3, "word": "as a matter of fact", "phonetic": "", "pos": "短语", "meaning": "事实上", "examples": [{"en": "He knows many English words. As a matter of fact, he is a walking dictionary.", "zh": "他英文单词懂得很多。事实上，他是本活字典。"}], "sub_entries": ["本短语有副词的功能，使用时常置于句首，再置逗号，", "修饰之后的整个句子。"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请于下列空格填入适当的字", "questions": ["I", "1", "many foreign friends. Bill", "2", "from", "England.He's_3", "3.Sue is from4.", "She's Mexican. Todd and Larry", "from Brazil.", "6", "Brazilian.We're fromdifferent7_，but", "8", "all good", "friends."], "answers": ["解答1.have", "2.is（或comes)", "3. Britishi", "4. Mexico", "5.are（或come)", "6. They're", "7. countries", "8. we're"]}}, {"num": 13, "title_en": "Nobody Is at Home", "title_zh": "没人在家", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Nobody is at home at the Wangs' house. Mr. Wang is working in his office. Mrs. Wang is shopping at the supermarket. Tony is sitting on the bus. He's on his way to the gym. Tina is studying at the library. Rover is not at home, either. It's running around the neighborhood. It's not chasing Mrs. Lee's cat. It's chasing Mrs. Lee!"], "zh": ["王家没有一个人在家。王先生正在办公室工作。王太太正在超级市场买东西·托尼正坐在公共汽车上。他正往健身房去·蒂娜正在图书馆看书。狗儿来福也不在家。它正在住处附近到处跑。它并不是在追李太太的猫。它是在追李太太！"]}, "dialog": null, "vocab": [{"num": 1, "word": "nobody", "phonetic": "[ˈno.bad1]", "pos": "pron.", "meaning": "没有人", "examples": [{"en": "Nobody likes a liar.", "zh": "谁都不喜欢撒谎的人。"}], "sub_entries": []}, {"num": 2, "word": "home", "phonetic": "[hom]", "pos": "n.", "meaning": "家", "examples": [{"en": "Nobody is at home today.", "zh": "今天没有人在家。"}], "sub_entries": []}, {"num": 3, "word": "office", "phonetic": "[ˈsfis]", "pos": "n.", "meaning": "办公室", "examples": [], "sub_entries": []}, {"num": 4, "word": "shop", "phonetic": "[ʃap]", "pos": "vi.", "meaning": "购物，买东西", "examples": [{"en": "She is shopping a new dress. (×) -→ She is shopping for a new dress. (○)", "zh": "她正在选购一件新服装。"}], "sub_entries": []}, {"num": 5, "word": "supermarket", "phonetic": "[ˈsupa.markit]", "pos": "n.", "meaning": "超级市场", "examples": [], "sub_entries": []}, {"num": 6, "word": "sit", "phonetic": "[sit]", "pos": "vi.", "meaning": "坐", "examples": [], "sub_entries": [": Father is sitting on the sofa.", "（父亲正坐在沙发上。）"]}, {"num": 7, "word": "bus", "phonetic": "[bas]", "pos": "n.", "meaning": "公共汽车，巴士", "examples": [{"en": "He takes the bus to work every day.", "zh": "他每天搭公共汽车上班。"}], "sub_entries": []}, {"num": 8, "word": "way", "phonetic": "[we]", "pos": "n.", "meaning": "方向，路线", "examples": [], "sub_entries": []}, {"num": 9, "word": "gym", "phonetic": "[d3im]", "pos": "n.", "meaning": "健身房，体育馆", "examples": [], "sub_entries": []}, {"num": 10, "word": "study", "phonetic": "[ˈstadr]", "pos": "vi.", "meaning": "念书，看书", "examples": [{"en": "I seldom study at home.", "zh": "我很少在家里看书。"}], "sub_entries": []}, {"num": 11, "word": "library", "phonetic": "[ˈlai.brsr1]", "pos": "n.", "meaning": "图书馆", "examples": [{"en": "I am going to the library to study.", "zh": "我正要去图书馆看书。"}], "sub_entries": []}, {"num": 12, "word": "either", "phonetic": "[io]", "pos": "adv.", "meaning": "也", "examples": [{"en": "Mary is beautiful. Jane is, too. : He isn't happy. She isn't, either.", "zh": "玛丽很漂亮，简也很漂亮。）b.either 用于含有not的否定句中，置于句尾，either之前置逗号。（他不快乐，她也不快乐。"}], "sub_entries": []}, {"num": 13, "word": "neighborhood", "phonetic": "[ˈneba.hud]", "pos": "n.", "meaning": "住处附近", "examples": [{"en": "There is a high school in my neighborhood.", "zh": "我家附近有一所高中。"}], "sub_entries": []}], "grammar": {"intro": "本课为读者介绍现在进行时的用法，并介绍及物动词与 不及物动词的区别方法。", "items": [{"num": 1, "title": "现在进行时的基本句型", "body": ["为使读者进一步熟悉现在进行时的用法，此处再强调一次，现在进行时的句型为：", "主语+am/are/is+现在分词", "例：They're chatting in the living room.（他们正在客厅内聊天。）"]}, {"num": 2, "title": "及物动词（vt.）与不及物动词（vi.）的区别", "body": ["本课中的现在分词 working、shopping、sitting、studying、running、chasing 均是由动词原形 work（工作）、shop（购物）、sit（坐）、study（看书）、run（跑）、chase（追）变化而成。这些动词除 chase 是及物动词外，其他均为不及物动词。及物动词须接宾语，意思才算完整；不及物动词本身意思即已完整，之后无须加宾语。", "例： I work every day.", "Svi. adv.（我每天工作。）They like music. vt. 0（他们喜欢音乐。）*\"S\"指主语（Subject）。\"vi.\"指不及物动词（intransitive verb）。\"adv.”指副词（adverb）。\"vt.\"指及物动词（transitive verb）。\"O”指宾语（Object）。初学英语的读者单凭上面的定义及例句可能仍无法了 解及物动词与不及物动词的区别。别急，我们可用下 面的步骤帮助读者清晰了解这两种动词的不同：", "第一步：先在心中想出下列的句型：", "A B。B被A A及B可代表任何指人或物的名词或代 词·即A或B可代表“我”、“约翰”“狗”、“书”、“钱”等。第二步：在上列空格中填人任何一个动词，然后将两 句译成中文，如果意思通顺，该动词就是及 物动词，否则就是不及物动词。我们现在用like（喜欢）作示范。此时我们 将A代表“我”，B代表“音乐”，即成：", "我like（喜欢）音乐。音乐被我like（喜欢）。以上译文通顺，得知like是及物动词。同理：", "狗chase（追）我。我被狗chase（追）。以上译文通顺，得知chase是及物动词。又例：我work（工作）他。他被我work（工作）。译文：我工作他·他被我工作。以上译文不通顺，得知work是不及物动词。以上的两个步骤是帮助我们区别及物动词与不及物动 词的简略方法，但并非完全精确。请看下例：", "我sit（坐）椅子。椅子被我sit（坐）。以上译文虽尚称通顺，但sit并非及物动词，而是不 及物动词，因为sit之后要接介词on（表示坐在无扶 手的椅子上面）或in（表示坐在有扶手的椅子里面），再接宾语。：He is sitting on the chair.（他正坐在椅子上。）He is sitting in the armchair.（他正坐在扶手椅里。）因此，要精确了解及物动词与不及物动词的区别，最 好的方法是勤看文章，勤查字典。"]}, {"num": 3, "title": "及物动词与不及物动词的基本句型", "body": ["已知及物动词和不及物动词的区别后，就应该知道这两个动词的用法：", "主语+及物动词（vt.)+宾语（O)主语+不及物动词(vi.)", "例：They often watch TV.", "adv.vt.（他们经常看电视。）She dances well. vi.adv.（她舞跳得很好。）以上两例中的often（经常）、well（很好）均是副 词，在句中用来修饰动词。"]}, {"num": 4, "title": "Nobody is at home at the Wangs'house.", "body": ["（王家没有一个人在家。）beathome是个固定用法，表示“在家里”的意 思。'：He is at home now.（他现在在家里。）"]}, {"num": 5, "title": "Mr. Wang is working in his office.", "body": ["（王先生正在办公室工作。）Mrs. Wang is shopping at the supermarket.（王太太正在超级市场买东西。）以上两句中的in及at均为介词，之后皆可用以表示 建筑物的名词作宾语；但in强调“在...…里面”，at则笼统指“在·…..…·地方”。：I will meet you at the library.（我会在图书馆和你见面。）*或在图书馆内，或在图书馆门口。", "I will meet you in the library.（我会在图书馆内和你见面。）"]}, {"num": 6, "title": "It's running around the neighborhood.", "body": ["（它正在住处附近到处跑。）around[a'raund]prep.围绕", "例: The children are sitting around the old man.（孩子们正围着老人而坐。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 14, "title_en": "Why Are You Smiling?", "title_zh": "你为什么在微笑？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Why are you smiling?", "zh": "你为什么在微笑？"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "I'm thinking about school.", "zh": "我正想到上学的事。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Why does that make you smile?", "zh": "为什么那会让你笑了起来呢？"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Because there is no school tomorrow.", "zh": "因为明天不上学。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Oh, I see.", "zh": "哦，我明白了。"}, {"speaker_en": "Tony", "speaker_zh": "托尼", "en": "Now you're smiling, too!", "zh": "现在你也在笑了！"}]}, "vocab": [{"num": 1, "word": "smile", "phonetic": "[smail]", "pos": "vi.", "meaning": "微笑（常与at并用）", "examples": [], "sub_entries": [": Look! The girl is smiling at you.", "（瞧！那位女孩在对着你笑呢。）"]}, {"num": 2, "word": "think ..", "phonetic": "", "pos": "about.", "meaning": "想到....", "examples": [], "sub_entries": [": Sue gets sad when she thinks about home.", "（苏一想到家就觉得很难过。）"]}, {"num": 3, "word": "make", "phonetic": "[mek]", "pos": "vt.", "meaning": "使，叫", "examples": [], "sub_entries": ["make+人+动词原形", "叫某人···", "Father makes me clean his bike every Sunday.", "（父亲叫我每个星期天擦洗他的自行车。）"]}, {"num": 4, "word": "I see.", "phonetic": "", "pos": "日常口语", "meaning": "我明白了。", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1.Tina is doing homework", "the library.", "(A) on", "(B) at", "(C) under", "(D) around", "2. Mrs. Wang is shopping", "(A) at the library", "(B) at the Wangs'house", "(C) at the gym", "(D) at the department store", "3. 1 am", "at the library.", "(A) reading (B) read (C) readed (D) reads", "4. They", "around the school yard.", "(A) are run", "(B) is running", "(C) are running", "(D) am running", "5. Mr. Wang", "in his office.", "(A) are reading", "(B) are working", "(C) am reading", "(D) is working", "6.Larry smiles when he thinks", "his girlfriend.", "(A) to(B) for", "(C) about (D) over"], "answers": ["解答→1.(B）2.(D）3.(A）4.(C）5.(D）6.(C)"]}}, {"num": 15, "title_en": "Mrs. Lee's Kitchen", "title_zh": "李太太的厨房", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["There are mice in Mrs. Lee's kitchen! There's a mouse  on the kitchen table. There's a mouse behind the stove. There are mice next to the refrigerator, under the sink and inside the cupboard! Why isn't Mrs. Lee's cat catching the mice? Because it's in a tree. It's staring at Rover with fear and shaking like a leaf."], "zh": ["李太太的厨房里有老鼠！厨房桌上有一只。炉子后面有一只。冰箱边、洗碗槽下，还有橱柜里面都有老鼠！李太太的猫为何不在抓这些老鼠呢？因为它在树上。它正惊恐地盯着狗儿来福，并且抖得很厉害。"]}, "dialog": null, "vocab": [{"num": 1, "word": "kitchen", "phonetic": "[ˈkitin]", "pos": "n.", "meaning": "厨房", "examples": [], "sub_entries": []}, {"num": 2, "word": "mouse", "phonetic": "[maus]", "pos": "n.", "meaning": "老鼠（单数）", "examples": [], "sub_entries": ["mice [maɪs] n. 老鼠（复数）", "a mouse 一只老鼠", "two mice 两只老鼠", "three mice 三只老鼠", "many mice 许多老鼠"]}, {"num": 3, "word": "table", "phonetic": "[ˈtebl]", "pos": "n.", "meaning": "桌子", "examples": [], "sub_entries": []}, {"num": 4, "word": "behind", "phonetic": "[brˈhaind]", "pos": "prep.", "meaning": "在....·后面", "examples": [{"en": "The little boy is standing behind a tall man.", "zh": "那个小男孩站在一个高大男子后面。"}], "sub_entries": []}, {"num": 5, "word": "stove", "phonetic": "[stov]", "pos": "n.", "meaning": "炉子", "examples": [], "sub_entries": []}, {"num": 6, "word": "next to...", "phonetic": "", "pos": "prep.", "meaning": "紧靠于...，在...旁边", "examples": [{"en": "There is a post office next to the bank.", "zh": "那家银行旁边有一个邮局。"}], "sub_entries": []}, {"num": 7, "word": "refrigerator", "phonetic": "[rˈfrid3a.reto]", "pos": "n.", "meaning": "电冰箱", "examples": [], "sub_entries": []}, {"num": 8, "word": "under", "phonetic": "[ˈanda]", "pos": "prep.", "meaning": "在.....下方", "examples": [{"en": "My shoes are under the bed.", "zh": "我的鞋子就在床下。"}], "sub_entries": []}, {"num": 9, "word": "sink", "phonetic": "[siɡk]", "pos": "n.", "meaning": "洗碗槽", "examples": [], "sub_entries": []}, {"num": 10, "word": "inside", "phonetic": "[nˈsaid]", "pos": "prep.", "meaning": "在......之内.", "examples": [{"en": "The lion is inside a cage.", "zh": "那只狮子在笼子里。"}], "sub_entries": []}, {"num": 11, "word": "cupboard", "phonetic": "[ˈkabad]", "pos": "n.", "meaning": "橱柜", "examples": [], "sub_entries": []}, {"num": 12, "word": "why", "phonetic": "[hwal／wa1]", "pos": "adv.", "meaning": "为什么", "examples": [{"en": "Why are you so sad?", "zh": "你为什么那么难过？"}], "sub_entries": []}, {"num": 13, "word": "catch", "phonetic": "[ket]", "pos": "vt.", "meaning": "抓，捕捉", "examples": [{"en": "The baseball player is catching the ball.", "zh": "那个棒球员正在接球。"}], "sub_entries": []}, {"num": 14, "word": "because", "phonetic": "[brˈkoz]", "pos": "conj.", "meaning": "因为", "examples": [{"en": "Tom is at home because he is sick.", "zh": "汤姆待在家里，因为他生病了。"}], "sub_entries": []}, {"num": 15, "word": "tree", "phonetic": "[tri]", "pos": "n.", "meaning": "树", "examples": [], "sub_entries": []}, {"num": 16, "word": "stare", "phonetic": "[ster]", "pos": "vi.", "meaning": "町，注视（常与at 并用）", "examples": [{"en": "It's rude to stare at people.", "zh": "盯着别人看是不礼貌的。"}], "sub_entries": ["stare at...", "盯着.·.·…."]}, {"num": 17, "word": "with", "phonetic": "[wio]", "pos": "prep.", "meaning": "有，带着", "examples": [], "sub_entries": []}, {"num": 18, "word": "fear", "phonetic": "[fr]", "pos": "n.", "meaning": "害怕，恐惧", "examples": [], "sub_entries": []}, {"num": 19, "word": "shake", "phonetic": "[∫ek]", "pos": "vi.", "meaning": "抖动", "examples": [], "sub_entries": []}, {"num": 20, "word": "leaf", "phonetic": "[lif]", "pos": "n.", "meaning": "叶子", "examples": [], "sub_entries": []}, {"num": 21, "word": "shake like a leaf", "phonetic": "", "pos": "短语", "meaning": "（因害怕、恐惧而）抖得很厉害", "examples": [{"en": "When I watch scary movies, I shake like a leaf.", "zh": "每次看恐怖电影时，我都吓得浑身发抖。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍介词与物体的关系，并介绍特殊问句的造句法。", "items": [{"num": 1, "title": "注意下列介词与物体的关系：", "body": ["inside+物体 在该物体之内", "=in+物体 behind+物体 在该物体的后面 under+物体 在该物体的下方 nextto+物体 紧邻于该物体", "例： There is a pen inside/in the box.（盒子里有支笔。）", "There is a dog behind the door.（门后有只狗。）He is standing under an umbrella.（他正站在雨伞下。）Mary is sitting next to the window.（玛丽正坐在窗边。）"]}, {"num": 2, "title": "There are mice in Mrs. Lee's kitchen!", "body": ["（李太太的厨房里有老鼠！）我们再复习一下Thereis/There are（有）与have/has（有）的用法。我们可用中文的句子清楚了解这些 用法。凡以人或动物作主语时，就要用have或has 作动词；凡以场所起首的句子，英文句首就应置 There is/There are 。", "例：中文：我有只手表。", "人 英文：Ihave a watch. 中文：这只猫直一根长尾巴。动物 英文:The cat has a long tail. 中文：客厅里有一个电冰箱。场所 英文：There is a refrigerator in the living room. 中文：书桌上有一本书和两枝铅笔。场所 英文: There are a book and two pencils on the desk."]}, {"num": 3, "title": "Why isn't Mrs. Lee's cat catching the mice?", "body": ["（李太太的猫为何不在抓这些老鼠呢？）本句是特殊问句。特殊问句就是用疑问副词why（为 什么）、when（何时）、how（如何）、where（何 处）或疑问代词who（谁，作主语）、whom（谁，作宾语）、what（什么）、which（哪个）等起首的 问句。由于特殊问句需要广泛的篇幅方能详细说明，我们将在往后的课文中逐步介绍·这里就疑问副词（why、when、how、where）形成的问句大略介绍 如下，以使读者对问句的造句有初步的了解：", "a. 疑问词一定置于问句句首。", "b. 问句要采用倒装句。", "1）原句有be动词时，该be动词要与主语倒装。", "例：中文：他为什么生气呢？", "英文：Why is he angry?（×）-→ Why is he angry? (○)中文：你为什么在哭呢？英文：You why are crying?（×）", "→ Why are you crying? (○)中文：他为什么不在做功课呢？英文: He why isn't doing his homework?（×）Why is not he doing his homework?（x)-→ Why isn't he doing his homework?(○)", "= Why is he not doing his homework? (○)", "2）原句有助动词如can（能）、will（将要）", "may（可以）等时，该助动词要与主语倒装。", "例：中文：你何时会来呢？", "英文：You when will come?（×）-→ When will you come? (○)中文：你如何做这件事呢？英文：You how can do it?（x）", "→How can you do it? (○)", "3）原句有一般动词时，一般动词与主语无法倒装，须按主语的人称在疑问词之后置do或does, 再将动词改为动词原形。", "例：中文：他住在什么地方？", "英文：He lives where?（×）Where he lives? (×)--→ Where does he live?(○)中文：他们为什么喜欢音乐？英文：Why do they like music?（×）", "→ Why do they like music? (○)"]}, {"num": 4, "title": "It's staring at Rover with fear.", "body": ["= It's staring at Rover fearfully.（它正惊恐地盯着来福。）上列第一句中with fear这个介词短语作副词用，等 于第二句中副词fearfully[firfali]，用以修饰已成 现在进行时短语动词的is staring at。"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 16, "title_en": "Where Are My Keys?", "title_zh": "我的钥匙在哪里？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Nick", "speaker_zh": "尼克", "en": "Where are my keys?", "zh": "我的钥匙在哪里？"}, {"speaker_en": "Sandy", "speaker_zh": "仙蒂", "en": "I don't know. Are they on the dresser?", "zh": "我不知道。它们是不是在化妆台上？"}, {"speaker_en": "Nick", "speaker_zh": "尼克", "en": "No, they aren't.", "zh": "没有，不在那里。"}, {"speaker_en": "Sandy", "speaker_zh": "仙蒂", "en": "Are they under the bed?", "zh": "是不是在床下？"}, {"speaker_en": "Nick", "speaker_zh": "尼克", "en": "No. Oh, here they are.", "zh": "没有。哦，它们在这里。"}, {"speaker_en": "Sandy", "speaker_zh": "仙蒂", "en": "Where?", "zh": "哪里？"}, {"speaker_en": "Nick", "speaker_zh": "尼克", "en": "In my pocket.", "zh": "在我的口袋里。"}]}, "vocab": [{"num": 1, "word": "key", "phonetic": "[ki]", "pos": "n.", "meaning": "钥匙", "examples": [], "sub_entries": []}, {"num": 2, "word": "dresser", "phonetic": "[ˈdresa]", "pos": "n.", "meaning": "化妆台", "examples": [], "sub_entries": []}, {"num": 3, "word": "Here", "phonetic": "", "pos": "", "meaning": "theyare．它们在这里。", "examples": [], "sub_entries": ["here[hir ] adv.这里"]}, {"num": 4, "word": "pocket", "phonetic": "[ˈpakit]", "pos": "n.", "meaning": "口袋", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Bill is sitting to the", "of Mary.", "(A) in", "(B) on", "(C) right", "(D) next to", "2. Why", "she washing the dishes?", "(A) isn't", "(B) is not", "(C) aren't (D) are not", "3. Larry is standing", "Mary and Jane.", "(A) in", "(B)between (C) left", "(D) inside", "4.Why aren't you", "his bicycle?", "(A) clean (B)ride", "(C) playing (D) fixing", "5. There is a trash can", "to the refrigerator.", "(A)between(B)next", "(C) at", "(D) behind", "6. What is that", "？", "(A)between thebed", "(B) in your pocket", "(C) to the left dresser(", "(D) in your keys"], "answers": ["解答>1.(C)2.(A)3.(B)4.(D）5.(B)6.(B)"]}}, {"num": 17, "title_en": "My Hometown", "title_zh": "我的家乡", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My hometown is not very modern, but it's beautiful. There is a big park in the center of my hometown. There is also a swimming pool there. It is next to the park. My school is across from the swimming pool. They are all near my home. In fact, there is no place like my hometown."], "zh": ["我的家乡不很现代化，但它却很美。家乡的中心位置有一座大公园。那儿也有一座游泳池。它紧邻公园。我的学校就在游泳池的对面。它们离我家都很近。事实上，没有一个地方像我的家乡一样。"]}, "dialog": null, "vocab": [{"num": 1, "word": "hometown", "phonetic": "[homˈtaun]", "pos": "n.", "meaning": "家乡，故乡", "examples": [{"en": "My hometown is far from here.", "zh": "我的家乡离这里很远。"}], "sub_entries": []}, {"num": 2, "word": "modern", "phonetic": "[ˈmadɚn]", "pos": "a.", "meaning": "现代化的", "examples": [{"en": "It is very convenient to live in a modern city.", "zh": "住在现代化的城市非常方便。"}], "sub_entries": []}, {"num": 3, "word": "beautiful", "phonetic": "[ˈbjutəfəl]", "pos": "a.", "meaning": "美丽的", "examples": [{"en": "The sun is shining. It's a beautiful day.", "zh": "阳光普照，今天是美好的一天。"}], "sub_entries": []}, {"num": 4, "word": "big", "phonetic": "[bɪɡ]", "pos": "a.", "meaning": "大的", "examples": [{"en": "There's a big elephant in the zoo.", "zh": "动物园里有一只大象。"}], "sub_entries": []}, {"num": 5, "word": "park", "phonetic": "[pɑrk]", "pos": "n.", "meaning": "公园", "examples": [], "sub_entries": []}, {"num": 6, "word": "center", "phonetic": "[ˈsɛntɚ]", "pos": "n.", "meaning": "中心，重点", "examples": [{"en": "Where is the town center?", "zh": "镇中心在哪里？"}, {"en": "The train station is in the center of the city.", "zh": "火车站位于市中心。"}], "sub_entries": ["in the center of... 在……的中心位置"]}, {"num": 7, "word": "swimming pool", "phonetic": "[ˈswɪmɪŋ pul]", "pos": "n.", "meaning": "游泳池", "examples": [], "sub_entries": []}, {"num": 8, "word": "across", "phonetic": "[əˈkrɔs]", "pos": "adv. & prep.", "meaning": "穿过，越过", "examples": [{"en": "Sarah is sitting across from me.", "zh": "莎拉坐在我的对面。"}], "sub_entries": ["(be) across from... 在……的对面"]}, {"num": 9, "word": "near", "phonetic": "[nɪr]", "pos": "prep.", "meaning": "靠近，接近", "examples": [{"en": "Billy lives near our school.", "zh": "比利住在我们学校附近。"}], "sub_entries": []}, {"num": 10, "word": "fact", "phonetic": "[fækt]", "pos": "n.", "meaning": "事实", "examples": [{"en": "I don't like hamburgers. In fact, I hate American food.", "zh": "我不喜欢汉堡。事实上，我讨厌美式食物。"}], "sub_entries": ["in fact 事实上"]}, {"num": 11, "word": "place", "phonetic": "[ples]", "pos": "n.", "meaning": "地方", "examples": [{"en": "The library is a very quiet place.", "zh": "图书馆是个非常安静的地方。"}], "sub_entries": []}, {"num": 12, "word": "like", "phonetic": "[laɪk]", "pos": "prep.", "meaning": "像", "examples": [{"en": "I want to be famous like Michael Jackson.", "zh": "我希望像迈克尔·杰克逊一样出名。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍表示场所位置的介词用法，并介绍infact 之用法及like作介词表示“像”的用法。", "items": [{"num": 1, "title": "注意下列介词及短语介词的意思及用法：", "body": ["a. near... 在···的附近", "b. next to..．紧邻....，在.....的旁边", "例: Don't move! There is a snake next to you.（别动！你的旁边有一条蛇。）", "c. across from... 在.…·的对面", "d. in the center of... 在...…的中央", "注意：", "1）这些介词或短语介词加了宾语之后，形成表示场所 位置的介词短语，与thereis/are（有.….….）并用 时，可置于句尾或句首。", "例: There is a swimming pool near my school.", "=Near my school there is a swimming pool.（我学校附近有一座游泳池。）There are several tall buildings in the center of the city.", "=In the center of the city there are several tall buildings.（市中心有几幢高大的建筑物。）", "2）若介词短语置于句首时，there可省略。", "例：Near my school there is a swimming pool.", "=Near my school is a swimming pool.（我学校附近有一座游泳池。）", "Inthecenter of the city there are several tall buildings.", "=In the center of the city are several tall buildings.（市中心有几幢高大的建筑物。）"]}, {"num": 2, "title": "In fact, there is no place like my hometown.", "body": ["（事实上，没有一个地方像我的家乡一样。）此处infact是作副词用的介词短语，使用时置于句 首，修饰 thereis..整个主句。in fact 事实上，实际上", "=as amatter of fact", "例：I am tired. In fact, I am exhausted.（我很累。实际上，我累坏了。）", "Jim is late today. As a matter of fact, he's late every day.（吉姆今天迟到了·实际上，他每天都迟到。）"]}, {"num": 3, "title": "...there is no place like my hometown.", "body": ["（…·没有一个地方像我的家乡一样。）此处的like是介词，表示“像”的意思。一般而言，like有两种用法：一作及物动词，表示“喜欢”；一作介词，表示“像”", "a. 作及物动词时，句子结构如下：", "主语+like+宾语（名词或代词）", "例：The boy likes the dog.（这男孩喜欢这条狗。）", "Ben is selfish. We don't like him.（本很自私，我们不喜欢他。）", "b. 作介词时，之后亦须接宾语，形成介词短语。这个 短语使用时，要置于：", "1）be动词之后", "例：My teacher is like my father.（我的老师就像我的父亲。）", "（is 为 be 动词，like my father 为介词短语，置于 be 动词之后）", "2）名词之后", "例：There is no place like my hometown.（没有一个地方像我的家乡一样。）", "（like my hometown 为介词短语，置于名词 place 之后）", "3）主语之前", "例：Like John, I enjoy music.（就像约翰一样，我也喜欢音乐。）", "（Like John 为介词短语，置于主语 I 之前）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 18, "title_en": "Is It near the Post Office?", "title_zh": "就在邮局附近吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Excuse me. Can you tell me the way to the train station, please?", "zh": "对不起·请您告诉我车站怎么个走法，好吗？"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "Sure. It's only three blocks down the street.", "zh": "没问题。朝这条街走下去只要走三条街就到了。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Is it near the post office?", "zh": "车站就在邮局附近吗？"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "No. It's next to the fire station.", "zh": "不是。它在消防队的隔壁。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Oh, I see. Thanks.", "zh": "哦，我明白了·谢谢。"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "You're welcome.", "zh": "不客气。"}]}, "vocab": [{"num": 1, "word": "excuse", "phonetic": "[ikˈskjuz]", "pos": "vt.", "meaning": "原谅", "examples": [{"en": "Excuse me.|Do you have the time? |Can you tell me what time it is?|", "zh": "对不起。请问现在是几点钟？"}], "sub_entries": ["Excuseme．对不起／打扰一下。"]}, {"num": 2, "word": "tell", "phonetic": "[tel]", "pos": "vt.", "meaning": "告诉，吩附", "examples": [{"en": "Mother is telling Bobby to clean his room.", "zh": "母亲吩咐博比去打扫他的房间。"}], "sub_entries": []}, {"num": 3, "word": "sure", "phonetic": "[ʃʊr]", "pos": "adv.", "meaning": "当然", "examples": [], "sub_entries": []}, {"num": 4, "word": "block", "phonetic": "[blak]", "pos": "n.", "meaning": "街区", "examples": [], "sub_entries": ["<div style=\"margin: 8px 0; padding: 10px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; font-family: monospace; font-size: 0.95em;\">\n  <div style=\"display: flex; justify-content: space-around; font-weight: bold; color: #334155; margin-bottom: 6px;\">\n    <span>南京路</span>\n    <span>上海路</span>\n    <span>天津路</span>\n  </div>\n  <div style=\"display: flex; align-items: center; border-top: 2px dashed #94a3b8; border-bottom: 2px dashed #94a3b8; padding: 6px 0; background: #eef2f6;\">\n    <span style=\"flex: 1; text-align: center; border-right: 2px solid #64748b; font-weight: bold; color: #2563eb;\">[ 1 block ]</span>\n    <span style=\"flex: 1; text-align: center; border-right: 2px solid #64748b; font-weight: bold; color: #2563eb;\">[ 1 block ]</span>\n    <span style=\"padding: 0 8px; font-weight: bold; color: #64748b; font-size: 0.9em; white-space: nowrap;\">长安街 ➔</span>\n  </div>\n</div>\n在上述路线图中，我们若想从南京路沿长安街到天津路时，就要走两个 blocks。"]}, {"num": 5, "word": "down", "phonetic": "[daun]", "pos": "prep.", "meaning": "朝.….…而下，沿着（街道）", "examples": [], "sub_entries": []}, {"num": 6, "word": "fire station", "phonetic": "[ˈfair stefan]", "pos": "n.", "meaning": "消防队", "examples": [], "sub_entries": []}, {"num": 7, "word": "welcome", "phonetic": "[ˈwelkam]", "pos": "a.", "meaning": "受欢迎的", "examples": [], "sub_entries": ["You are welcome．别客气。", "=Not at all."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ：请于下列空格填入适当的字", "questions": ["Billy lives", "1", "the center of town. There", "2_a restaurant", "3", "from his house.", "4", "isa", "police station", "5", "his house. His town is not", "beautiful，", "6", "it is safe."], "answers": ["解答1.in", "2.is", "3.across", "4. There", "5. near", "6.but"]}}, {"type": "song", "id": "song_01", "title_en": "Dreamin'", "title_zh": "梦想", "lyrics": [], "category": "经典英文金曲赏析"}, {"num": 19, "title_en": "I Have Two Friends", "title_zh": "我有两个朋友", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["I have two friends. One is short, and the other is tall. My short friend is fat, bald and ugly, but his girlfriend is beautiful. My tall friend is handsome, intelligent and strong, but his girlfriend is ugly. Oh, one more thing: my short friend is rich, but my tall friend is poor."], "zh": ["我有两个朋友。一个是矮个子，另一个是高个子。我那位矮个子朋友肥胖、秃头、长得又丑，但他的女友很美。我那位高个子朋友英俊、聪明、身体又壮，但他的女友很丑。哦，另外还有一点：我那位矮个子朋友很有钱，但是我那位高个子朋友则很穷。"]}, "dialog": null, "vocab": [{"num": 1, "word": "short", "phonetic": "[∫ort]", "pos": "a.", "meaning": "矮的，短的", "examples": [], "sub_entries": [": My parents are short, but I am tall.", "（我的父母亲很矮，但我却很高。）", "Bob is writing a short letter to his grandmother.", "（鲍勃正在写一封简短的信给他的祖母。）"]}, {"num": 2, "word": "other", "phonetic": "[ˈo]", "pos": "a.", "meaning": "剩余的，其他的", "examples": [{"en": "I have two sons. One is a doctor, and the other is a lawyer.", "zh": "我有两个儿子·其中一个是医生，另一个是律师。"}], "sub_entries": ["在本文中other与the并用，形成代词theother", "（另外一个）。", "one...the other...", "个………·.另一个…··"]}, {"num": 3, "word": "tall", "phonetic": "[tol]", "pos": "a.", "meaning": "高的", "examples": [], "sub_entries": [":Basketball players are very tall.", "（篮球运动员都很高。）"]}, {"num": 4, "word": "fat", "phonetic": "[fet]", "pos": "a.", "meaning": "肥胖的", "examples": [{"en": "Fat people can't run fast.", "zh": "胖的人都跑不快。"}], "sub_entries": []}, {"num": 5, "word": "bald", "phonetic": "[bold]", "pos": "a.", "meaning": "秃头的", "examples": [], "sub_entries": []}, {"num": 6, "word": "ugly", "phonetic": "[ˈaɡll]", "pos": "", "meaning": "a．丑.陋的，难看的", "examples": [{"en": "The ugly boy doesn't have a girlfriend.", "zh": "那丑男孩没有女朋友。"}], "sub_entries": []}, {"num": 7, "word": "girlfriend", "phonetic": "[ˈɡ3lfrend]", "pos": "n.", "meaning": "女朋友", "examples": [], "sub_entries": []}, {"num": 8, "word": "handsome", "phonetic": "[ˈhensam]", "pos": "a.", "meaning": "英俊的", "examples": [], "sub_entries": [": The handsome actor is very famous.", "（那位英俊的演员非常有名。）"]}, {"num": 9, "word": "intelligent", "phonetic": "[1nˈtelad3ant]", "pos": "a.", "meaning": "聪明的", "examples": [{"en": "The intelligent boy is reading a novel.", "zh": "那个聪明的男孩正在看小说。"}], "sub_entries": []}, {"num": 10, "word": "strong", "phonetic": "[stroɡ]", "pos": "a.", "meaning": "强壮的", "examples": [{"en": "Boxers are very strong.", "zh": "拳击手都很强壮。"}], "sub_entries": []}, {"num": 11, "word": "rich", "phonetic": "[rit]", "pos": "a.", "meaning": "富有的", "examples": [{"en": "The rich man is a banker.", "zh": "那个有钱人是个银行家。"}], "sub_entries": []}, {"num": 12, "word": "poor", "phonetic": "[pur]", "pos": "a.", "meaning": "贫穷的", "examples": [{"en": "I don't have any money. I am very poor.", "zh": "我没有半毛钱，我很穷。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍代词\"one...theother...”的用法，并介绍 并列连词and 的用法。", "items": [{"num": 1, "title": "I have two friends. One is short, and the other is tall.", "body": ["（我有两个朋友。一个是矮个子，另-个是高个子。）注意下列代词的用法：", "a. 两者：one...the other...", "·个...…·另··个...·", "例：I have two brothers. One is a teacher, and the other is a soldier.（我有两个哥哥。一个是老师，另…·个是军 人。）", "b. 三者:one...another...the other...", "例：Her three sisters are busy now. One is", "cooking in the kitchen, another is fixing her bike in the yard, and the other is studying in the living room.（她的三个姐姐现在都很忙。一个正在厨房作 饭，一个正在院子里修她的自行车，另··个 则正在客厅里看书。）"]}, {"num": 2, "title": "My short friend is fat, bald and ugly.", "body": ["（我那位矮个子朋友肥胖、秃头、长得又丑。）上句中的 and 是并列连词，表示“和”、“以及”的意思，连接 fat、bald 及 ugly 三个平行对等的形容词。and 可连接平行的单词、短语、从句或句子。", "例：", "• John and David are good friends.（名词 + 名词：约翰和大卫是好朋友。）", "• She is beautiful and helpful.（形容词 + 形容词：她美丽又乐于助人。）", "• She sings and dances very well.（动词 + 动词：她唱歌跳舞都很好。）", "• I like him because he is intelligent and because he is helpful.（状语从句 + 状语从句：我喜欢他，因为他很聪明，也因为他乐于助人。）", "• She sings well, and she is good at dancing.（句子 + 句子：她歌唱得很好，跳舞也很行。）", "注意：", "a. and 连接两个平行单词时，and 之前不得置逗号。", "例：My friend is handsome, and intelligent.（×）", "→ My friend is handsome and intelligent.（○）（我的朋友英俊又聪明。）", "b. and 连接三个平行单词时，第一个单词与第二个单词之间置逗号，and 则置于第二个单词与第三个单词之间，and 之前则可置逗号，但通常予以省略。", "例：My friend is handsome, intelligent, and strong.（可）", "→ My friend is handsome, intelligent and strong.（常用）（我的朋友英俊、聪明、身体又壮。）", "c. and 连接平行的句子时，and 之前通常置一逗号；but 亦为并列连词，表示“但是”、“不过”的意思，用来连接平行的句子时，but 之前通常也置一逗号。", "例：He loves Jane, and (he) is planning to marry her this year.（他很爱简，且正计划今年要跟她结婚。）", "He likes music, but his girlfriend hates it.（他喜欢音乐，但他的女友讨厌音乐。）"]}, {"num": 3, "title": "Oh, one more thing: my short friend is rich, but my tall friend is poor.", "body": ["=Oh, there is one more thing: my short friend...（哦，另外还有一点：我那位矮个子朋友·…·.）more[mor]a.更多的 one more.... 再一个··. two more... 再两个·. three more... 再三个····：", ": We need five more apple pies for the party.（我们的宴会还需要五个苹果馅饼。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 20, "title_en": "She Is Beautiful", "title_zh": "她很漂亮", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "John", "speaker_zh": "约翰", "en": "Wow! Who is that lady next to Bob? She's pretty.", "zh": "哇！鲍勃身旁的那位小姐是谁呀？她好漂亮。"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "Do you really think so?", "zh": "你真地这么认为吗？"}, {"speaker_en": "John", "speaker_zh": "约翰", "en": "Sure. Look at her lovely blond hair and blue eyes.", "zh": "当然·瞧瞧她那漂亮的金发和蓝眼睛。"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "You're right. She is beautiful.", "zh": "你说对了·她很美。"}, {"speaker_en": "John", "speaker_zh": "约翰", "en": "Well, who is she?", "zh": "那么，她是谁呢？"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "She's my mother.", "zh": "她是我妈妈。"}]}, "vocab": [{"num": 1, "word": "lady", "phonetic": "[ˈleɪdi]", "pos": "n.", "meaning": "小姐，女士", "examples": [], "sub_entries": []}, {"num": 2, "word": "pretty", "phonetic": "[ˈprɪti]", "pos": "a.", "meaning": "漂亮的（=beautiful)", "examples": [], "sub_entries": []}, {"num": 3, "word": "think so", "phonetic": "", "pos": "", "meaning": "如此想法", "examples": [], "sub_entries": ["此处 so 是代词，代替前面的句子 \"She's pretty.\"。"]}, {"num": 4, "word": "look", "phonetic": "[lʊk]", "pos": "vi.", "meaning": "看", "examples": [{"en": "The boys are looking at the pretty girl.", "zh": "男孩们正注视着那位漂亮的女孩。"}], "sub_entries": ["look at...", "注视…··…，注意看···"]}, {"num": 5, "word": "lovely", "phonetic": "[ˈlʌvli]", "pos": "a.", "meaning": "美丽的（=beautiful)", "examples": [{"en": "My best friend has a lovely daughter.", "zh": "我最好的朋友有个漂亮的女儿。"}], "sub_entries": []}, {"num": 6, "word": "blond", "phonetic": "[blɑːnd]", "pos": "a.", "meaning": "金色的（头发）", "examples": [], "sub_entries": []}, {"num": 7, "word": "hair", "phonetic": "[her]", "pos": "n.", "meaning": "头发", "examples": [], "sub_entries": []}, {"num": 8, "word": "blue", "phonetic": "[bluː]", "pos": "a.", "meaning": "蓝色的", "examples": [], "sub_entries": []}, {"num": 9, "word": "eye", "phonetic": "[aɪ]", "pos": "n.", "meaning": "眼睛", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Mary has two sons. One is a college student, and", "is a soldier.", "(A)another", "(B)other", "(C) the other", "(D) an other", "2.", "is the boy there?", "(A) Who's (B) Who (C) Where (D) There", "3.Tom's", "is a musician.", "(A) girl's friends", "(B) girlfriend", "(C) boys' friends", "(D) friends", "4. Can I have", "cup of coffee?", "(A) more", "(B) one more", "(C) more one", "(D) two more", "5.", "the girl next to the window. She is beautiful.", "(A) Look", "(B) Look into", "(C) Look look", "(D) Look at", "6. Roger thinks Jane has lovely eyes. This sentence", "means", "(A) Roger loves Jane", "(B) Roger loves Jane's eyes", "(C) Roger thinks Jane's eyes are beautiful", "(D) Roger thinks Jane's hair is beautiful"], "answers": ["解答>1.(C）2.(B）3.(B）4.(B）5.(D）6.(C)"]}}, {"num": 21, "title_en": "I Don't Know Anyone", "title_zh": "我谁都不认识", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["I don't know anyone at this party. There's a strange man. He has a big nose and small ears. I don't know him. There are two women. They're wearing glasses. I don't know them, either. There is a cute young girl. She has long hair and fair skin. She's dancing with someone. I like her, but everyone else does, too."], "zh": ["这个宴会上的人我一个也不认识。有个陌生人。他鼻大耳小。我不认识他。有两个女人。她们都戴着眼镜。我也不认识她们。有位可爱的年轻女孩。她留着长发、皮肤白皙。她正跟某个人跳舞。我喜欢她，但其他的人也都喜欢她。"]}, "dialog": null, "vocab": [{"num": 1, "word": "know", "phonetic": "[no]", "pos": "vt.", "meaning": "认识", "examples": [{"en": "Do you know the way to my house?", "zh": "你知道去我家的路吗？"}], "sub_entries": []}, {"num": 2, "word": "anyone", "phonetic": "[ˈenl.wan]", "pos": "pron.", "meaning": "任何一个人", "examples": [{"en": "Does anyone want an orange?", "zh": "有没有人想要橙呢？"}], "sub_entries": []}, {"num": 3, "word": "party", "phonetic": "[ˈparti]", "pos": "n.", "meaning": "宴会，（社交性或娱乐性的）聚会", "examples": [], "sub_entries": []}, {"num": 4, "word": "strange", "phonetic": "[ˈstreɪndʒ]", "pos": "a.", "meaning": "陌生的；奇怪的", "examples": [{"en": "Tim's girlfriend has a strange voice.", "zh": "蒂姆女友的声音很奇怪。"}], "sub_entries": []}, {"num": 5, "word": "big", "phonetic": "[biɡ]", "pos": "a.", "meaning": "大的", "examples": [], "sub_entries": []}, {"num": 6, "word": "nose", "phonetic": "[noz]", "pos": "n.", "meaning": "鼻子", "examples": [], "sub_entries": []}, {"num": 7, "word": "small", "phonetic": "[smol]", "pos": "a.", "meaning": "小的", "examples": [], "sub_entries": []}, {"num": 8, "word": "ear", "phonetic": "[ir]", "pos": "n.", "meaning": "耳朵", "examples": [], "sub_entries": []}, {"num": 9, "word": "women", "phonetic": "[ˈwiman]", "pos": "n.", "meaning": "女人（复数）", "examples": [], "sub_entries": ["woman['wuman]n.女人（单数）", "one woman", "一个女人", "two women", "两个女人"]}, {"num": 10, "word": "wear", "phonetic": "[wer]", "pos": "vt.", "meaning": "穿，戴（帽子、耳环、鞋子、衣服、", "examples": [{"en": "I like to wear jeans.", "zh": "我喜欢穿牛仔裤。"}], "sub_entries": ["皮带等任何可穿戴在身上的东西）"]}, {"num": 11, "word": "glasses", "phonetic": "[ˈɡlaesiz]", "pos": "n.", "meaning": "眼镜", "examples": [{"en": "a piece of glass two pieces of glass a glass two glasses", "zh": "一片玻璃两片玻璃一只玻璃杯两只玻璃杯但glasses亦可作“眼镜”解，由于眼镜的镜片有两片，故用来指“眼镜”时，glasses用复数。"}, {"en": "a pair of glasses two pairs of glasses", "zh": "一副眼镜两副眼镜"}], "sub_entries": ["时，是不可数名词；作“玻璃杯”解时，则为可数名"]}, {"num": 12, "word": "cute", "phonetic": "[kjut]", "pos": "a.", "meaning": "可爱的", "examples": [{"en": "Everybody likes cute children.", "zh": "每个人都喜欢可爱的小孩。"}], "sub_entries": []}, {"num": 13, "word": "young", "phonetic": "[jɡ]", "pos": "a.", "meaning": "年轻的", "examples": [{"en": "The young man is very polite.", "zh": "那个年轻人很有礼貌。"}], "sub_entries": []}, {"num": 14, "word": "long", "phonetic": "[loɡ]", "pos": "a.", "meaning": "长的", "examples": [{"en": "John likes girls with long hair.", "zh": "约翰喜欢长头发的女孩。"}], "sub_entries": []}, {"num": 15, "word": "fair", "phonetic": "[fer]", "pos": "a.", "meaning": "（皮肤）白皙的", "examples": [], "sub_entries": []}, {"num": 16, "word": "skin", "phonetic": "[skin]", "pos": "n.", "meaning": "皮肤（不可数）", "examples": [], "sub_entries": []}, {"num": 17, "word": "dance", "phonetic": "[dens]", "pos": "vi.", "meaning": "跳舞", "examples": [{"en": "Do you know how to dance?", "zh": "你知道怎么跳舞吗？"}], "sub_entries": []}, {"num": 18, "word": "someone", "phonetic": "[ˈsam.wan]", "pos": "pron.", "meaning": "某个人", "examples": [], "sub_entries": []}, {"num": 19, "word": "else", "phonetic": "[εls]", "pos": "adv.", "meaning": "另外，别的（置于everybody", "examples": [{"en": "I like my teacher, but everyone else doesn't. Sorry, I can't help you. Please ask someone else. James smokes, but no one else in the office does.", "zh": "我喜欢我的老师，但是其他人都不喜欢。）（抱歉，我没办法帮你。请你找别人吧！）（詹姆士抽烟，但是办公室里的其他人都不抽烟。"}], "sub_entries": ["somebody、nobody之后）", "everybody else", "其他每个人", "=everyoneelse", "somebody else", "另外一个人", "=someoneelse", "nobody else", "没有其他的人", "=no one else"]}], "grammar": {"intro": "本课介绍not形成的否定句，并介绍代词anyone 与someone的区别。", "items": [{"num": 1, "title": "I don't know anyone at this party.", "body": ["（这个宴会上的人我一个也不认识。）本句为以副词not形成的否定句子结构。否定句均由 肯定句变化而成，有下列三种型态：", "a. 句中有be动词时，not置于该be动词之后。", "例：He is intelligent.（肯定）（他聪明。）", "He is not intelligent.（否定）", "=He isn't intelligent.（他不聪明。）", "b. 句中有助动词如can（能够）、will（将要）、may（可以）、must（必须）等时，not置于该助 动词之后。", "例：He will come today.（肯定）（他今天会来。）", "He will not come today.（否定）", "=He won't come today.（他今天不会来。）The boy can sing.（肯定）（这男孩会唱歌。）The boy cannot sing.（否定）", "= The boy can't sing.（这男孩不会唱歌。）*can与not并用时，应写成cannot而非can not，但will、may、must等助动词与not并 用时，则仍为will not、maynot、mustnot。", "c. 句中只有一般动词而无be动词或助动词时，应先 在主语之后按人称变化分置助动词do或does，再 加not，原来的动词均改为动词原形。", "例：She loves David.（肯定）（她爱大卫。）", "此时主语She为第三人称单数代词，故She之后 应置does，再加not,然后将loves改为love, 即：", "She does not love David.（否定）", "=She doesn't love David.（她不爱大卫。）", "例：They like music.（肯定）（他们喜欢音乐。）", "此时主语They为第三人称复数代词，故They之 后应置do，再加not，like 的原形仍为like，即：", "They do not like music.（否定）", "=They don't like music.（他们不喜欢音乐。）"]}, {"num": 2, "title": "不定代词 anyone 与 someone 的用法区别", "body": ["anyone（任何一个人）与 someone（某个人）分别等于 anybody 及 somebody。anyone 或 anybody 通常用于否定句或疑问句中；someone 或 somebody 则用于肯定句中。", "例： I don't know anybody in the classroom.（否定）（教室里的人我都不认识。）", "There isn't anyone in the room.(否定）（房间里一个人都没有。）Does anyone know the answer?（疑问）（有人知道这答案吗？）Can anybody do it?（疑问）（这件事有人会做吗？）There is someone·there.（肯定）（那里有个人。）Somebody is talking to Mary.（肯定）（有人在跟玛丽说话。）不过anybody或anyone若作主语时，仍可用于肯 定句中，作强调的用法。", "例：Anybody can answer the question.（任何人都能回答这个问题。）", "If he can do it, anyone can.（他若能做这件事，那么任何人都能够做了。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 22, "title_en": "Do You Want to Dance?", "title_zh": "你想跳舞吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "Hello. Do you want to dance?", "zh": "你好。你想跳舞吗？"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "No, thanks.", "zh": "不，谢谢。"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "Do you want a drink?", "zh": "你要喝一杯吗？"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "No, thank you.", "zh": "不，谢谢你。"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "What do you want?", "zh": "你想要什么？"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "I just want you to go away.", "zh": "我只想要你离开。"}]}, "vocab": [{"num": 1, "word": "want", "phonetic": "[want]", "pos": "vt.", "meaning": "要，欲", "examples": [{"en": "I want to see him now. : The little boy wants more toys.", "zh": "我想现在就见到他。）b.want+名词要.··.（这小男孩想要更多的玩具。）c.want+人+to+动词原形要某人·…·"}, {"en": "He wants me to mail the letter for him.", "zh": "他要我为他寄这封信。"}], "sub_entries": ["a.wantto+动词原形", "想要····"]}, {"num": 2, "word": "drink", "phonetic": "[driɡk]", "pos": "n.", "meaning": "酒", "examples": [{"en": "I want a drink after work.", "zh": "下班后我想喝杯酒。"}], "sub_entries": ["drink可作“饮料”或“酒”解，但在现代美语中，", "多作“酒”解，尤其常见使用于下列短语中：", "have/want/get+a drink", "喝…杯（酒）"]}, {"num": 3, "word": "go away", "phonetic": "", "pos": "短语", "meaning": "离开", "examples": [{"en": "Don't bother me! Please go away.", "zh": "别烦我！请你走开。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. 1 don't know", "here.", "(A) anyone", "(B） someone", "(C) another one", "(D) the other", "2.He isn't polite. She isn't,", "(A) also", "(B) too", "(C) either", "(D) polite", "3. They like music. I", "too.", "(A)am", "(B)can", "(C) don't", "(D) do", "4. The question is easy.", "can answer it.", "(A) Some body", "(B)No one.", "(C) Every body", "(D） Anyone", "5. He's wearing", "(A) a piece of glass", "(B) a glass", "(C) glasses", "(D) glass", "6.Mother wants you", "the dishes for her.", "(A) to wash", "(B)washing", "(C) wash", "(D） to washes"], "answers": ["解答=>1.(A）2.(C）3.(D）4.(D）5.(C）6.（A)"]}}, {"num": 23, "title_en": "The Book Is Mine", "title_zh": "这本书是我的", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["This is my English book. It belongs to me. It is mine. That is your English book. It belongs to you. It is yours. Those books aren't ours. They belong to those boys over there. They are theirs. Why do we all have different books? Because we belong to different classes."], "zh": ["这是我的英文书。它属于我。它是我的·那是你的英文书。它属于你。它是你的。那些书不是我们的。它们属于那边那些男孩不同的班级。"]}, "dialog": null, "vocab": [{"num": 1, "word": "English", "phonetic": "[ˈnɡlj]", "pos": "n.", "meaning": "英文，英语", "examples": [{"en": "John is Chinese, but he speaks English well.", "zh": "约翰是中国人，不过他英文说得很好。"}], "sub_entries": []}, {"num": 2, "word": "belong", "phonetic": "[brloɡ]", "pos": "vi.", "meaning": "属于（与介词to并用）", "examples": [{"en": "Put that umbrella down. It doesn't belong to you.", "zh": "把那把雨伞放下。它不属于你的。"}], "sub_entries": ["belong to...", "属于··..…."]}, {"num": 3, "word": "mine", "phonetic": "[main]", "pos": "pron.", "meaning": "我的", "examples": [], "sub_entries": []}, {"num": 4, "word": "yours", "phonetic": "[jurz]", "pos": "pron.", "meaning": "你的，你们的", "examples": [], "sub_entries": []}, {"num": 5, "word": "those", "phonetic": "[ooz]", "pos": "pron.", "meaning": "那些", "examples": [], "sub_entries": []}, {"num": 6, "word": "ours", "phonetic": "[aurz]", "pos": "pron.", "meaning": "我们的", "examples": [], "sub_entries": []}, {"num": 7, "word": "theirs", "phonetic": "[erz]", "pos": "pron.", "meaning": "他们/她们/它们的", "examples": [], "sub_entries": []}, {"num": 8, "word": "different", "phonetic": "[ˈdifarant]", "pos": "a.", "meaning": "不同的", "examples": [{"en": "I like many different kinds of books.", "zh": "我喜欢很多不同种类的书。"}], "sub_entries": []}, {"num": 9, "word": "class", "phonetic": "[klaes]", "pos": "n.", "meaning": "班级；课", "examples": [{"en": "What time is your history class?", "zh": "你的历史课是在什么时候呢？"}], "sub_entries": []}], "grammar": {"intro": "本课介绍指示代词及名词性所有格代词的种类及用法。", "items": [{"num": 1, "title": "This is my English book.", "body": ["（这是我的英文书。）", "That is your English book.（那是你的英文书。）Those books aren't ours.（那些书不是我们的。）上列句中的This、That及Those 均为指示代词。英语中的指示代词常用的有四个：this[ors这个）that[aet]（那个）、these[oiz]（这些）those[oz]（那些）。请读者注意下列要点：", "a. this及that代替单数名词或不可数名词，these 及those则代替复数名词。", "例： This is my bike.", "单数名词（这是我的自行车。）That is your money. 不可数名词（那是你的钱。）These are your books. 复数名词（这些是你的书。）Those are his pencils. 复数名词（那些是他的铅笔。）", "b. 以上指示代词亦有定冠词的功能，之后可接名词。", "例： This bike belongs to me.（这辆自行车属于我的。）", "These girls are cute.（这些女孩子很可爱。）", "c. this及these指较近的人或事物；that及those 则指较远的人或事物。", "例：This book belongs to me, and that book belongs to him.（这本书属于我的，那本书则属于他的。）", "I don'don't like these flowers. I like those flowers next to the window.（我不喜欢这些花。我喜欢紧窗户的那些 花。）", "d. this、that、these、those 在文章第一次出现之 后，第二次使用时为避免重复，this及that应用 it代替，these及those则用they代替。", "例: This is my English book. This belongs to", "me.（劣）", "→ This is my English book. It belongs to me.（佳）（这是我的英文书。它属于我的。）These books are mine. These don't belong to you.（劣）> These books are mine. They don't belong to you.（佳）（这些书是我的。它们不属于你的。）"]}, {"num": 2, "title": "It is mine.", "body": ["（它是我的。）", "It is yours.", "（它是你的。）", "Those books aren't ours.", "（那些书不是我们的。）", "上列句中的mine、yours及ours均为名词性所有", "格代词，与我们稍早所介绍的形容词性所有格代词有", "所不同·兹先列表如下：", "数", "单", "数", "型", "一详", "我的", "你（你)的", "他(她它)的", "态", "形容词性所", "his/her/its", "my", "your", "有格代词", "名词性所", "mine", "yours", "his/hers/its", "有格代词", "数", "复", "数", "中", "型", "译", "我们的", "你（你）们的", "他（她、它）们的", "态", "形容词性所", "our", "your", "their", "有格代词", "名词性所", "ours", "yours", "theirs", "有格代词", "注意事项：", "a.形容词性所有格代词相当于形容词，之后一定要接", "名词；而名词性所有格代词则相当于名词，之后不", "可再接名词。", "例：The book is my.（×，my 是形容词性所有", "格代词，之后须接名词）", "-→ This is my book. (○)", "（这是我的书。）", "-→ The book is mine. (○)", "（这本书是我的。）", "Our school is big, but their is small. ( × ,", "their是形容词性所有格代词，之后须接名词）", "→ Our school is big, but their school is", "small.（O，但school一字在句中重复是", "-缺点）", "\"> Our school is big, but theirs is small.", "（佳）", "（我们的学校很大，但他们的却很小。）", "b.his及its可同时作形容词性或名词性所有格代词；", "her属形容词性所有格代词，hers则属名词性所", "有格代词。", "例：I don't like her car. I like his.(his 为名", "词性所有格代词，her为形容词性所有格代", "词）", "（我不喜欢她的车。我喜欢他的。）", "I like his car. I don't like hers.(his 为形", "容词性所有格代词，hers为名词性所有格代", "词）", "（我喜欢他的车。我不喜欢她的。）", "I have a dog. Its mouth is big, but mine", "is bigger than its.（本句中Its 是形容词性", "所有格代词，its则为名词性所有格代词）", "（我有一只狗。它的嘴很大，但我的嘴比它的", "还大。）", "c.勿将 it's与 its 混为一谈。", "its（它的）是所有格代词；it's 则为 it is（它是）", "的缩写形。", "例: I have a dog. It's tail is long. (×)", "-→ I have a dog. Its tail is long. (○)", "（我有一只狗。它的尾巴是长的。）", "I have a dog. Its very strong. (×)", "→ I have a dog. It's very strong. (○)", "=I have a dog. It is very strong.", "（我有一只狗。它很强壮。）"]}, {"num": 3, "title": "They belong to those boys over there.", "body": ["（它们属于那边那些男孩子的。）there（那里）、here（这里）皆为表示场所的副词，使用时，通常置于句尾。", "例：I see aboy there．（我看到那边有个男孩。）", "There is a dog here.（这里有只狗。）但在口语中，老美常在there及here之前另加一副 词over['ova]，强调 there 或here·故以上两句 亦可改为：", "I see a boy over there.", "There is a dog over here."]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 24, "title_en": "It's Mine", "title_zh": "它是我的", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Whose test paper is this?", "zh": "这是谁的测验卷？"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "It's mine, ma'am.", "zh": "是我的，老师。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "And whose test paper is this?", "zh": "那么这是谁的测验卷？"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "It's Tony's, ma'am.", "zh": "是托尼的，老师。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "And why are your answers exactly the same as his?", "zh": "那么为什么你的答案和他完全一样呢？"}, {"speaker_en": "Bob", "speaker_zh": "鲍勃", "en": "Because Tony has eyes in the back of his head.", "zh": "因为托尼后脑勺长了眼睛。"}]}, "vocab": [{"num": 1, "word": "whose", "phonetic": "[huz]", "pos": "pron.", "meaning": "谁的", "examples": [{"en": "This is whose dog? (×) → Whose dog is this? (○)", "zh": "（whose 因属疑问代词，故应置于句首；此处 whose 为形容词性所有格代词，之后接名词 dog。译：这是谁的狗？）"}, {"en": "This dog is whose? (×) → Whose is this dog? (○)", "zh": "（whose 因属疑问代词，故应置于句首；此处 whose 为名词性所有格代词，之后不接名词。译：这只狗是谁的？）"}], "sub_entries": ["本字乃所有格疑问代词，用于问句中，置于该问句句", "首。whose可作形容词性或名词性所有格代词；作形", "容词性所有格代词时，之后接名词；作名词性所有格", "代词时，之后不接名词。"]}, {"num": 2, "word": "test paper", "phonetic": "[ˈtest pepa]", "pos": "n.", "meaning": "测验卷，试卷", "examples": [], "sub_entries": []}, {"num": 3, "word": "ma'am", "phonetic": "[maem]", "pos": "n.", "meaning": "夫人，女士（对妇女的尊称语，", "examples": [], "sub_entries": ["此指女老师)"]}, {"num": 4, "word": "answer", "phonetic": "[ˈens]", "pos": "n.", "meaning": "答案", "examples": [], "sub_entries": []}, {"num": 5, "word": "exactly", "phonetic": "[iɡzaktl1]", "pos": "adv.", "meaning": "完全地", "examples": [], "sub_entries": []}, {"num": 6, "word": "same", "phonetic": "[sem]", "pos": "a.", "meaning": "相同的", "examples": [{"en": "This book is the same as mine. exactly the same much the same about the same", "zh": "这本书和我的那本相同。）b.the same 之前可置副词exactly、much、about，表示相同的程度的深浅之别。完全相同很相同大致相同"}, {"en": "My bike is exactly the same as John's.", "zh": "我的自行车和约翰的完全相同。"}], "sub_entries": []}, {"num": 7, "word": "in the back of", "phonetic": "", "pos": "短语", "meaning": "在.…·…之后", "examples": [{"en": "I sit in the back of the class, and Mary sits in the front.", "zh": "我坐在教室后面，而玛丽坐在前面。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.", "is her pencil over there.", "(A) Those (B) These (C) That (D) This", "2.", "is my book bag over here.", "(A) Those(B)These(C) That", "t(D）This", "3.", "shoes over here are his.", "(A） Those(B) These (C) That(D） This", "4.", "earrings over there are Sally's.", "(A)Those(B)These(C) That (D） This", "5. Whose cigarettes are these?", "Peter's.", "(A) They're (B) This's (C) That's (D) It's", "6. Bob's car is", "color as mine.", "(A) exactly same", "(B) same", "(C) exactly the same", "(D) very same"], "answers": ["解答1.(C）2.(D）3.(B）4.(A）5.(A）6.(C)"]}}, {"num": 25, "title_en": "My Father", "title_zh": "我的父亲", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My father does the same thing every morning. He gets up at six o'clock. He washes, brushes his teeth and combs his hair. Then, he puts on his clothes and eats breakfast. At six-thirty helistens to the news on the radio. At exactly seven o'clock he leaves the house. My father ha.. very regular habits."], "zh": ["我父亲每天早上都做相同的事。他六点起床。他洗脸、刷牙、梳头发。然后他就穿衣吃早饭。他六点半听收音机播报的新闻。他七点整出门。我父亲有很规律的习惯。"]}, "dialog": null, "vocab": [{"num": 1, "word": "every", "phonetic": "[ˈcvr1]", "pos": "a.", "meaning": "每个", "examples": [{"en": "He visits his teacher every Sunday.", "zh": "他每个星期天都会去看他的老师。"}], "sub_entries": []}, {"num": 2, "word": "morning", "phonetic": "[ˈmorniɡ]", "pos": "n.", "meaning": "早上", "examples": [], "sub_entries": []}, {"num": 3, "word": "wash", "phonetic": "[waf]", "pos": "vi.", "meaning": "洗脸，洗手", "examples": [], "sub_entries": [": My kung fu teacher always washes in cold", "water.", "（我的功夫课老师总是以冷水盥洗。）"]}, {"num": 4, "word": "brush", "phonetic": "[bra∫]", "pos": "vt.", "meaning": "刷", "examples": [], "sub_entries": []}, {"num": 5, "word": "teeth", "phonetic": "[tio]", "pos": "n.", "meaning": "牙齿（tooth[tuo]的复数形）", "examples": [], "sub_entries": ["one tooth", "一颗牙齿", "two teeth", "两颗牙齿"]}, {"num": 6, "word": "comb", "phonetic": "[kom]", "pos": "vt.", "meaning": "用梳子梳（comb也可作名词，表示", "examples": [{"en": "Comb your hair. It's a mess.", "zh": "把头发梳一梳吧！乱七八糟的。"}], "sub_entries": ["“梳子”的意思）"]}, {"num": 7, "word": "hair", "phonetic": "[her]", "pos": "n.", "meaning": "头发（不可数）", "examples": [], "sub_entries": []}, {"num": 8, "word": "then", "phonetic": "[en]", "pos": "adv.", "meaning": "然后", "examples": [], "sub_entries": []}, {"num": 9, "word": "clothes", "phonetic": "[kloz]", "pos": "n.", "meaning": "衣服", "examples": [], "sub_entries": []}, {"num": 10, "word": "eat", "phonetic": "[it]", "pos": "vt.", "meaning": "吃", "examples": [{"en": "I usually eat a sandwich for lunch.", "zh": "我午餐通常吃一个三明治。"}], "sub_entries": []}, {"num": 11, "word": "breakfast", "phonetic": "[ˈbrekfast]", "pos": "n.", "meaning": "早餐", "examples": [], "sub_entries": []}, {"num": 12, "word": "listen", "phonetic": "[ˈlisn]", "pos": "vi.", "meaning": "倾听（与介词 to 并用，方可置宾语）", "examples": [{"en": "He is listening music. (×) →He is listening to music.(○)", "zh": "他正在听音乐。"}], "sub_entries": []}, {"num": 13, "word": "news", "phonetic": "[njuz]", "pos": "n.", "meaning": "新闻，消息（不可数）", "examples": [{"en": "That's a very good news. (×) →That's very good news. (○) → That's a very good piece of news. (○)", "zh": "那是很好的消息。）（那是一则好消息。"}], "sub_entries": ["a piece of news", "一则消息"]}, {"num": 14, "word": "radio", "phonetic": "[redi.o]", "pos": "n.", "meaning": "收音机", "examples": [], "sub_entries": []}, {"num": 15, "word": "o'clock", "phonetic": "[aˈklak]", "pos": "n.", "meaning": "..….点钟", "examples": [], "sub_entries": ["eight o'clock", "八点钟"]}, {"num": 16, "word": "leave", "phonetic": "[liv]", "pos": "vt.", "meaning": "离开", "examples": [], "sub_entries": [".例: What time does the train leave the station?", "（火车什么时候离开车站？）"]}, {"num": 17, "word": "regular", "phonetic": "[ˈreɡjalo]", "pos": "a.", "meaning": "有规律的", "examples": [{"en": "My father goes to bed at regular hours.", "zh": "我父亲的睡觉时间很规律。"}], "sub_entries": []}, {"num": 18, "word": "habit", "phonetic": "[ˈhabit]", "pos": "n.", "meaning": "习惯", "examples": [{"en": "Smoking is a bad habit.", "zh": "抽烟是个坏习惯。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍一般现在时的用法。", "items": [{"num": 1, "title": "一般现在时与现在进行时的比较", "body": ["稍早我们曾介绍了现在进行时的形态及用法。我们现在将两种时态作个比较：", "一般现在时：", "例: He has breakfast at seven every morning.（他每天早上七点吃早饭。）", "现在进行时：", "例：He is having breakfast now.（他现在正在吃早饭。）", "第一句中的has（吃）等于eats，是一般现在时，所 表示的动作并非“正在发生的动作”，而是“常态的 动作”；而第二句ishaving（正在吃）等于is eating，则表示“现在正在发生的动作”。"]}, {"num": 2, "title": "My father does the same thing every morning.", "body": ["=Every morning my father does the same thing.（我父亲每天早上都做相同的事。）上句中的everymorning是时间副词。英文中的时间 副词可置于句首或句尾，但多半置于句尾。中文里的 时间副词，则多置于主语之后。比较下列句子：", "中文：我今天很忙。英文：I today am busy.（×）", "→ I am busy today.(○)", "=Today I am busy."]}, {"num": 3, "title": "He gets up at six o'clock.", "body": ["=He rises at six o'clock.（他六点钟起床。）", "a. get up 起床（=rise[raiz])go to bed 睡觉", "例：A farmer usually gets up early in the morning.（农民通常一大早就起床。）", "b. at six o'clock 在六点钟", "=at six 英文里表示“在...点钟”时，要使用介词at，之 后接数字，名词o'clock通常可省略。", "例：He gets up at five (o'clock）every morning.（他每天早上五点起床。）"]}, {"num": 4, "title": "Then, he puts on his clothes and eats breakfast.", "body": ["（然后，他就穿衣吃早饭。）put on 穿戴（衣、帽、鞋、袜子、耳环等可佩带 在身上的任何东西)takeoff 脱下（上列的任何东西）", "例：Put on your bathing suit and let's go swimming:", "（穿上泳装，咱们去游泳吧。）Take off your shoes. They're dirty.（把鞋子脱掉，它们太脏了。）", "注意：", "wear[wer]与puton均表示“穿”的意思，但 d（）。….，on则强调“穿上.”（穿的动作）。", "例：After I wash, I put on my school uniform.（盥洗过后，我穿上学校的制服。）", "Bob wears a suit and tie to work.（鲍勃上班时穿西装打领带。）"]}, {"num": 5, "title": "At exactly seven o'clock he leaves the house.", "body": ["=He leaves the house at exactly seven (o'clock).（他七点整出门。）exactly[igzektli]adv.精确地 此处exactly置于表几点钟的名词之前，表示“几点 整”之意。", "例：Please see me at exactly nine (o'clock)", "tonight.（请于今晚九点整见我。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 26, "title_en": "He Usually Plays Tennis", "title_zh": "他通常打网球", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Jeff", "speaker_zh": "杰弗", "en": "What do you usually do on Sundays?", "zh": "你星期天通常做些什么事？"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "I usually go for a walk in the mountains.", "zh": "我通常到山中走一走。"}, {"speaker_en": "Jeff", "speaker_zh": "杰弗", "en": "Does your husband go with you?", "zh": "你先生跟你一块儿去吗？"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "No. He doesn't.", "zh": "不。他不去。"}, {"speaker_en": "Jeff", "speaker_zh": "杰弗", "en": "What does he do?", "zh": "他做什么呢？"}, {"speaker_en": "Betty", "speaker_zh": "贝蒂", "en": "He usually plays tennis.", "zh": "他通常打网球。"}]}, "vocab": [{"num": 1, "word": "What do you usually do on Sundays?", "phonetic": "", "pos": "日常口语", "meaning": "你星期天通常做些什么事？", "examples": [{"en": "Do you want to go to the beach on Sunday? I practice the piano on Sundays.", "zh": "你这个星期天要去海滩吗？）（我每个星期天都练习弹钢琴。"}], "sub_entries": ["on Sunday", "这个星期天", "on Sundays", "每逢星期天"]}, {"num": 2, "word": "go for a walk", "phonetic": "", "pos": "短语", "meaning": "散步", "examples": [{"en": "Let's go for a walk in the countryside tomorrow.", "zh": "咱们明天到乡下去走走吧。"}], "sub_entries": ["=take a walk", "walk[wok]n.散步"]}, {"num": 3, "word": "mountain", "phonetic": "[ˈmauntn]", "pos": "n.", "meaning": "山", "examples": [], "sub_entries": []}, {"num": 4, "word": "hus. and", "phonetic": "[hazband]", "pos": "n.", "meaning": "丈夫", "examples": [], "sub_entries": []}, {"num": 5, "word": "tennis", "phonetic": "[ˈtenis]", "pos": "n.", "meaning": "网球", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Patty", "up at eight o'clock.", "(A) wake", "(B）rises", "(C) wakes (D) waking", "2. At seven o'clock I", "my homework.", "(A) does", "(B) do", "(C) writes", "(D) doing", "3.", "your coat. It's cold outside.", "(A) Take off (B) Put on (C) Wear(D) Put down", "4. Carl", "his dog on Sundays.", "(A) wash (B) walk (C) walking (D) washes", "5.1", "a shower in the morning.", "(A) do", "(B)take(C)wash", "(D) make", "6. I usually watch TV", "(A) for Saturdays", "(B) in Saturdays", "(C) on Saturdays", "(D) at Saturdays"], "answers": ["解答→1.(C）2.(B）3.(B）4.(D）5.(B）6.(C)"]}}, {"num": 27, "title_en": "Jack and His Dog", "title_zh": "杰克和他的狗", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Jack seldom gets together with his friends. He usually stays at home with his pet dog, Lucky. They sometimes go for long walks in the park. Although Jack is often alone, he is never lonely. He always tells his friends that a dog is man's best friend."], "zh": ["杰克很少与朋友在一起。他通常跟他的爱犬乐奇待在家里。他们有时候在公园里散步，走上好一阵子。虽然杰克经常单独一朋友。"]}, "dialog": null, "vocab": [{"num": 1, "word": "seldom", "phonetic": "[ˈseldam]", "pos": "adv.", "meaning": "很少", "examples": [{"en": "I seldom go to the movies.", "zh": "我很少去看电影。"}], "sub_entries": []}, {"num": 2, "word": "together", "phonetic": "[taˈɡedo]", "pos": "adv.", "meaning": "一起", "examples": [{"en": "Carl and I are working on this project together.", "zh": "卡尔和我正一起做这项计划。"}], "sub_entries": ["get together", "在一起"]}, {"num": 3, "word": "usually", "phonetic": "[ju3ual1]", "pos": "adv.", "meaning": "通常", "examples": [{"en": "I usually jog in the morning.", "zh": "我通常在早上慢跑。"}], "sub_entries": []}, {"num": 4, "word": "stay", "phonetic": "[ste]", "pos": "vi.", "meaning": "待在，停留在", "examples": [{"en": "Susie often stays at her grandmother's house on Saturdays.", "zh": "苏西星期六经常待在她奶奶家里。"}], "sub_entries": []}, {"num": 5, "word": "pet", "phonetic": "[pet]", "pos": "n.", "meaning": "宠物", "examples": [], "sub_entries": ["a pet dog", "爱犬", "a pet cat", "宠猫"]}, {"num": 6, "word": "sometimes", "phonetic": "[ˈsam.taimz]", "pos": "adv.", "meaning": "有时候", "examples": [{"en": "Patty sometimes falls asleep in class.", "zh": "帕蒂有时候会在课堂上睡着。"}], "sub_entries": []}, {"num": 7, "word": "go for a walk", "phonetic": "", "pos": "短语", "meaning": "去散步", "examples": [{"en": "I usually go for a walk after dinner.", "zh": "我通常在吃完晚饭后会去散步。"}], "sub_entries": ["=go for a stroll", "*stroll['strol]n.散步"]}, {"num": 8, "word": "park", "phonetic": "[park]", "pos": "n.", "meaning": "公园", "examples": [], "sub_entries": []}, {"num": 9, "word": "although", "phonetic": "[5lˈoo]", "pos": "conj.", "meaning": "虽然", "examples": [{"en": "Although Jane eats a lot of ice cream, she is not fat.", "zh": "虽然简吃了很多冰淇淋，但是她并不胖。"}], "sub_entries": []}, {"num": 10, "word": "often", "phonetic": "[ˈsfan]", "pos": "adv.", "meaning": "经常", "examples": [{"en": "Chris is often late for work.", "zh": "克里斯上班经常迟到。"}], "sub_entries": []}, {"num": 11, "word": "alone", "phonetic": "[alon]", "pos": "a.", "meaning": "单独的，独自的", "examples": [{"en": "Are you alone, or is somebody with you?", "zh": "你是一个人呢，还是有人跟你作伴？"}], "sub_entries": []}, {"num": 12, "word": "never", "phonetic": "[ˈnev?]", "pos": "adv.", "meaning": "绝对不，从不", "examples": [{"en": "Mother is always happy. She is never sad.", "zh": "我母亲总是很快乐。她从不会感到难过。"}], "sub_entries": []}, {"num": 13, "word": "lonely", "phonetic": "[lonli]", "pos": "a.", "meaning": "寂寞的", "examples": [], "sub_entries": []}, {"num": 14, "word": "always", "phonetic": "[ˈlwez]", "pos": "adv.", "meaning": "始终", "examples": [{"en": "I always play ping-pong on Saturday mornings.", "zh": "我总是在星期六早上打乒乓球。"}], "sub_entries": []}, {"num": 15, "word": "tell", "phonetic": "[tel]", "pos": "vt.", "meaning": "告诉", "examples": [{"en": "My teacher often tells us to study hard.", "zh": "我的老师常常告诉我们要用功读书。"}], "sub_entries": []}, {"num": 16, "word": "man", "phonetic": "[men]", "pos": "n.", "meaning": "人类（之前不置冠词）", "examples": [], "sub_entries": []}, {"num": 17, "word": "best", "phonetic": "[best]", "pos": "a.", "meaning": "最好的（good 的最高级）", "examples": [{"en": "Tim is the best basketball player on our team.", "zh": "蒂姆是我们队上最好的篮球运动员。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍频率副词与一般现在时的关系，并 介绍双重连接的错误句子结构及改正之道。", "items": [{"num": 1, "title": "频度副词的用法及在句中的位置", "body": ["本课出现了许多频度副词，计有 seldom（很少）、sometimes（有时）、often（经常）、usually（通常）、never（从不）、always（始终）等。频度副词通常使用在一般现在时中。注意这些频度副词在句中的位置：", "a. 句中有be 动词时，频率副词置于该be 动词之 后。", "例：John is always busy.（约翰总是很忙。）", "Chris is helpful. He is never selfish.（克里斯很乐于助人。他从不自私。）Because they live far away from here, they are sometimes late for work.（因为他们住的地方离这里很远，所以他们有 时候上班会迟到。）", "b. 句中有一般动词时，频率副词置于该动词之前。", "例：He usually goes to bed late.（他通常很晚才睡觉。）", "I seldom talk to him.（我很少跟他说话。）"]}, {"num": 2, "title": "Although Jack is often alone, he is never lonely.", "body": ["=Jack is often alone, but he is never lonely.（虽然杰克经常单独一个人，但是他从不感寂寞。）请读者注意下列要点：", "a. although亦可用though[o]代替，均表“虽 然”，作副词连词，引导状语从句，修饰主句。我 们因受中文语法“虽然·。但是·…”的影响，而可能 在英文里亦说\"although（或though)...but..\"，但 这是错误的用法，因为英文的语法规定两句间的连 词只能有.-个。\"although（或though)..but...\"之中，although（或though）与but均为连词，形 成错误的双重连接句子结构·故若采用although（或though)，则but应予省略；若采用but,则 although（或though）就应省略。", "例：Though he is nice, but I don't like him.（×）", "→ Though he is nice, I don't like him.(○)", "=He is nice, but I don't like him.（虽然他人不错，但是我不喜欢他。）", "b.\"Because...o...\"（因为.…..….所以.…...）亦是错误的 双重连接句子结构。故若采用because时，则不 可再用so；若采用so时，则不可再用because。", "例：Because he is nice, so we all like him.（×）", "-→Because he is nice, we all like him.（O)", "=He is nice, so'we all like him.（因为他人不错，所以我们都喜欢他。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 28, "title_en": "I Always Walk", "title_zh": "我都是走路去", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Chris", "speaker_zh": "克里斯", "en": "How do you go to school, Judy?", "zh": "朱迪，你是怎么上学的？"}, {"speaker_en": "Judy", "speaker_zh": "朱迪", "en": "I usually take a bus, but sometimes I ride my bicycle. What about you?", "zh": "我通常乘公共汽车，但有时候我骑自行车。你呢？"}, {"speaker_en": "Chris", "speaker_zh": "克里斯", "en": "I live near our school, so I always walk.", "zh": "我住在我们学校附近，因此我都是走路去。"}, {"speaker_en": "Judy", "speaker_zh": "朱迪", "en": "You're lucky.", "zh": "你真幸运。"}]}, "vocab": [{"num": 1, "word": "take a bus", "phonetic": "", "pos": "短语", "meaning": "乘公共汽车", "examples": [], "sub_entries": ["take a train", "乘火车", "take a taxi", "乘出租车"]}, {"num": 2, "word": "ride", "phonetic": "[rard]", "pos": "vt.", "meaning": "骑乘", "examples": [{"en": "Do you know how to ride a motorcycle?", "zh": "你知道怎么骑摩托车吗？"}], "sub_entries": []}, {"num": 3, "word": "near", "phonetic": "[nrr]", "pos": "prep.", "meaning": "在...…·附近", "examples": [], "sub_entries": []}, {"num": 4, "word": "lucky", "phonetic": "[ˈ1ki]", "pos": "a.", "meaning": "幸运的", "examples": [{"en": "Roger has a beautiful girlfriend. He is very lucky.", "zh": "罗杰有个很漂亮的女友，他真是幸运。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Mark is very lazy. He is", "late for class.", "(A) rarely (B) never (C) seldom (D) always", "2. Paul is very hardworking. He", "watches TV.", "(A) rarely (B) always (C) usually (D) often", "3. Mary", "walks to school. She always takes a", "bus.", "(A) never (B) often (C) sometimes (D) usually", "4.Jack is very shy. He", "talks to people.", "(A) always (B) usually (C) often (D) seldom", "5.Bill is afraid of cold weather. He", "swims", "in the winter.", "(A） always (B) usually (C) never (D) often"], "answers": ["解答>1.(D）2.(A）3.(A）4.(D）5.(C)"]}}, {"num": 29, "title_en": "Poor Dick", "title_zh": "可怜的迪克", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["There are holes in Dick's shoes. He needs new shoes. Dick doesn't want cheap shoes. He wants expensive shoes, but he doesn't have any money. He needs a job. He is looking for one, but he isn't having any luck. No one wants to give him a job because his shoes have holes in them. Poor Dick!"], "zh": ["迪克的鞋子有破洞。他需要新鞋子。迪克不想要便宜的鞋子。他想要贵的鞋子，但他没钱。他需要一份工作。他正在找工作，但他的运气不好。因为他的鞋子有破洞，所以没有人给他工作。可怜的迪克！"]}, "dialog": null, "vocab": [{"num": 1, "word": "hole", "phonetic": "[hol]", "pos": "n.", "meaning": "破洞；小洞", "examples": [], "sub_entries": []}, {"num": 2, "word": "shoe", "phonetic": "[ʃu]", "pos": "n.", "meaning": "鞋子", "examples": [{"en": "I want to buy a pair of black leather shoes.", "zh": "我想买一双黑皮鞋。"}], "sub_entries": ["a pair of shoes", "双鞋"]}, {"num": 3, "word": "need", "phonetic": "[nid]", "pos": "vt.", "meaning": "需要", "examples": [{"en": "Do you need any help?", "zh": "你需要任何帮助吗？"}], "sub_entries": []}, {"num": 4, "word": "want", "phonetic": "[want]", "pos": "vt.", "meaning": "想要", "examples": [{"en": "I want to study abroad.", "zh": "我想去国外念书。"}], "sub_entries": []}, {"num": 5, "word": "cheap", "phonetic": "[thip]", "pos": "a.", "meaning": "便宜的，廉价的", "examples": [{"en": "Most vegetables are cheap in the summer.", "zh": "人部分的蔬菜在夏天都很便宜。"}], "sub_entries": []}, {"num": 6, "word": "expensive", "phonetic": "[ikˈspensiv]", "pos": "a.", "meaning": "昂贵的", "examples": [{"en": "This diamond ring is very expensive.", "zh": "这只钻石戒指非常昂贵。"}], "sub_entries": []}, {"num": 7, "word": "any", "phonetic": "[ˈεnr]", "pos": "a.", "meaning": "任何的", "examples": [], "sub_entries": []}, {"num": 8, "word": "money", "phonetic": "[ˈmani]", "pos": "n.", "meaning": "钱", "examples": [], "sub_entries": []}, {"num": 9, "word": "job", "phonetic": "[d3ab]", "pos": "n.", "meaning": "I作", "examples": [{"en": "Do you have a full-time job?", "zh": "你有全职的工作吗？"}], "sub_entries": []}, {"num": 10, "word": "look", "phonetic": "[lʊk]", "pos": "vi.", "meaning": "寻找（与介词for并用）", "examples": [{"en": "What is she looking for?", "zh": "她在寻找什么？"}], "sub_entries": ["look for...", "寻找··…"]}, {"num": 11, "word": "luck", "phonetic": "[lak]", "pos": "n.", "meaning": "幸运", "examples": [], "sub_entries": []}, {"num": 12, "word": "poor", "phonetic": "[pur]", "pos": "a.", "meaning": "可怜的", "examples": [{"en": "Poor Billy has a terrible cold.", "zh": "可怜的比利感冒得很严重。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍no与not的区别、代词one的用法，并 复习连词but及because的用法。", "items": [{"num": 1, "title": "He wants expensive shoes, but he doesn't have any money.", "body": ["=He wants expensive shoes, but he has no mo1.ey.（他想要贵的鞋子，但他没钱。）no与not对初学英文的读者来说，有时是个头痛的 问题。请先看下例：", "I have not money. (×)-> I have no money. (○)（我没有钱。）其实no与not 很容易分辨：", "a. no是形容词，表示“没有一个”，而not 则是副 词，表示“不”的意思。", "b. no就等于not any（没有任何一个）。换言之，no之后可直接置名词，而not则须先接形容词 any，才可接名词。", "例：I have not any money.(可)", "=I have no money.（佳，no 比 not any 更 简洁）（我没有钱。）", "注意:", "上列第一句中，not亦可置于动词have之前，形 成否定句。但not不能直接修饰动词，须于其前 按主语人称分置助动词do或does，再将动词改为 原形。", "例：He not has any money.(×)", "-→ He does not have any money. (○)", "=He doesn't have any money.", "=He has no money.（他没有钱。）"]}, {"num": 2, "title": "He wants expensive shoes, but he doesn't have any money.", "body": ["（他想要贵的鞋子，但他没钱。）He is looking for one, but he isn't having any luck.（他正在找工作，但他的运气不好。）以上两句中的but是并列连词·这种连词连接两个主 句·就写作习惯而言，but之前应置逗号。不过，现 在的英美文章中，亦常见将but之前的逗号省略。"]}, {"num": 3, "title": "He needs a job. He is looking for one, but he isn't having any luck.", "body": ["（他需要一份工作。他正在找工作，但他的运气不 好。）", "a. 上列第二句中的one是代词，代替前面的名词a job·原句实为：", "He needs a job. He is looking for a job, but... 但ajob重覆了一次，就修辞而言应予避免，故用 one代替·这个one专用来代替其前提过之单数 可数名词·", "例：I need a_good English dictionary, but I can't afford a good English dictionary", "now.（劣）>I need a good English dictionary, but I can't afford one now.（佳）（我需要一本好的英文字典，但我现在买不 起。）", "b. one 亦可与形容词并用。", "例：I don't like this red pen.", "Give yellow pen.（劣）", "=I don't like this red pen. Give me a yellow one.（佳）（我不喜欢这枝红色的笔·给我·－枝黄色的 笔。）"]}, {"num": 4, "title": "No one wants to give him a job because his shoes have holes in them.", "body": ["（因为他的鞋子有破洞，所以没有人给他工作。）本句中的because是从属连词，引导状语从句，修饰 主句。because引导的从句可置于主句前后。就写作 习惯而言，置于主句之前时，主句与从句之间应置逗 号；若置于主句之后时，则主句与从句之间不置逗 号。", "例：Because he is knowledgeable, he has my respect.", "=He has my respect because he is knowledgeable.（因为他有学问，所以我尊敬他。）其他从属连词如although（=though，虽然）、when（当）、if（如果）等用法皆同。", "例：Although he is rich, I don't envy him.", "=I don't envy him although he is rich.（虽然他有钱，可我不嫉妒他。）", "If I have time, I will do it.", "=I will do it if I have time.（我若有时间，就会做这件事。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 30, "title_en": "Money Doesn't Grow on Trees", "title_zh": "挣钱是很辛苦的", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Sam", "speaker_zh": "萨姆", "en": "Mother, can you buy me a new bike?", "zh": "妈，您可不可以买一辆新的自行车给我？"}, {"speaker_en": "Mother", "speaker_zh": "妈妈", "en": "No, Sam. I can't.", "zh": "不可以，萨姆。我办不到。"}, {"speaker_en": "Sam", "speaker_zh": "萨姆", "en": "But all my friends have new bicycles.", "zh": "但是我所有的朋友都有新车。"}, {"speaker_en": "Mother", "speaker_zh": "妈妈", "en": "You can ride their bikes.", "zh": "你可以骑他们的车子呀！"}, {"speaker_en": "Sam", "speaker_zh": "萨姆", "en": "Why can't I have a new bike?", "zh": "我为什么不能有辆新车呢？"}, {"speaker_en": "Mother", "speaker_zh": "妈妈", "en": "Because money doesn't grow on trees.", "zh": "因为钱不会长在树上嘛（喻挣钱是很辛苦的）。"}]}, "vocab": [{"num": 1, "word": "buy+人+物", "phonetic": "", "pos": "", "meaning": "买某物给某人", "examples": [{"en": "Romeo buys his wife flowers every day. =Romeo buys flowers for his wife every day.", "zh": "罗密欧每天都买花送他太太。"}], "sub_entries": ["=buy+物+for+人"]}, {"num": 2, "word": "ride", "phonetic": "[raid]", "pos": "vt.", "meaning": "骑（马、自行车等），乘坐（公共汽", "examples": [{"en": "Can you ride a horse? I always ride the train to work.", "zh": "你会骑马吗？）（我都是乘火车上班的。"}], "sub_entries": ["车、火车等）"]}, {"num": 3, "word": "grow", "phonetic": "[ɡro]", "pos": "vi.", "meaning": "生长", "examples": [{"en": "All flowers need water to grow.", "zh": "花都需要水才能生长。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Mary doesn't like this dress. She likes", "over there.", "(A) the red one (B) the red (C) red (D) a red", "2. John is looking", "a good English dictionary.", "(A) on", "(B)around", "(C) into", "(D) for", "3.He can't come", "he is busy now.", "(A) though (B) but (C) because (D) although", "4. He is sad because he", "money.", "(A) has no any", "(B) not has", "(C) not has any", "(D) doesn't have any", "5. Tim often", "his children.", "(A) buys toys", "(B) buys toys for", "(C) buys for his toys", "(D) buys toys to"], "answers": ["解答1.(A）2.(D）3.(C）4.(D）5.(B)"]}}, {"num": 31, "title_en": "Poor Amy", "title_zh": "可怜的艾米", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Amy can't pay this month's rent. She needs some help. Unfortunately, none of her friends can help her. They don't have any money, either. Poor Amy is really depressed. She has no money, and the landlord is knocking at the door. Amy is very nervous. She shouts, \"No one is home!\""], "zh": ["艾米这个月的房租付不出来。她需要一些帮助。不幸的是，她的朋友没有一个能帮助她。他们也没钱。可怜的艾米真地很沮丧·她没钱，而房东这时正在敲门。艾米很紧张。她叫道：“没人在家！”"]}, "dialog": null, "vocab": [{"num": 1, "word": "pay", "phonetic": "[peɪ]", "pos": "vt.", "meaning": "付（钱）", "examples": [{"en": "Can you pay the telephone bill today?", "zh": "你今天可以去付电话费吗？"}], "sub_entries": []}, {"num": 2, "word": "rent", "phonetic": "[rent]", "pos": "n.", "meaning": "房租", "examples": [], "sub_entries": []}, {"num": 3, "word": "help", "phonetic": "[help]", "pos": "n.", "meaning": "&vt.帮助", "examples": [{"en": "Thank you very much for your help. Help your mother (to) wash the dishes.", "zh": "非常感谢你的帮忙。）（去帮你母亲洗碗。"}], "sub_entries": []}, {"num": 4, "word": "unfortunately", "phonetic": "[ʌnˈfɔːrtʃənətli]", "pos": "adv.", "meaning": "不幸的是", "examples": [{"en": "I should see a doctor. Unfortunately, I don't have any time.", "zh": "我应该去看医生·不幸的是，我没有时间。"}], "sub_entries": []}, {"num": 5, "word": "none", "phonetic": "[nan]", "pos": "pron.", "meaning": "没有一个", "examples": [{"en": "None of the students know the answer.", "zh": "这些学生中没有一个知道答案。"}], "sub_entries": ["none of +the+复数名词", "·…··…之中没有一个"]}, {"num": 6, "word": "really", "phonetic": "[riali]", "pos": "adv.", "meaning": "真正地", "examples": [{"en": "Sam really loves studying English.", "zh": "萨姆真的很爱读英文。"}], "sub_entries": []}, {"num": 7, "word": "depressed", "phonetic": "[diˈprest]", "pos": "a.", "meaning": "沮丧的，难过的", "examples": [{"en": "Carl is depressed because his bicycle is broken.", "zh": "卡尔很沮丧，因为他的自行车坏了。"}], "sub_entries": []}, {"num": 8, "word": "landlord", "phonetic": "[landlord]", "pos": "n.", "meaning": "房东", "examples": [], "sub_entries": ["tenant['tenant ]n.房客"]}, {"num": 9, "word": "knock", "phonetic": "[nok]", "pos": "vi.", "meaning": "敲（门]）", "examples": [], "sub_entries": ["knock the door （×）", "knock at the door （O)", "敲门"]}, {"num": 10, "word": "nervous", "phonetic": "[ˈn3vas]", "pos": "a.", "meaning": "紧张的", "examples": [{"en": "Exams make me very nervous.", "zh": "考试使我很紧张。"}], "sub_entries": []}, {"num": 11, "word": "shout", "phonetic": "[ʃaʊt]", "pos": "vt.", "meaning": "高呼，大声说出", "examples": [{"en": "My teacher often shouts, \"Shut up!\" when we are noisy.", "zh": "当我们吵闹时，老师常会大叫：“闭嘴！”"}], "sub_entries": []}], "grammar": {"intro": "本课介绍形容词some及代词none的用法。", "items": [{"num": 1, "title": "She needs some help.", "body": ["（她需要一些帮助。）此处some [sʌm]为形容词，表示“一些”。此外，亦可表示“某个”的意思，用法如下：", "a. 作“一些”解时，之后可接复数可数名词（如 friends、books）或不可数名词（如money help）。", "例: Peter has some very good English books.（彼得有一些很棒的英文书。）", "I have some money.（我有一些钱。）", "b. 作“某个”解时，之后接单数可数名词。此时的 some相当于不定冠词a或an。", "例： Some guy is looking for you.", "=A guy is looking for you.（某个家伙正在找你。）"]}, {"num": 2, "title": "...none of her friends can help her.", "body": ["（...她的朋友没有一个能帮助她。）本句中的none是代词，可用来代替人或物，指三个或 三个以上的人或东西中“没有一个”，用法如下：", "\"、o、、s、o+复数名词+复数（或单数）动词", "例：None of my friends like(s)music.（我的朋友中没有一个喜欢音乐。）", "None of those books are/is interesting.（那些书中没有一本是有趣的。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 32, "title_en": "Coins for the Phone", "title_zh": "打投币电话", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Roy", "speaker_zh": "罗伊", "en": "Hi, Connie! Do you have any change?", "zh": "嗨，康妮！你有零钱吗？"}, {"speaker_en": "Connie", "speaker_zh": "康妮", "en": "What for?", "zh": "下嘛？"}, {"speaker_en": "Roy", "speaker_zh": "罗伊", "en": "I want some coins for the pay phone.", "zh": "我想要些硬币打投币电话。"}, {"speaker_en": "Connie", "speaker_zh": "康妮", "en": "I see. Here you are.", "zh": "我明白了·拿去吧！"}, {"speaker_en": "Roy", "speaker_zh": "罗伊", "en": "Thank you.", "zh": "谢谢你。"}, {"speaker_en": "Connie", "speaker_zh": "康妮", "en": "You're welcome.", "zh": "别客气。"}]}, "vocab": [{"num": 1, "word": "change", "phonetic": "[tjend3]", "pos": "n.", "meaning": "零钱（不可数）", "examples": [], "sub_entries": []}, {"num": 2, "word": "Do you have any change?", "phonetic": "", "pos": "日常口语", "meaning": "你有零钱吗？", "examples": [{"en": "Do you need any help?", "zh": "你需要帮助吗？）2）否定句："}, {"en": "He doesn't need any help.", "zh": "他不需要任何帮助。）3）肯定句："}, {"en": "He needs some help.", "zh": "他需要一些帮助。"}], "sub_entries": ["I want some coins for the pay phone.", "（我想要些硬币打投币电话。）", "any与some 均可作数量形容词，之后均可置可数或", "不可数名词，但用法有别：", "a.any使用于疑问句或否定句中；", "b.some使用于肯定句中。", "1）疑问句："]}, {"num": 3, "word": "What for?", "phonetic": "", "pos": "日常口语", "meaning": "为什么？", "examples": [], "sub_entries": ["=Why?"]}, {"num": 4, "word": "coin", "phonetic": "[kin]", "pos": "n.", "meaning": "硬币", "examples": [], "sub_entries": []}, {"num": 5, "word": "pay phone", "phonetic": "[ˈpe fon]", "pos": "n.", "meaning": "投币电话，付费电话", "examples": [], "sub_entries": []}, {"num": 6, "word": "I see.", "phonetic": "", "pos": "日常口语", "meaning": "我明白了。", "examples": [{"en": "A: Bill is studying for his test. B: Oh, I see.", "zh": "甲：比尔正在为他的考试而念书。）（乙：哦，我知道了。"}], "sub_entries": ["=I understand.", "*understand[Anda'stand]vi.了解"]}, {"num": 7, "word": "Here you are.", "phonetic": "", "pos": "日常口语", "meaning": "拿去吧！", "examples": [{"en": "A: Please pass me the salt. B: Here you are.", "zh": "甲：请把盐递给我。）（乙：拿去吧！"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. He doesn't have", "friends.", "(A) some", "(B)any", "(C) no", "(D) none", "2.", "can sing.", "(A) None my friends", "(B) None of my friends", "(C) None of friends", "(D) No of friends", "3.", "does he have?", "(A) How many change", "(B)How many changes", "(C) How much change", "(D）Howmuch changes", "4. I don't have", "with me.", "(A) some moneys", "(B) any moneys", "(C) some money", "(D) any money", "5. 1 have", "questions.", "(A) some", "(B) any (C) none", "(D) no any"], "answers": ["解答→1.(B）2.(B）3.(C）4.(D）5.(A)"]}}, {"num": 33, "title_en": "She Wants to Wear Something Formal", "title_zh": "她想穿正式的衣服", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Judy is looking for something nice to wear for a job interview. She wants to wear something formal. Unfortunately, she doesn't have anything except casual clothes. Judy is worried. She has nothing suitable to wear, so she puts on her best casual clothes. She goes to the interview. Guess what? Judy gets the job!"], "zh": ["朱迪正在寻找求职面试时要穿的一件好衣服·她想要穿正式的衣服。不幸的是，她除了休闲装以外，没别的衣服。朱迪很焦急·她没有适当的衣服可穿，于是她穿上了她最好的休闲装。她面试去了。你猜怎么了？朱迪得到了那份工作！"]}, "dialog": null, "vocab": [{"num": 1, "word": "interview", "phonetic": "[ˈnto.vju]", "pos": "n.", "meaning": "面试", "examples": [{"en": "I am nervous at interviews.", "zh": "我面试时都会紧张。"}], "sub_entries": []}, {"num": 2, "word": "formal", "phonetic": "[ˈforml]", "pos": "a.", "meaning": "正式的", "examples": [{"en": "People wear formal clothes at weddings.", "zh": "婚礼时人们都穿着正式的服装。"}], "sub_entries": []}, {"num": 3, "word": "except", "phonetic": "[kˈsept]", "pos": "prep.", "meaning": "除.....之外", "examples": [{"en": "My father works every day except on Sundays.", "zh": "我父亲除了星期天外，每天都要工作。"}], "sub_entries": []}, {"num": 4, "word": "casual", "phonetic": "[ˈkæʒuəl]", "pos": "a.", "meaning": "休闲的", "examples": [], "sub_entries": ["casualclothes", "便服，休闲装"]}, {"num": 5, "word": "worried", "phonetic": "[ˈwɜːrid]", "pos": "a.", "meaning": "忧虑的，焦急的", "examples": [{"en": "I am worried about my sick mother.", "zh": "我很担心我生病的母亲。"}], "sub_entries": []}, {"num": 6, "word": "suitable", "phonetic": "[ˈsutabl]", "pos": "a.", "meaning": "适合的", "examples": [{"en": "Shorts are not suitable for cold weather.", "zh": "短裤不适合在寒冷的天气时穿。"}], "sub_entries": []}, {"num": 7, "word": "guess", "phonetic": "[ɡes]", "pos": "vt.", "meaning": "猜", "examples": [{"en": "Can anyone guess the answer?", "zh": "有谁能猜出答案吗？"}], "sub_entries": []}], "grammar": {"intro": "本课介绍\"something/anything/nothing+形容词\"的 后位修饰结构，以及介词except的用法·", "items": [{"num": 1, "title": "复合不定代词 something, anything, nothing 的用法", "body": ["something['sʌmθɪŋ]（某物/某事）、anything['ɛnɪˌθɪŋ]（任何事物）、nothing['nʌθɪŋ]（无事/无物）均为代词，可代替物或事情；代替物时，可指衣服、食物、家具等。", "a. 形容词修饰一般名词时，通常置于该名词前。但形 容词修饰 something、anything、nothing等代 词时，该形容词应置于这些代词之后，这种结构称 为后位修饰。", "例：He is a boy good.(×)", "→He is a good boy. (○)（他是好孩子。）I have good something for you. (×)", "→ I have something good for you. (○)（我有好东西给你。）I can't find good anything at the store.（×）", "→I can't find anything_good at the store.（o)（在那家商店我找不到任何好货。）He is doing wrong nothing. (×)", "→ He is doing nothing wrong. (○)（他没有在做不对的事。）", "b. something、anything、nothing 无复数形。", "例：I have somethings to do.（×）", "→ I have something to do. (○)（我有事要做。）", "c. something使用于肯定句中；anything使用于否定 句及疑问句中；nothing本身具否定意味，不可再 与否定句连用形成双重否定。(1) something", "例：I don't have something important to", "tell you.（×，something不可用于否定 句中)-->I have something important to tell you.（O，something用于肯定句中）（我有重要的事要告诉你。）(2) anything", "例: Do you have anything important to tell", "me？（O，anything用于疑问句中）（你有任何重要的事要告诉我吗？）I don't have anything important to tell you.（O，anything用于否定句中）（我没有重要的事要告诉你。）(3) nothing", "例：I don't have nothing important to tell", "you.（×，nothing已具否定意思，故不得 再与否定副词not并用，否则形成错误的 双重否定）", "→ I have nothing important to tell you.（0)", "=I don't have anything important to tell you.（我没有重要的事要告诉你。）"]}, {"num": 2, "title": "Unfortunately, she doesn't have anything except casual clothes.", "body": ["（不幸的是，她除了休闲装以外，没别的衣服。）本句的except是介词，表示“除·..…·之外”，使用 时要置于有all（所有的）、no（没有一个）、any（任何个）、every（每-一个）等含有完全意义的形 容词所修饰的名词之后。", "例：All the boys like music except John.（除了约翰以外，所有男孩都喜欢音乐。）", "He has nothing except money.（他除了钱以外，什么都没有。）He likes everybody except me.（他除了我以外，谁都喜欢；他喜欢每个人，就 是不喜欢我。）I don't like anyone except Mary.（我除了玛丽以外，谁都不喜欢。）了解上述有关except的用法后，我们就不可再造下 列错误的句子：", "例: Many boys are good except him.( ×， many", "表“许多”，不含有完全的意义，故不能与 except并用）", "→All the boys are good except him. (○)（除了他以外，所有男孩都很好。）I like. some girls here except Mary. ( × , some表“一些”，不含有完全的意义，故 不能与except并用）", "→I like every girl here except Mary. (○)", "= I like all the girls here except Mary.（除了玛丽以外，这里的女孩我都喜欢。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 34, "title_en": "Let's Go to a Disco", "title_zh": "咱们到迪斯科舞厅去", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Peter", "speaker_zh": "彼得", "en": "Hi, Paula! What are you doing?", "zh": "嗨，波拉！你在做什么？"}, {"speaker_en": "Paula", "speaker_zh": "波拉", "en": "Nothing special.", "zh": "没什么特别的事。"}, {"speaker_en": "Peter", "speaker_zh": "彼得", "en": "Let's do something together.", "zh": "咱们一块做些事好了。"}, {"speaker_en": "Paula", "speaker_zh": "波拉", "en": "Do you have anything in mind?", "zh": "你有什么想法没有？"}, {"speaker_en": "Peter", "speaker_zh": "彼得", "en": "Let's go to a disco.", "zh": "咱们到迪斯科舞厅去。"}, {"speaker_en": "Paula", "speaker_zh": "波拉", "en": "Great! Can your handsome brother come, too?", "zh": "太棒了！你那英俊的哥哥是否也可以来？"}]}, "vocab": [{"num": 1, "word": "special", "phonetic": "[ˈspeal]", "pos": "a.", "meaning": "特别的", "examples": [], "sub_entries": []}, {"num": 2, "word": "together", "phonetic": "[tˈɡed]", "pos": "adv.", "meaning": "一起", "examples": [{"en": "Do you want to go to the party together?", "zh": "你想要一起去参加宴会吗？"}], "sub_entries": []}, {"num": 3, "word": "mind", "phonetic": "[maind]", "pos": "n.", "meaning": "头脑，心里", "examples": [{"en": "Do you have anybody in mind for the job?", "zh": "这工作你心里有任何人选没有？"}], "sub_entries": ["have...in mind", "心里想着···"]}, {"num": 4, "word": "disco", "phonetic": "[ˈdisko]", "pos": "n.", "meaning": "迪斯科舞厅", "examples": [], "sub_entries": []}, {"num": 5, "word": "handsome", "phonetic": "[ˈhansam]", "pos": "a.", "meaning": "（指男士）英俊的", "examples": [{"en": "You look very handsome today.", "zh": "你今天看起来很英俊。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. I don't have", "to eat.", "(A) anything", "(B) nothing", "(C) something", "(D) any", "2. We have", "to do.", "(A) anything", "(B)some", "(C) nothing", "(D) none", "3. 1 have", "to say.", "(A) anything", "(B) anythings", "(C) somethings", "(D) something", "4. Do you want", "to eat?", "(A) any", "(B) anything", "(C) some", "(D) none", "5. 1 have nothing to wear", "dirty clothes.", "(A) and", "(B)except", "(C) some", "(D) no", "6. Sam : Let's get something to eat.", "Sally: OK. Do you", "？", "(A) any place have in mind", "(B) any place in mind", "(C) have in mind", "(D) have any place in mind"], "answers": ["解答→1.(A）2.(C）3.(D）4.(B）5.(B）6.(D)"]}}, {"num": 35, "title_en": "There's Little Food", "title_zh": "饭菜很少", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Fred's having a party, but he's very embarrassed. There are many people at his party, but there's very little food. There's very little meat. There isn't much rice, either. There are only a few cans of coke and a little orange juice. However, everyone is happy at the party because there's plenty of beer."], "zh": ["弗雷德在开宴会，但是他觉得很不好意思。赴宴的人很多，不过饭菜却很少。肉很少，饭也不够多。只有几罐可乐和一些橙汁·不过，因为啤酒很多，所以宴会上每个人都很高兴。"]}, "dialog": null, "vocab": [{"num": 1, "word": "embarrassed", "phonetic": "[imˈbarast]", "pos": "a.", "meaning": "困窘的，不好意思的", "examples": [{"en": "I am embarrassed to wear dirty clothes.", "zh": "穿脏衣服让我觉得很不好意思。"}], "sub_entries": []}, {"num": 2, "word": "many", "phonetic": "[ˈmeni]", "pos": "a.", "meaning": "许多的（之后接复数名词）", "examples": [{"en": "Mr. Lee has many children.", "zh": "李先生有许多孩子。"}], "sub_entries": []}, {"num": 3, "word": "little", "phonetic": "[“litl]", "pos": "a.", "meaning": "很少的（之后接不可数名词）", "examples": [{"en": "I have very little homework tonight.", "zh": "我今晚的功课很少。"}], "sub_entries": []}, {"num": 4, "word": "food", "phonetic": "[fud]", "pos": "n.", "meaning": "食物（不可数）", "examples": [], "sub_entries": []}, {"num": 5, "word": "meat", "phonetic": "[miːt]", "pos": "n.", "meaning": "肉（不可数）", "examples": [], "sub_entries": []}, {"num": 6, "word": "much", "phonetic": "[matf]", "pos": "a.", "meaning": "许多的（之后接不可数名词）", "examples": [], "sub_entries": []}, {"num": 7, "word": "rice", "phonetic": "[rais]", "pos": "n.", "meaning": "米，饭（不可数）", "examples": [], "sub_entries": []}, {"num": 8, "word": "few", "phonetic": "[fju]", "pos": "", "meaning": "a．很少的，没几个（之后接复数名词）", "examples": [{"en": "Only a few of my friends smoke cigarettes.", "zh": "我的朋友中只有少数人抽烟。"}], "sub_entries": ["onlyafew", "〇只有几个"]}, {"num": 9, "word": "can", "phonetic": "[kaen]", "pos": "n.", "meaning": "罐头", "examples": [], "sub_entries": []}, {"num": 10, "word": "coke", "phonetic": "[kok]", "pos": "n.", "meaning": "可乐（COCA-COLA可口可乐的缩", "examples": [], "sub_entries": ["写形）"]}, {"num": 11, "word": "orange", "phonetic": "[ˈɔːrɪndʒ]", "pos": "n.", "meaning": "橙", "examples": [], "sub_entries": []}, {"num": 12, "word": "juice", "phonetic": "[dʒuːs]", "pos": "n.", "meaning": "果汁", "examples": [], "sub_entries": []}, {"num": 13, "word": "plenty", "phonetic": "[ˈplenti]", "pos": "pron.", "meaning": "充分，够多", "examples": [{"en": "There'splentyofcoffeeandteainthe kitchen.", "zh": "厨房里有很多的咖啡和茶。"}], "sub_entries": ["plenty of...", "很多的……·…，不少的….", "（之后可接复数名词或不可数名词）"]}, {"num": 14, "word": "beer", "phonetic": "[bir]", "pos": "n.", "meaning": "啤酒", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍表示数量的形容词（如many、few、little、 much等）的用法。 这些形容词亦称不定代词，有的之后要接复数名词，有的 只能接不可数名词，有的则两者皆可·兹列述如下：", "items": [{"num": 1, "title": "之后须接复数名词者：", "body": ["few", "极少，没有几个", "a few", "有几个", "several", "数个（意思接近 a few，但数目较 a few 多）", "many", "许多个", "例：He has few friends.（他没几个朋友——他的朋友很少。）", "I have a few friends.（我有几个朋友。）", "She has many friends.（她有许多朋友。）", "注意：", "a. few 表示“没几个”，有否定意味；a few 表示“有几个”，有肯定意味。", "b. quite a few: 不少的，相当多的（= many）", "例：He has quite a few friends.（他朋友不少。）", "c. only a few: 只有几个（= few 没几个）", "例：Mary has only few friends. (×)", "→ Mary has only a few friends. (○)（玛丽只有几位朋友。）"]}, {"num": 2, "title": "之后须接不可数名词者：", "body": ["little", "很少，没多少", "a little", "有一点", "much", "许多", "例：He has little money.（他没有钱——一点钱都没有。）", "He has a little money.（他有点钱。）", "He doesn't have much money.（他的钱不多。）", "注意：", "a. little 表示“很少/没多少”，有否定意味；a little 表示“有一点”，有肯定意味。", "b. quite a little: 不少的，相当多的", "例：He has quite a little money.（他的钱不少。）", "c. much 多用于否定句中，在肯定句中多用 a lot of 或 lots of 代替。", "例：He has much money. (劣)", "He doesn't have much money. (○)（他的钱不多。）", "He has a lot of / lots of money. (○)（他很有钱。）", "d. a great deal of 表示“大量的”，之后接不可数名词。", "例：He has a great deal of money. = He has a lot of money.（他很有钱。）"]}, {"num": 3, "title": "之后可接复数名词或不可数名词者：", "body": ["some", "一些", "a lot of (= lots of)", "许多", "plenty of", "很多的，充裕的", "例：He has some friends / money.（他有一些朋友/有一点钱。）", "He has a lot of (lots of) friends / money.（他有许多朋友/很多钱。）", "He has plenty of friends / money.（他有很多朋友/充裕的钱。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 36, "title_en": "A Lot of Bills", "title_zh": "许多帐单", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Al", "speaker_zh": "艾尔", "en": "Do you have any money with you?", "zh": "你身上带钱了吗？"}, {"speaker_en": "Sue", "speaker_zh": "苏", "en": "Not much. Why?", "zh": "我带的不多。干嘛问这个？"}, {"speaker_en": "Al", "speaker_zh": "艾尔", "en": "I need to borrow some.", "zh": "我需要借点钱。"}, {"speaker_en": "Sue", "speaker_zh": "苏", "en": "What's the matter?", "zh": "怎么回事？"}, {"speaker_en": "Al", "speaker_zh": "艾尔", "en": "I have a lot of bills to pay this month.", "zh": "这个月我有许多帐单要付。"}]}, "vocab": [{"num": 1, "word": "need", "phonetic": "[nid]", "pos": "vt.", "meaning": "需要", "examples": [{"en": "You need to be more patient.", "zh": "你需要有耐心一点。"}], "sub_entries": ["needto+动词原形", "需要····"]}, {"num": 2, "word": "borrow", "phonetic": "[ˈbaro]", "pos": "vt.", "meaning": "借", "examples": [{"en": "Can I borrow a pen from you?", "zh": "我可以向你借一支笔吗？"}], "sub_entries": ["borrow+物+from+人", "向某人借某物"]}, {"num": 3, "word": "matter", "phonetic": "[ˈmato]", "pos": "n.", "meaning": "事情", "examples": [], "sub_entries": ["What's the matter (with you)?", "（你）怎么啦？", "= What's wrong (with you)?"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. There are", "pencils on the table.", "(A) a few", "(B)much", "(C) little", "(D)a little", "2. We need", "food for theparty.", "(A) many", "(B) several", "(C) a lot", "(D) lots of", "3. How", "students are in the room?", "(A)much", "(B) few", "(C) many", "(D) a few", "4. There is", "juice in the refrigerator.", "(A)lots", "(B) a little", "(C) a lots of", "(D) many", "5. There are", "children playing in the yard.", "(A)a little", "(B)much", "(C) several", "(D) severals", "6. There is something", "with Fred.", "(A) matter", "(B） the matter", "(C) the wrong", "(D) what's wrong"], "answers": ["解答>1.(A）2.(D）3.(C）4.(B）5.(C）6.(B)"]}}, {"type": "song", "id": "song_02", "title_en": "All I Have to Do Is Dream", "title_zh": "我只能梦想", "lyrics": [], "category": "经典英文金曲赏析"}, {"num": 37, "title_en": "A Wonderful Time", "title_zh": "美好时光", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My girlfriend and I had a wonderful time last night. First, I took her to a cozy restaurant for dinner. Then, we went to a concert. Finally, we had some coffee at a nearby cafe. Just before we parted, she gave me a goodnight kiss. At that moment, I was on top of the world. And now I'm in love."], "zh": ["我和女友昨晚共度了一段美好时光。首先我带她到一家舒适的餐厅吃晚饭。然后我们就去听演唱会·最后我们在附近的一家咖啡厅喝点咖啡。就在我们分手前，她给了我一个晚安之吻。就在那一刻，我飘飘欲仙。现在我恋爱了。"]}, "dialog": null, "vocab": [{"num": 1, "word": "girlfriend", "phonetic": "[ˈɡalfrend]", "pos": "n.", "meaning": "女朋友", "examples": [], "sub_entries": ["boyfriend['boifrend]n.男朋友"]}, {"num": 2, "word": "wonderful", "phonetic": "[ˈwandafal]", "pos": "a.", "meaning": "美妙的，棒的", "examples": [{"en": "This is a wonderful party.", "zh": "这是个很棒的宴会。"}], "sub_entries": []}, {"num": 3, "word": "last night", "phonetic": "", "pos": "短语", "meaning": "昨晚", "examples": [], "sub_entries": []}, {"num": 4, "word": "first", "phonetic": "[fɜːrst]", "pos": "adv.", "meaning": "首先", "examples": [], "sub_entries": []}, {"num": 5, "word": "took", "phonetic": "[tuk]", "pos": "vt.", "meaning": "带，载（take[tek]的过去式）", "examples": [{"en": "Can you take me to school tomorrow?", "zh": "你明天可以带我去学校吗？"}], "sub_entries": ["take+人+to+地方带（载）某人到某地"]}, {"num": 6, "word": "cozy", "phonetic": "[ˈkoʊzi]", "pos": "a.", "meaning": "舒适的", "examples": [{"en": "Joe lives in a cozy little house in the countryside.", "zh": "乔住在乡下的一幢舒适小屋中。"}], "sub_entries": []}, {"num": 7, "word": "restaurant", "phonetic": "[ˈrestarant/ˈresta.rant]", "pos": "n.", "meaning": "餐厅", "examples": [], "sub_entries": []}, {"num": 8, "word": "went", "phonetic": "[went]", "pos": "vi.", "meaning": "去（go[go]的过去式）", "examples": [{"en": "We need to go to the supermarket.", "zh": "我们需要到超级市场去一趟。"}], "sub_entries": ["goto+地方到某地去"]}, {"num": 9, "word": "concert", "phonetic": "[ˈkansat]", "pos": "n.", "meaning": "演唱会，音乐会", "examples": [], "sub_entries": []}, {"num": 10, "word": "finally", "phonetic": "[ˈfaɪnəli]", "pos": "adv.", "meaning": "最后", "examples": [{"en": "After trying for an hour, Bill finally started the car.", "zh": "试了一个小时后，比尔终于把车子发动了。"}], "sub_entries": []}, {"num": 11, "word": "coffee", "phonetic": "[ˈkɔːfi]", "pos": "n.", "meaning": "咖啡", "examples": [], "sub_entries": []}, {"num": 12, "word": "nearby", "phonetic": "[ˈnɪrbaɪ]", "pos": "a.", "meaning": "在附近的", "examples": [{"en": "My brother lives in a nearby village.", "zh": "我哥哥住在附近的一个村庄里。"}], "sub_entries": []}, {"num": 13, "word": "cafe", "phonetic": "[kaeˈfe/kafe]", "pos": "n.", "meaning": "咖啡厅", "examples": [], "sub_entries": []}, {"num": 14, "word": "just", "phonetic": "[dʒʌst]", "pos": "adv.", "meaning": "就在（强调用法）", "examples": [], "sub_entries": ["just before...", "就在…··之前"]}, {"num": 15, "word": "before", "phonetic": "[brˈfor]", "pos": "conj.", "meaning": "在.....之前", "examples": [{"en": "Before I leave for work, I always kiss my wife goodbye.", "zh": "上班前；我总是会和太太吻别。"}], "sub_entries": []}, {"num": 16, "word": "part", "phonetic": "[part]", "pos": "vi.", "meaning": "分手", "examples": [], "sub_entries": ["part from+人", "与某人分手", ": After saying goodbye, he parted from his", "parents and got on the train.", "（道别后，他就与父母分手并上了火车。）"]}, {"num": 17, "word": "kiss", "phonetic": "[kis]", "pos": "n.", "meaning": "吻", "examples": [], "sub_entries": ["a good-night kiss", "晚上道别时之亲吻"]}, {"num": 18, "word": "moment", "phonetic": "[ˈmomant]", "pos": "n.", "meaning": "片刻，时刻", "examples": [{"en": "At that moment, I had nothing to say.", "zh": "就在那一刻，我无话可说。"}], "sub_entries": ["at that moment", "就在那时"]}, {"num": 19, "word": "be on top of the world", "phonetic": "", "pos": "短语", "meaning": "在世界的顶端，喻快乐得飘飘欲仙", "examples": [{"en": "I got an \"A\" on my final exam. I am on top oftheworld.", "zh": "期末考时我得了个\"A”。我真是高兴极了。"}], "sub_entries": ["top[ tap] n.顶端", "world[w3ld]n.世界"]}, {"num": 20, "word": "love", "phonetic": "[lav]", "pos": "n.", "meaning": "爱", "examples": [{"en": "I think Carl is in love with Connie.", "zh": "我想卡尔爱上康妮了。"}], "sub_entries": ["bein love(with+人）爱上某人；（与某人）恋爱了"]}], "grammar": {"intro": "本课介绍一般过去时的形式及其用法。课文中的动词如", "items": [{"num": 1, "title": "一般过去时的形式", "body": ["主语+动词的过去式", "例：I saw him yesterday.（saw为see的过去式）（我昨天见到他。）", "He lived here ten years ago.(lived 为 live 的 过去式)（他十年前住在这里。）They were angry when they heard the news.（were为are的过去式，heard为hear的过去 式）（.他们听到这消息时很生气。）", "注意：", "a. 动词的过去式均由动词原形变化而成，许多动词字 尾加-ed即成过去式，如：", "want → wanted 要 part -→ parted 分开 visit -→ visited 拜访 help → helped 帮助 但也有不少动词变成过去式时，呈不规则变化，如：", "see →saw 看 tell→told 告诉 have -→had 有 forget → forgot 忘记 属于不规则变化的动词过去式繁多，读者要在短时 间内完全熟悉是不太可能的一件事。唯有多读英文 文章，勤查字典，持之以恒，不知不觉中就能运用 自如了。", "b. 由于be 动词的过去式亦属不规则变化，且常用得 到，故特列表如下，以利背诵：", "现在时 过去时 单 I am... I was... You are... 数 You were... He/She/It is... He/She/It was.. We are... 复 We were... 数 You are... You were... They are... They were...", "c. 一般过去时的否定句子结构如下：", "主语+didnot/didn't+动词原形 主语+|wasnot/wasn't lwerenot/weren'tl", "例：肯定句：Heleft.（他离开了。）", "否定句：He didn't leave．（他没离开。）肯定句：Wewerehappy．（我们很快乐。）否定句：Weweren't happy．（我们不快 乐。）"]}, {"num": 2, "title": "一般过去时使用的时机", "body": ["一般过去时表示过去所发生的动作或状态。这种时态 往往与表示过去的时间副词并用。", "例：He came back at ten this morning.（他于今天早上十点回来。）", "He passed away last night.（他昨晚过世了。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 38, "title_en": "Nobody Answered the Phone", "title_zh": "没人接电话", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Rita", "speaker_zh": "丽塔", "en": "Hi, Jay, where did you go last night?", "zh": "嗨，杰伊，你昨晚到哪儿去了？"}, {"speaker_en": "Jay", "speaker_zh": "杰伊", "en": "I stayed home.", "zh": "我待在家里。"}, {"speaker_en": "Rita", "speaker_zh": "丽塔", "en": "But I called you many times. Nobody answered the phone.", "zh": "但是我打了好几次电话给你。没人接电话。"}, {"speaker_en": "Jay", "speaker_zh": "杰伊", "en": "That's impossible.", "zh": "不可能。"}, {"speaker_en": "Rita", "speaker_zh": "丽塔", "en": "Oh! Mom probably forgot to pay the phone bill again. 杰伊和丽塔是兄妹。", "zh": "哦！妈可能又忘了付电话费了。"}]}, "vocab": [{"num": 1, "word": "stay", "phonetic": "[ste]", "pos": "vi.", "meaning": "待在，留在", "examples": [{"en": "I stayed at Peter's house last night.", "zh": "昨晚我留在彼得家。"}], "sub_entries": []}, {"num": 2, "word": "call", "phonetic": "[kɔːl]", "pos": "vt.", "meaning": "打电话（给某人）", "examples": [{"en": "I called my girlfriend on the phone last night.", "zh": "昨晚我打电话给我女友。"}], "sub_entries": []}, {"num": 3, "word": "many times", "phonetic": "", "pos": "短语", "meaning": "许多次", "examples": [{"en": "A baby eats many times a day.", "zh": "宝宝一天要吃好几次。"}], "sub_entries": ["several times", "几次"]}, {"num": 4, "word": "answer", "phonetic": "[ˈenss]", "pos": "vt.", "meaning": "回应，回答", "examples": [], "sub_entries": ["answer the phone", "接电话"]}, {"num": 5, "word": "phone", "phonetic": "[fon]", "pos": "n.", "meaning": "电话机（telephone['tela.fon]的", "examples": [], "sub_entries": ["缩写形）"]}, {"num": 6, "word": "impossible", "phonetic": "[imˈpasabl]", "pos": "a.", "meaning": "不可能的", "examples": [], "sub_entries": []}, {"num": 7, "word": "probably", "phonetic": "[ˈprababll]", "pos": "adv.", "meaning": "可能，或许", "examples": [{"en": "I will probably visit my grandmother tomorrow.", "zh": "我明天或许会去拜访我的祖母。"}], "sub_entries": []}, {"num": 8, "word": "forgot", "phonetic": "[foˈɡat]", "pos": "vt.", "meaning": "忘记（forget [fəˈget] 的过去式）", "examples": [{"en": "I forgot to tell you that your mother called.", "zh": "我忘了告诉你，你母亲有打过电话来。"}], "sub_entries": ["forget to + 动词原形：忘了要……"]}, {"num": 9, "word": "pay", "phonetic": "[peɪ]", "pos": "vt.", "meaning": "付（款）", "examples": [], "sub_entries": []}, {"num": 10, "word": "bill", "phonetic": "[bul]", "pos": "n.", "meaning": "帐单", "examples": [], "sub_entries": []}, {"num": 11, "word": "again", "phonetic": "[aˈɡen]", "pos": "adv.", "meaning": "再次，又", "examples": [{"en": "Fred is late for work, again.", "zh": "弗雷德上班又迟到了。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Fred", "back at three o'clock last night.", "(A) comes (B) came (C) come (D) is coming", "2.His poor old father", "away this morning.", "(A) go", "(B) goes", "(C) pass", "(D) passed", "3.We", "a good movie last Saturday.", "(A)went", "(B)liked", "(C) saw", "(D) visited", "4.Sally is", "love with Bob.", "(A) in", "(B)on", "(C)at(D) inside", "5.1", "my mother to the beach yesterday.", "(A) and", "(B) told", "(C) took", "(D) went", "6.Where", "last night?", "(A) you were", "(B) were you", "(C) did you be", "(D) did you went"], "answers": ["解答1.(B）2.(D）3.(C)4.(A）5.(C）6.(B)"]}}, {"num": 39, "title_en": "Homesickness", "title_zh": "乡愁", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["After my graduation, I went to Beijing to further my studies. I lived there for three years. At first, I was happy, but later, I was frustrated and depressed. I was homesick all the time. Although the people were friendly, 1 missed my family, my friends and the lifestyle in my hometown."], "zh": ["我毕业后便到北京深造。我在那儿住了三年。起先我很快乐，但后来我便感到泄气、沮丧。我一直都很想家·虽然那里的人们都很友善，但我还是想念在故乡的家人、朋友以及生活方式。"]}, "dialog": null, "vocab": [{"num": 1, "word": "homesickness", "phonetic": "[ˈhom.siknis]", "pos": "n.", "meaning": "乡愁，思乡病", "examples": [], "sub_entries": []}, {"num": 2, "word": "after", "phonetic": "[ˈefto]", "pos": "prep.", "meaning": "（指时间）在...之后", "examples": [{"en": "After my test, I went home to sleep.", "zh": "考完试后，我就回家睡觉。"}], "sub_entries": []}, {"num": 3, "word": "graduation", "phonetic": "[ˌɡrædʒuˈeɪʃən]", "pos": "n.", "meaning": "毕业", "examples": [{"en": "I graduated from Beijing University last year.", "zh": "我去年从北大毕业。"}], "sub_entries": ["graduate ['gred3uet ] vi. 毕业", "graduate from...", "从.……毕业"]}, {"num": 4, "word": "further", "phonetic": "[ˈfɜːrðər]", "pos": "vt.", "meaning": "增进", "examples": [], "sub_entries": []}, {"num": 5, "word": "studies", "phonetic": "[ˈstadiz]", "pos": "n.", "meaning": "学业（study的复数形）", "examples": [{"en": "Bob went to Paris to further his studies in art.", "zh": "鲍勃到巴黎去进修艺术。"}], "sub_entries": ["further one's studies", "深造，进修"]}, {"num": 6, "word": "live", "phonetic": "[liv]", "pos": "vi.", "meaning": "住；活", "examples": [{"en": "Some turtles can live for hundreds of years.", "zh": "有些乌龟可以活上好儿百年。"}], "sub_entries": []}, {"num": 7, "word": "first", "phonetic": "[fɜːrst]", "pos": "n.", "meaning": "最先，第一", "examples": [{"en": "At first I forgot his name，but later, I remembe:ed it.", "zh": "起初我忘了他的名字，但后来我又想起来了。"}], "sub_entries": ["at first", "起初（作状语用，通常暨于句首）"]}, {"num": 8, "word": "later", "phonetic": "[leto]", "pos": "adv.", "meaning": "之后，后来", "examples": [{"en": "I will call you later in the day.", "zh": "我今天晚点再打电话给你。"}], "sub_entries": []}, {"num": 9, "word": "frustrated", "phonetic": "[ˈfrastretid]", "pos": "a.", "meaning": "受挫的", "examples": [{"en": "Fred was very sadand frustrated whenno one came to his party.", "zh": "没有人来参加弗雷德的宴会使得他感到伤心又泄气。"}], "sub_entries": []}, {"num": 10, "word": "depressed", "phonetic": "[dˈprest]", "pos": "a.", "meaning": "沮丧的", "examples": [{"en": "Sarah was very depressed when her dog died.", "zh": "当萨莉的狗儿死掉时她很沮丧。"}], "sub_entries": []}, {"num": 11, "word": "homesick", "phonetic": "[ˈhom.sik]", "pos": "a.", "meaning": "思乡的，想家的", "examples": [{"en": "Children get homesick at summer camp.", "zh": "孩子们在夏合营时会想家。"}], "sub_entries": []}, {"num": 12, "word": "time", "phonetic": "[taim]", "pos": "n.", "meaning": "时间", "examples": [{"en": "Charles is a good student. He studies all the time.", "zh": "查尔斯是个好学生。他总是在念书。"}], "sub_entries": ["all the time", "始终，一直（作状语用，使用时置", "于句尾）"]}, {"num": 13, "word": "friendly", "phonetic": "[ˈfrendli]", "pos": "a.", "meaning": "友善的", "examples": [], "sub_entries": []}, {"num": 14, "word": "miss", "phonetic": "[mis]", "pos": "vt.", "meaning": "想念", "examples": [{"en": "When I went abroad, I missed my friends.", "zh": "出国时，我很想念我的朋友们。"}], "sub_entries": []}, {"num": 15, "word": "lifestyle", "phonetic": "[laifstall]", "pos": "n.", "meaning": "生活方式", "examples": [{"en": "City people and country people have very different lifestyles.", "zh": "都市人和乡下人的生活方式大不相同。"}], "sub_entries": []}, {"num": 16, "word": "hometown", "phonetic": "[ˈhomˈtaun]", "pos": "n.", "meaning": "家乡", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍 after、atfirst的用法，并介绍可作形容 词用的分词用法。", "items": [{"num": 1, "title": "After my graduation, I went to Beijing to further my studies.", "body": ["（我毕业后便到北京深造。）本句中的After是介词，之后以名词graduation 作 其宾语。但after亦可作连词，引导状语从句，亦即 after之后可接“主语+动词”。故上句亦可改写为：", "After I graduated, I went to Beijing to further my studies.", "例： After his resignation, he went abroad.", "介词", "=After he resigned, he went abroad. 连词（他辞职后便出国去了。）before（在...·之前）与after…一样，亦有上述两种 词性。", "例: Before she left, she gave me a kiss.", "连词", "=Before her departure, she gave me a kiss. 介词（她在离开前给了我一个吻。）"]}, {"num": 2, "title": "at first 与 first 的区别", "body": ["at first 与 first 均可置于句首，作副词用，修饰之后的句子，但意思不同：", "例：At first, she was very nice to John，but later, she left him.（起先，她对约翰很好，但后来她却离开他 了。）", "David is great in many ways. First, he never lies. Second(ly),he is helpful.（大卫很多方面都很棒。首先是，他从不说谎。其次是；他乐于助人。）"]}, {"num": 3, "title": "..I was frustrated and depressed.", "body": ["（...。我便感到泄气、沮丧。）frustrated及depressed均为过去分词，在本文中作 的”。英语中有一些现在分词或过去分词均可作形容词用。初学英语的人较不易判断使用这两种分词的时机。其 实我们可掌握下列原则：", "现在分词多译为“令人·…的”，过去分词则译为“感到·….…·的”。", "例：The question is confused.（×）（这个问题感到迷惑。一一不合逻辑）", "The question is confusing. (○)（这个问题令人迷惑。）The result is depressed. (×)（这个结果感到沮丧。－不合逻辑）The result is depressing. (○)（这个结果令人沮丧。）The baby is tiring. (○)（这个婴儿真累人。：", "抱着他的时候，他扭来 扭去，晚上又爱哭，令父母睡不着）The baby is tired.(○)（这个婴儿已累了。一一他哭个老半天，终于筋 疲力尽而感到累了)由以上各例得知，使用分词作形容词时，只要合乎逻 辑，掌握翻译的原则，就不易出错。"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 40, "title_en": "Everybody Spoke English", "title_zh": "大家都说英语", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Eve", "speaker_zh": "夏娃", "en": "Welcome back! What was America like?", "zh": "欢迎归来！美国是什么样子呀？"}, {"speaker_en": "Adam", "speaker_zh": "亚当", "en": "OK, I guess.", "zh": "我想还可以。"}, {"speaker_en": "Eve", "speaker_zh": "夏娃", "en": "What do you mean by \"I guess?\"", "zh": "你说“我想”是什么意思？"}, {"speaker_en": "Adam", "speaker_zh": "亚当", "en": "Well, frankly speaking, it was terrible.", "zh": "，坦白说，美国糟透了。"}, {"speaker_en": "Eve", "speaker_zh": "夏娃", "en": "Why?", "zh": "为什么？"}, {"speaker_en": "Adam", "speaker_zh": "亚当", "en": "Everybody only spoke English.", "zh": "大家只说英语嘛。"}]}, "vocab": [{"num": 1, "word": "welcome", "phonetic": "[ˈwelkam]", "pos": "a.", "meaning": "受欢迎的", "examples": [], "sub_entries": ["\"Welcome back!\" 乃由 \"(You're） welcome back!\"", "简化而成。"]}, {"num": 2, "word": "guess", "phonetic": "[ɡes]", "pos": "vt.", "meaning": "猜想", "examples": [], "sub_entries": ["本文中之“OK，Iguess.”即等于\"Iguess that", "America was OK.\"。"]}, {"num": 3, "word": "mean", "phonetic": "[min]", "pos": "vt.", "meaning": "意即，意思是", "examples": [{"en": "Do you know what this word means?", "zh": "你知道这个字是什么意思吗？"}], "sub_entries": []}, {"num": 4, "word": "frankly", "phonetic": "[ˈfræŋkli]", "pos": "adv.", "meaning": "坦白i地", "examples": [{"en": "A:I failed my test. B: Frankly speaking, I'm not surprised. You never study.", "zh": "甲：我考试没通过。）（乙：坦白说，我并不惊讶。你从不念书。"}], "sub_entries": ["frankly speaking", "坦白说，老实说（使用时多置于", "句首，以逗号与主句相隔）"]}, {"num": 5, "word": "terrible", "phonetic": "[ˈterabl]", "pos": "a.", "meaning": "糟糕的", "examples": [{"en": "The food at that restaurant is terrible.", "zh": "那家餐厅的食物真是糟透了。"}], "sub_entries": []}, {"num": 6, "word": "spoke", "phonetic": "[spok]", "pos": "vt.", "meaning": "说，讲（语言）(speak 的过去式）", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. At first, I was sad,", "later, I was happy.", "(A) and (B) but (C) also (D) so", "2. That movie was good in many ways. First, it was", "exciting.", "，it was funny.", "(A）Then (B)But later (C) Second (D）After", "3.After I did my homework, 1", "TV.", "(A) saw (B) look (C) looked (D) watched", "4.This job is very", "(A) tired (B) helping (C) tiring (D) confused", "5.Before I saw the movie, I", "the book.", "(A)read (B）readed (C)watched (D) looked", "6. Able: Paul is a great dancer.", "Sue :", "，I'm not surprised. He dances every", "day.", "(A) Speaking frankly (B) Frankly speaking", "(C) Spoke frankly", "(D) Frankly spoke"], "answers": ["解答1.(B）2.(C）3.(D）4.(C）5.(A）6.(B)"]}}, {"num": 41, "title_en": "Going Camping", "title_zh": "露营", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Last weekend, my classmates and I went camping. We found a grassy spot beside a river. We put up our tents and made a campfire. Then, we fished at the river. We had only one fishing rod, so we took turns. After a while, we caught a big trout. Finally, we sat around the fire, roasted the fish and sang songs. Camping is really fun!"], "zh": ["上个周末我和同学去露营。我们在河边找到一块草地。我们架起帐篷、生了营火，然后就在河边钓鱼。我们只有一只钓竿，因此我们就轮流钓。没多久，我们钓到一条大鱼。最后，我们围坐在营火旁，边烤鱼边唱歌·露营真有趣！"]}, "dialog": null, "vocab": [{"num": 1, "word": "classmate", "phonetic": "[ˈklæsˌmet]", "pos": "n.", "meaning": "同班同学", "examples": [], "sub_entries": ["schoolmate['skul.met]n.学校同学"]}, {"num": 2, "word": "camp", "phonetic": "[kamp]", "pos": "", "meaning": "vi．露营（使用时，多采现在分词形，", "examples": [], "sub_entries": ["置于go之后）", "go camping", "露营去", ": Every summer my family and I go camping", "in the mountains.", "（每年夏天我和我的家人都会到山中去露营。）"]}, {"num": 3, "word": "found", "phonetic": "[faund]", "pos": "vt.", "meaning": "找到，发现（find的过去式）", "examples": [], "sub_entries": [": I lost my umbrella yesterday, but found it", "today.", "（昨天我的雨伞遗失了，但今天我又找到了。）"]}, {"num": 4, "word": "grassy", "phonetic": "[ˈɡrasi]", "pos": "a.", "meaning": "多草的", "examples": [], "sub_entries": []}, {"num": 5, "word": "spot", "phonetic": "[spat]", "pos": "n.", "meaning": "地点", "examples": [], "sub_entries": []}, {"num": 6, "word": "beside", "phonetic": "[brˈsaid]", "pos": "prep.", "meaning": "在......之旁", "examples": [{"en": "I sit beside Carol in math class.", "zh": "上数学课时我坐在卡罗尔旁边。"}], "sub_entries": []}, {"num": 7, "word": "river", "phonetic": "[ˈriv]", "pos": "n.", "meaning": "河流", "examples": [], "sub_entries": []}, {"num": 8, "word": "put", "phonetic": "[put]", "pos": "vt.", "meaning": "放置", "examples": [], "sub_entries": []}, {"num": 9, "word": "tent", "phonetic": "[tent]", "pos": "n.", "meaning": "帐篷", "examples": [{"en": "We should put up the tent. It is getting dark.", "zh": "我们应该把帐篷搭起来。天快黑了。"}], "sub_entries": ["put up a/the tent", "架设帐篷"]}, {"num": 10, "word": "campfire", "phonetic": "[ˈkamp.fair]", "pos": "n.", "meaning": "营火", "examples": [{"en": "Do you know how to make a fire?", "zh": "你知道如何生火吗？"}], "sub_entries": ["make a campfire", "生营火", "make a fire", "生火"]}, {"num": 11, "word": "fish", "phonetic": "[ff]", "pos": "vi.", "meaning": "钓鱼", "examples": [], "sub_entries": []}, {"num": 12, "word": "fishing rod", "phonetic": "[ˈfujiɡ rad]", "pos": "n.", "meaning": "钓竿", "examples": [], "sub_entries": []}, {"num": 13, "word": "took", "phonetic": "[tuk]", "pos": "vt.", "meaning": "采取（take[tek]的过去式）", "examples": [], "sub_entries": []}, {"num": 14, "word": "turn", "phonetic": "[tɜːrn]", "pos": "n.", "meaning": "轮流", "examples": [{"en": "Let's take turns playing with the toy.", "zh": "咱们轮流玩玩具吧！"}], "sub_entries": ["take turns", "轮流"]}, {"num": 15, "word": "while", "phonetic": "[hwanl/wail]", "pos": "", "meaning": "n．一会儿（通常与介词for或", "examples": [{"en": "After a while, I found my keys. I worked at that store for a while.", "zh": "没多久我就找到了钥匙。）（我在那家商店工作过一阵子。"}], "sub_entries": ["after并用）", "after a while", "一会儿之后，没多久", "for a while", "有-一会儿"]}, {"num": 16, "word": "caught", "phonetic": "[kot]", "pos": "vt.", "meaning": "捕捉（catch[kaetf]的过去式）", "examples": [], "sub_entries": []}, {"num": 17, "word": "trout", "phonetic": "[traut]", "pos": "n.", "meaning": "鳟鱼（单复数同形）", "examples": [], "sub_entries": ["a trout", "一条鳟鱼", "two trout", "两条鳟鱼"]}, {"num": 18, "word": "sat", "phonetic": "[saet]", "pos": "vi.", "meaning": "坐（sit[sit]的过去式）", "examples": [{"en": "I sat in the library and read all day.", "zh": "我坐在图书馆里看了一整天的书。"}], "sub_entries": []}, {"num": 19, "word": "around", "phonetic": "[araund]", "pos": "prep.", "meaning": "围绕，在.…....周围", "examples": [], "sub_entries": []}, {"num": 20, "word": "roast", "phonetic": "[rost]", "pos": "vt.", "meaning": "烤", "examples": [], "sub_entries": []}, {"num": 21, "word": "fish", "phonetic": "[fif]", "pos": "n.", "meaning": "鱼（单复数同形）", "examples": [], "sub_entries": ["a fish", "一条鱼", "two fish", "两条鱼"]}, {"num": 22, "word": "sang", "phonetic": "[saɡ]", "pos": "vt.", "meaning": "唱（sing[sin]的过去式）", "examples": [], "sub_entries": []}, {"num": 23, "word": "song", "phonetic": "[son]", "pos": "n.", "meaning": "歌曲", "examples": [], "sub_entries": []}, {"num": 24, "word": "fun", "phonetic": "[fan]", "pos": "n.", "meaning": "乐趣", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课主要介绍and连接含有两个或两个以上的人 称代词作主语的位置，及动名词作主语的用法。", "items": [{"num": 1, "title": "Last weekend, my classmates and I went camping.", "body": ["（上个周末我和同学去露营。）注意下列有两个主语并存的位置：", "a. 主语若有代词\"T\"及其他人时，应以and连接，并 将其他人置于\"T\"之前，以示尊重。： I and my father went fishing last weekend.（x)", "→ My father and I went fishing last weekend.（0)（上个周末我和我爸爸钓鱼去了。）词与其他人共同作主语时，这些代词应置于第一个 位置。：His father and he went swimming last Friday.（×)", "→He and his father went swimming last Friday.（O)（他和他爸爸上星期五游泳去了。）Mary and we sang songs at the party. (×)", "→ We and Mary sang songs at the party. (○)（我们和玛丽在宴会上高歌。）", "c. 代词并存时，注意下列次序：", ": He, you and I are good friends. (×)", "→ You, he and I are good friends. (○)（你、我和他都是好朋友。）You, we and they are good friends. (×)", "→We, you and they are good friends. (○)（我们、你们和他们都是好朋友。）"]}, {"num": 2, "title": "...my classmates and I went camping.", "body": ["（...。我和同学去露营。）本句采用了\"go+现在分词”的短语，表示“从事某 种短暂性的活动”之意。常用的此类短语如下：", "go camping 去露营 go hunting去打猎 go dancing 去跳舞 go golfing去打高尔夫球 go shopping 去购物 go'swimming 去游泳 go mountain climbing 去爬山: My best friend and I often go shopping together.（我经常和我的好友一起去购物。）"]}, {"num": 3, "title": "take turns 的用法", "body": ["take turns 意为“轮流”，常见搭配为：take turns (at) + 动名词（轮流做某事）。", "例：The three boys took turns tolook after their", "sick mother.（×）", "→The three boys took turns(at)looking_after their sick mother.(○)（这三个孩子轮流照顾他们生病的母亲。）"]}, {"num": 4, "title": "Camping is really fun!", "body": ["（露营真有趣！)此处作主语的camping是动名词，由动词原形camp 变化而成。作主语的词类通常是名词或代词。m: The boy lives near my house. 名词（这男孩就住在我家附近。）He is a student. 代词（他是学生。）动词不能直接作主语，应将动词变成动名词方可作主 语。中文：跟他唱歌很愉快。英文：Sing songs with him is fun.（×）理由：Sing是动词原形，不可作主语。改正： Singing songs with him is fun.（ O)请再看下例：", "中文：在河边露营很愉快。英文：Camp by the river is fun.（×）理由：Camp是动词原形，不可作主语。改正:Camping by the river is fun.（O)"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 42, "title_en": "Are You Having Fun?", "title_zh": "你玩得愉快吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Sally", "speaker_zh": "莎莉", "en": "How often do you go camping?", "zh": "你多久去露营一次？"}, {"speaker_en": "Bert", "speaker_zh": "伯特", "en": "This is my first time.", "zh": "这是我第一次去露营。"}, {"speaker_en": "Sally", "speaker_zh": "莎莉", "en": "Really? Are you having fun?", "zh": "真的吗？你玩得开心吗？"}, {"speaker_en": "Bert", "speaker_zh": "伯特", "en": "Yes. I'm having a wonderful time.", "zh": "是的。我玩得开心极了。"}]}, "vocab": [{"num": 1, "word": "How often do you + 动词原形……？", "phonetic": "", "pos": "句型", "meaning": "你多久做...一次？", "examples": [{"en": "How often do you visit your grandparents?", "zh": "你多久看祖父母一次？"}], "sub_entries": []}, {"num": 2, "word": "have fun", "phonetic": "", "pos": "短语", "meaning": "玩得开心", "examples": [{"en": "We had fun to sing songs at the party. (×) → We had fun singing songs at the party. (○)", "zh": "我们在晚会上唱歌玩得很痛快。"}, {"en": "= We had a good time singing songs at the party.", "zh": "（同上）"}], "sub_entries": ["= have a good time", "have fun + (in) + 动名词"]}, {"num": 3, "word": "I'm having a wonderful time.", "phonetic": "", "pos": "日常口语", "meaning": "我玩得开心极了。", "examples": [], "sub_entries": ["= I'm having a great time.", "= I'm having a lot of fun."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "请选出下列各题中最正确的一项：", "questions": ["1. _____ went swimming.", "(A) My and my brother", "(B) My brother and me", "(C) My brother and I", "(D) I and my brother", "2. We took turns _____ the guitar.", "(A) to play", "(B) playing", "(C) play", "(D) to playing", "3. _____, _____, and _____ are classmates.", "(A) You, she, I", "(B) I, you, she", "(C) She, I, you", "(D) She, you, I", "4. _____ bicycles in the mountains is fun.", "(A) Ride", "(B) Rides", "(C) Rode", "(D) Riding", "5. We had a good time _____ in the river.", "(A) swam", "(B) to swim", "(C) swimming", "(D) swim", "6. _____ does your brother play basketball?", "(A) How far", "(B) How often", "(C) How good", "(D) How nice"], "answers": ["1.(C) 2.(B) 3.(A) 4.(D) 5.(C) 6.(B)"]}}, {"num": 43, "title_en": "Killing Two Birds with One Stone", "title_zh": "两全其美", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Dan must take a day off tomorrow. He has to take care of his sick mother. He ought to talk to his boss, but he's afraid. His boss might get angry with him. What should Dan do? He can take the work home. This way, he can kill two birds with one stone."], "zh": ["丹明天必须请一天假。他得照顾他生病的母亲。他应当向他的老板说的，但他怕。他的老板也许会生他的气。丹该怎么办呢？他可以把工作带回家去。这样他就能两全其美。"]}, "dialog": null, "vocab": [{"num": 1, "word": "must", "phonetic": "[mast]", "pos": "aux.", "meaning": "必须", "examples": [{"en": "You must have a driver's license to drive a car.", "zh": "你必须要有驾驶执照才能开车。"}], "sub_entries": []}, {"num": 2, "word": "take ... off", "phonetic": "", "pos": "短语", "meaning": "请假", "examples": [{"en": "Last week I was sick, so I took two days off from work.", "zh": "上星期我病了，所以我请了两天假。"}], "sub_entries": ["take a day off 请一天假", "take two days off 请两天假"]}, {"num": 3, "word": "tomorrow", "phonetic": "[taˈmaro]", "pos": "adv.", "meaning": "明天", "examples": [], "sub_entries": ["today[ ta'de ]adv.今天", "yesterday[jesta.de]adv.昨天", "thedayafter tomorrow", "后天", "the day before yesterday", "前天"]}, {"num": 4, "word": "have", "phonetic": "", "pos": "", "meaning": "to+动词原形", "examples": [{"en": "I have to work all weekend.", "zh": "整个周末我都必须工作。"}], "sub_entries": ["必须…·….", "=must+动词原形"]}, {"num": 5, "word": "take care of...", "phonetic": "", "pos": "短语", "meaning": "照顾...", "examples": [{"en": "Can you take care of my dog for a few days?", "zh": "你可以帮我照顾我的狗几天吗？"}], "sub_entries": ["照顾···….", "=look after...", "care[ker]n.关怀，照料"]}, {"num": 6, "word": "sick", "phonetic": "[sik]", "pos": "a.", "meaning": "生病的", "examples": [], "sub_entries": []}, {"num": 7, "word": "ought", "phonetic": "[t]", "pos": "aux.", "meaning": "应该（使用时，之后应接 to，再接", "examples": [{"en": "You ought to be more polite.", "zh": "你应该要更有礼貌些。"}], "sub_entries": ["动词原形）", "ought to+动词原形", "应该…", "=should+动词原形"]}, {"num": 8, "word": "talk", "phonetic": "[tok]", "pos": "vi.", "meaning": "谈话", "examples": [{"en": "You have to talk to your parents about your marriage plans.", "zh": "你应该将你结婚的计划告诉你的父母。"}], "sub_entries": ["talk to+人", "对某人说话"]}, {"num": 9, "word": "boss", "phonetic": "[bos]", "pos": "n.", "meaning": "老板，上司", "examples": [], "sub_entries": []}, {"num": 10, "word": "afraid", "phonetic": "[aˈfred]", "pos": "a.", "meaning": "害怕的", "examples": [{"en": "Don't be afraid to speak English.", "zh": "别害怕开口说英文。"}], "sub_entries": ["beafraid to+动词原形", "害怕···."]}, {"num": 11, "word": "might", "phonetic": "[mait]", "pos": "aux.", "meaning": "也许，大概", "examples": [{"en": "Bill might go to the party.", "zh": "比尔大概会去参加宴会。"}], "sub_entries": []}, {"num": 12, "word": "get", "phonetic": "", "pos": "", "meaning": "angry with+人", "examples": [{"en": "He got angry with me when I broke the window, and he is still angry now.", "zh": "我把窗户打破时，他生我的气，而且到现在他还在气呢。"}], "sub_entries": ["生某人的气", "angry['angrr]a.生气的"]}, {"num": 13, "word": "should", "phonetic": "[ʃʊd]", "pos": "aux.", "meaning": "应该", "examples": [{"en": "You should brush your teeth three times a day.", "zh": "你一天应该刷三次牙。"}], "sub_entries": []}, {"num": 14, "word": "work", "phonetic": "[wɜːrk]", "pos": "n.", "meaning": "工作（不可数）", "examples": [{"en": "I don't have much work to do this afternoon.", "zh": "今天下午我没有许多工作要做。"}], "sub_entries": []}, {"num": 15, "word": "this way", "phonetic": "", "pos": "短语", "meaning": "以这种方式，这样的话", "examples": [{"en": "Let's work together. This way, we can finish the project sooner.", "zh": "我们一起工作吧·这样的话，我们就可以早一点将工作做完。"}], "sub_entries": ["way[we] n.方式"]}, {"num": 16, "word": "can", "phonetic": "[ken/kan]", "pos": "aux.", "meaning": "能", "examples": [{"en": "Ted can swim very fast.", "zh": "特德游泳可以游得很快。"}], "sub_entries": []}, {"num": 17, "word": "kill two birds with one stone", "phonetic": "", "pos": "短语", "meaning": "一石两鸟；两全其美；一举两得", "examples": [], "sub_entries": ["kill[kil]vt.杀死", "bird [bzd] n.鸟", "stone[ston ] n.石头", ":Charlie can study and work at the same", "time. This way, he kills two birds with one", "stone.", "（查利可以一边读书一边工作·这样他就可以两", "全其美了。）"]}], "grammar": {"intro": "", "items": [{"num": 1, "title": "常用助动词（情态动词）的共同特征", "body": ["本课旨在协助读者熟悉常用的一些助动词（亦指情态动词）及其用法。这些助动词有一个共同特征：它们之后皆接动词原形。", "a. Dan must take a day off tomorrow.（丹明天必须请假一天。）", "He has to take care of his sick mother.（他得照顾他生病的母亲。）以上两句中的 must 及has to（have to的第三 人称单数用法）均表示“必须”，但有其同异处。", "1）表示道德或义务（如爱国、孝顺父母）的“必 须”时，只能使用must。haveto则表示有勉 强意味（不得不去做）的“必须”，此时亦可使 用must。", "例：You have to love your country.(×)", "→You must love your country. (○)（你必须爱国家。）", "Youhave to finish the work before you can go home.", "=You must finish the work before you can go home.（你得做完工作才能回家。）", "2）must 通常只能用来表示现在或未来的状况，不 能用于过去时中。而haveto除可表示现在或 未来的状况外，亦可改为过去式hadto，使用 于过去时中。W: He must stay here now.", "=He has to stay here now.（他现在必须留下来。）", "He must come here tomorrow.", "=He has to come here tomorrow.（他明天必须来。）He must stay here yesterday. (×)", "→He had to stay here yesterday. (○)（他昨天必须留下来。）", "b. He ought to talk to his boss, but he's afraid.（他应当向他的老板说的，但他怕。）", "What should Dan do?（丹该怎么办呢？）在“单词短语注解”中，我们已说明oughtto与 should均表“应该”，用法相同·故上两句的 ought to与should可互换，而改为：", "He should talk tohis boss, but he's afraid. What ought Dan to do?（可别写成“Whatought to do and to？”之错误句 子结构）"]}, {"num": 2, "title": "His boss might get angry with him.", "body": ["（他的老板也许会生他的气。）此处助动词might是may[me]的过去式，但却 非表示过去的状态，而是表示较低的可能性，可译成“也许”、“大概”、“说不定”。而may则表示 较高可能性，可译成“很可能”。", "例：You may be right, so I will take your advice.（你很可能是对的，因此我会接受你的建议。）", "You might be right, but I think my way is better.（你或许是对的，但我想我的方法比较好。）"]}, {"num": 3, "title": "He can take the work home.", "body": ["（他可以把工作带回家去。）本句使用了\"take+人或物+to+地方\"（将某物带/运送到某地）的短语。", "例：Please take me to the station.（请带我到车站去。）", "故\"Hecan take theworkhome.\"理应写成：", "He can take the work to home.（x）由于home是副词，相当于表示场所的副词there（那里）、here（这里）等，置于句尾修饰动词时，这些副词之前不能置介词to。", "例: Let's go to home now.(×)", "→ Let's go home now. (○)（咱们回家去吧！）He went to there with Mary.(×)", "→He went there with Mary.(○)（他跟玛丽到那儿去了。）但home之前若置所有格代词（如my、your、his 等），则home是名词，在上列句子结构中，之前应 置介词to，以作其宾语。", "例:Let's go my home.(×)", "→ Let's go to my home (○)（咱们到我家去。）home 亦可与介词 at 并用，形成下列固定用法：", "beathome 在家中", "例：He is at home most of the time.（他大部分时间都待在家中。）"]}, {"num": 4, "title": "This way, he can kill two birds with one stone.", "body": ["（这样的话，他就能两全其美。）本句中的Thisway原为In thisway（以这种方式，这样的话），是作副词用的短语，但way之前有this 或that时，介词in常予省略。", "例：You must be modest. That way, you will be respected.（你必须谦虚待人。那样的话，你就会受人尊 敬。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 44, "title_en": "She Had a Bad Cold", "title_zh": "她患了重感冒", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Where were you yesterday?", "zh": "你昨天在哪里？"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "I was at home. In fact, I was taking care of Sally.", "zh": "我在家里·事实上，我在照顾萨莉。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "What's wrong with her?", "zh": "她怎么了？"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "She had a bad cold.", "zh": "她患了重感冒。"}, {"speaker_en": "Mary", "speaker_zh": "玛丽", "en": "Is she getting better?", "zh": "她好多了吗？"}, {"speaker_en": "Jack", "speaker_zh": "杰克", "en": "Yes. Thanks.", "zh": "好多了。谢谢。"}]}, "vocab": [{"num": 1, "word": "in fact", "phonetic": "", "pos": "短语", "meaning": "事实上", "examples": [{"en": "Mike likes Jessica. In fact, I think he loves her.", "zh": "迈克喜欢杰西卡。事实上，我认为他爱上她"}], "sub_entries": ["fact[fekt]n.事实", "本短语通常置于句首，之后置逗号，再接主句。"]}, {"num": 2, "word": "have a bad cold", "phonetic": "", "pos": "短语", "meaning": "患重感冒", "examples": [{"en": "You have a bad cold. You should take some medicine.", "zh": "你患了重感冒，你应该吃些药。"}], "sub_entries": ["cold[kold]n.感冒"]}, {"num": 3, "word": "be getting better", "phonetic": "", "pos": "短语", "meaning": "（病）渐渐好起来", "examples": [{"en": "A:Do you still feel sick? B: Yes, but I'm getting better.", "zh": "甲：你还是觉得不舒服吗？）（乙：是的，但我好多了。"}], "sub_entries": ["此处better是形容词well（身体健康的）的比较级"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Take your dog.", "(A) to home", "(B)home", "(C) at home", "(D)in home", "2.Bill is a little fat. He", "to go on a diet.", "(A) should (B) must (C) have (D) ought", "3.Carlos has a big exam tomorrow. He", "to", "study tonight.", "(A)have (B) should (C) has (D） must", "4.1", "work last Sunday.", "(A) have to (B) must (C) had to (D) has to", "5.I don't know, but it", "rain tomorrow.", "(A) might (B) must (C) has to (D) ought to", "6. Peter can sing.", ",he is a good singer.", "(A) However", "(B）At first", "(C) This way", "(D) In fact"], "answers": ["解答>1.(B）2.(D）3.(C）4.(C）5.(A）6.(D)"]}}, {"num": 45, "title_en": "What a Nightmare!", "title_zh": "真是恶梦一场啊！", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Jeff had a terrible day. He missed the train to work. Moreover, he had to wait a long time for the next train. As a matter of fact, he waited for two hours. To make matters worse, he left his briefcase on the train. As a result, he had to go to the police station. Poor Jeff never got to work that day. What a nightmare!"], "zh": ["杰夫过了很糟的一天。他上班没赶上火车。而且，他得久候下一班火车的到来。事实上，他等了两个小时。更糟的是，他把手提箱留在火车上了。结果，他得到警察局走一趟。可怜的杰夫那一天根本上不了班。真是恶梦一场啊！"]}, "dialog": null, "vocab": [{"num": 1, "word": "terrible", "phonetic": "[ˈterabl]", "pos": "a.", "meaning": "糟糕的，可怕的", "examples": [{"en": "That was a terrible movie.", "zh": "那真是一部遭透了的电影。"}], "sub_entries": []}, {"num": 2, "word": "miss", "phonetic": "[mis]", "pos": "vt.", "meaning": "错过", "examples": [{"en": "Why did you miss the meeting today?", "zh": "你为什么错过今天的会议呢？"}], "sub_entries": []}, {"num": 3, "word": "moreover", "phonetic": "[morov]", "pos": "adv.", "meaning": "此外，尤有甚者", "examples": [{"en": "Mike is very kind. Moreover, he is honest.", "zh": "迈克为人很好。而且，他还很诚实。"}], "sub_entries": []}, {"num": 4, "word": "wait", "phonetic": "[wet]", "pos": "vi.", "meaning": "等候", "examples": [{"en": "I am still waiting for my girlfriend to write to me.", "zh": "我还在等我女友写信给我。"}], "sub_entries": ["waitfor+人或事物", "等候某人或某事物"]}, {"num": 5, "word": "as a matter of fact", "phonetic": "", "pos": "短语", "meaning": "事实上（使用时置于句首，", "examples": [{"en": "That car is not cheap. As a matter of fact, it's very expensive.", "zh": "那辆车不便宜，事实上，它很昂贵。"}], "sub_entries": ["=in fact", "之后置逗号）"]}, {"num": 6, "word": "to ...", "phonetic": "", "pos": "worse.", "meaning": "更糟的是，··", "examples": [{"en": "It was raining. To make matters worse, I forgot to bring my umbrella.", "zh": "下雨了。更糟的是，我忘了带伞。"}], "sub_entries": ["worse[w3s]a.更坏的(bad 的比较级）"]}, {"num": 7, "word": "left", "phonetic": "[left]", "pos": "vt.", "meaning": "将...…留在.…...（leave的过去式）", "examples": [{"en": "I left my umbrella on the bus.", "zh": "我把雨伞留在公共汽车上了。"}], "sub_entries": []}, {"num": 8, "word": "briefcase", "phonetic": "[ˈbrif.kes]", "pos": "n.", "meaning": "手提箱，公事皮包", "examples": [], "sub_entries": []}, {"num": 9, "word": "police station", "phonetic": "[palis stejan]", "pos": "n.", "meaning": "警察局", "examples": [], "sub_entries": []}, {"num": 10, "word": "nightmare", "phonetic": "[ˈnait.mer]", "pos": "n.", "meaning": "恶梦（本文中指“可怕的", "examples": [{"en": "City traffic is a real nightmare.", "zh": "市区的交通真像是一场恶梦。"}], "sub_entries": ["经验”）"]}], "grammar": {"intro": "本课介绍不定式短语作副词的用法及感叹句的用法。", "items": [{"num": 1, "title": "He missed the train to work.", "body": ["（他上班没赶上火车。）本句中的towork是介词短语，作形容词用，修饰之 前的名词thetrain。to是介词，表示“通往”之 意。work则为名词，作to之宾语，原指“工作”，此处笼统指“上班”之意。其他有关work的常用短 语尚有：", "a. gotowork 上班: He goes to work at 8:00 a.m. every morning.（他每天早上八点上班。）", "b. after work 下班后 个:What do you usually do after work?（下班后你通常做什么？）"]}, {"num": 2, "title": "To make matters worse, he left his briefcase on the train.", "body": ["（更糟的是，他把手提箱留在火车上了。）to make matters worse为不定式短语。这种短语由 to之后接动词原形所成，此处的to是虚词，而非介 词。这种不定式短语通常置于句首，之后置逗号，有 副词的功能，修饰全句·类似的短语尚有：", "to tell(you) the truth 老实（对你）说", "to be frank (with you)", "坦白（跟你）说", "例：A:Did you like themovie?", "B:To tell the truth, I fell asleep in the middle of it.（甲：你喜欢这部电影吗？）（乙：老实说，我看到一半时就睡着了。）A:Do you like Picasso's paintings? B: To be frank, I don't know who Picasso is.（甲：你喜欢毕加索的画吗？）（乙：坦白说，我不知道谁是毕加索。）"]}, {"num": 3, "title": "What a nightmare!", "body": ["=What a nightmare it was!（真是恶梦一场啊！)原句句尾省略了主语it及动词was；it是代词，指的 是杰夫一天里种种倒霉遭遇。本句属what引导的感叹句。英文中的感叹句有两 种，\"-由how引导，\"-由what引导，均置于句首。这种感叹句多译成“多么地”、“眞地”。感叹句均 而成，形成的方式如下：", "a. 以how引导的感叹句 由于how是副词，可修饰形容词、副词或动词，因此：", "1）陈述句有形容词，之后又无名词时，该形容词 移至how之后即告完成。陈述句：He is nice.", "a.（他人很好。）", "感叹句：Hownicehe is!（他多好啊！）", "2）陈述句有副词时，该副词移至how之后即告 完成。陈述句：He worked hard. adv.（他工作努力。）", "感叹句：How hard he worked!（他工作多努力啊！）", "3）how亦可修饰陈述句中的动词，此时将how 置于原陈述句句首即告完成。陈述句：I love that picture.（我喜欢那张画。）", "感叹句：How I love that picture!（我多喜欢那张画啊！）", "b. 以what引导的感叹句 此时what是形容词，之后须接名词或含有形容词 修饰的名词，因此：", "1)陈述句有名词时，该名词移至what之后即告 完成。陈述句： It was a nightmare.", "n.（那是一个恶梦。）", "感叹句：What a nightmare it was!（真是恶梦-场啊！）陈述句：They are nice boys.", "a.", "n.（他们是好孩子。）", "感叹句：Howniceboys theyare！（×）感叹句：What nice boys they are!（O）（他们真是好孩子！）陈述句:He did a stupid thing.（他做了件蠢事。）感叹句：What a stupid thing he did!（他做了多蠢的一件事！）", "2）what引导的感叹句中，what之后接名词，再 接“主语+be动词”时，主语及be动词可省 略。", "例：What a nightmare it was!", "主语 be动词", "→ What a nightmare!（真是恶梦一场啊！）What nice boys they are!主语be 动词-→ What nice boys!（多好的孩子们啊！）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 46, "title_en": "A Terrible Headache", "title_zh": "头痛得很厉害", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Frank", "speaker_zh": "弗兰克", "en": "Do you have any aspirins?", "zh": "你有阿司匹林吗？"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "In fact, I don't. Why?", "zh": "事实上，我没有。干嘛问这个？"}, {"speaker_en": "Frank", "speaker_zh": "弗兰克", "en": "I have a terrible headache.", "zh": "我头痛得很厉害。"}, {"speaker_en": "Jane", "speaker_zh": "简", "en": "Well, you should go see a doctor immediately.", "zh": "那么，你应当立刻去看医生。"}]}, "vocab": [{"num": 1, "word": "headache", "phonetic": "[ˈhe.dek]", "pos": "n.", "meaning": "头痛", "examples": [{"en": "Don't shout; I have a terrible headache.", "zh": "别叫了，我头痛得很厉害。"}], "sub_entries": ["have a headache", "头痛"]}, {"num": 2, "word": "aspirin", "phonetic": "[ˈesparin]", "pos": "n.", "meaning": "阿司匹林（一种头痛药）", "examples": [], "sub_entries": []}, {"num": 3, "word": "go see a doctor", "phonetic": "", "pos": "短语", "meaning": "去看医生", "examples": [], "sub_entries": ["=go and see a doctor", "英文中come 或 go以原形出现，其后接and再接另", "一动词原形时，and可予省略，而形成come 或 go"]}, {"num": 210, "word": "", "phonetic": "", "pos": "", "meaning": "直接加动词原形的情况。", "examples": [{"en": "Come and see me when you have time. =Come see me when you have time.", "zh": "你有空时要来看我。"}], "sub_entries": []}, {"num": 4, "word": "doctor", "phonetic": "[ˈdakto]", "pos": "n.", "meaning": "医生", "examples": [], "sub_entries": []}, {"num": 5, "word": "immediately", "phonetic": "[ɪˈmiːdiətli]", "pos": "adv.", "meaning": "立刻，马上", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1.", "beautiful your house is!", "(A)What", "(B）How", "(C) So", "(D) What's", "2.", "a good time we had!", "(A)What", "(B）How", "(C) So", "(D) What's", "3. I got up late for work today.", "，my car", "wouldn't start.", "(A) As a matter of fact", "(B)To make matters worse", "(C) As a result", "(D）To tell the truth", "4.I had to work yesterday.", "，I worked all", "day.", "(A） As a result", "(B)However", "(C) As a matter of fact", "(D） Therefore", "5.Carl took a taxi", "(A) for work", "(B) to working", "(C) and work", "(D) to work", "6. Let's", "(A) go seeing a movie", "(B) go to and see a movie", "(C) go see a movie", "(D) see and go to a movie"], "answers": ["解答>1.(B）2.(A）3.(B）4.(C)5.(D）6.(C)"]}}, {"num": 47, "title_en": "Be Polite", "title_zh": "要有礼貌", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Everyone should be polite. Polite people show good manners. Moreover, they are popular. On the other hand, rude people are looked down upon. Rudeness shows poor education. Therefore, why not be polite? A simple \"Please,\" \"Thank you,\" or \"You're welcome,\" can make a big difference."], "zh": ["每个人都应有礼貌。有礼貌的人展现良好的风度。而且，他们受人欢迎。另一方面，无礼的人则遭人轻视。无礼表示教育，，、“，一业回，。气”这几个字虽很简单，却会使情况大不相同。"]}, "dialog": null, "vocab": [{"num": 1, "word": "polite", "phonetic": "[palait]", "pos": "a.", "meaning": "有礼貌的", "examples": [{"en": "A gentleman is always polite.", "zh": "绅士总是很有礼貌。"}], "sub_entries": []}, {"num": 2, "word": "show", "phonetic": "[fo]", "pos": "vt.", "meaning": "展现", "examples": [{"en": "Her poor test score showed that she didn't study.", "zh": "她差劲的考试分数显示出她根本没念书。"}], "sub_entries": []}, {"num": 3, "word": "manners", "phonetic": "[ˈmanaz]", "pos": "n.", "meaning": "风度，礼貌", "examples": [{"en": "She spoke to us in an impolite manner. It is bad manners to point at people.", "zh": "她跟我们说话时很不礼貌。）（对人指指点点是很不礼貌的。"}], "sub_entries": []}, {"num": 4, "word": "moreover", "phonetic": "[morov]", "pos": "adv.", "meaning": "并且.，此外", "examples": [], "sub_entries": []}, {"num": 5, "word": "popular", "phonetic": "[ˈpapjalo]", "pos": "a.", "meaning": "受人欢迎的", "examples": [{"en": "That teacher is very popular with her students.", "zh": "那位老师非常受她学生的欢迎。"}], "sub_entries": ["be popular with+众人", "受到一群人的欢迎"]}, {"num": 6, "word": "on the other hand", "phonetic": "", "pos": "短语", "meaning": "另一方面", "examples": [{"en": "On the one hand, it's fun to have a dog. On the other hand, it's a big responsibility.", "zh": "一方面来说，养狗很好玩。但另一方面来说，那是个很大的责任。"}], "sub_entries": ["on(the) one hand...on the other (hand)", "一方面····另方面"]}, {"num": 7, "word": "rude", "phonetic": "[rud]", "pos": "a.", "meaning": "粗鲁的，无礼的", "examples": [{"en": "Don't interrupt; it is very rude.", "zh": "别打断别人的谈话，那是很无礼的。"}], "sub_entries": ["rudeness['rudnis]n.粗鲁，无礼"]}, {"num": 8, "word": "look", "phonetic": "", "pos": "", "meaning": "down upon +人", "examples": [{"en": "People look down upon Barry, because he is a thief. People look up to a good leader.", "zh": "人们都瞧不起巴里，因为他是个贼。）（人们都尊敬一位好的领导者。"}], "sub_entries": ["轻视某人", "look up to+人", "瞧得起/尊敬某人"]}, {"num": 9, "word": "poor", "phonetic": "[pur]", "pos": "a.", "meaning": "差劲的，不良的", "examples": [], "sub_entries": []}, {"num": 10, "word": "education", "phonetic": "[ˌedʒuˈkeɪʃən]", "pos": "n.", "meaning": "教育", "examples": [{"en": "Carl has a college education. Chris was educated in England.", "zh": "卡尔受过大学教育。）（克里斯是在英国受教育的。"}], "sub_entries": ["educate['sd3a.ket ]vt.教育"]}, {"num": 11, "word": "therefore", "phonetic": "[erfor]", "pos": "adv.", "meaning": "因此", "examples": [{"en": "We spent all our money; therefore, we had to go home.", "zh": "我们把钱全花光了，因此，我们只得回家去。"}], "sub_entries": []}, {"num": 12, "word": "simple", "phonetic": "[ˈsimpl]", "pos": "a.", "meaning": "简单的", "examples": [], "sub_entries": []}, {"num": 13, "word": "make", "phonetic": "", "pos": "", "meaning": "abig difference产生很大的不同", "examples": [{"en": "Your help can make a big difference.", "zh": "你的帮忙可以使情况大为改观。"}], "sub_entries": ["difference['difarans ]n.差异，不同"]}], "grammar": {"intro": "本课主要介绍被动语态的形成及用法。", "items": [{"num": 1, "title": "On the other hand, rude people are looked down upon.", "body": ["（另一方面，无礼的人则遭人轻视。）", "本句中的 \"are looked down upon\"（被轻视）乃短语动词 \"look down upon\" 的被动语态。", "a. “被动语态”均由及物动词形成，句型如下：", "主语+及物动词+宾语", "主语+be动词+过去分词+by+宾语", "例：They respect him.", "He is respected by them.", "（他受到他们的尊敬。）", "例：主动：The teacher punished the naughty boy.", "被动：The naughty boy was punished by the teacher.", "（这顽皮的男孩被老师处罚了。）", "b. 及物动词变成被动语态时，除非绝对必要，否则“by+宾语”往往省略。故以上二例均可写成：", "He is respected.（他受到尊敬。）", "The naughty boy was punished.（这顽皮的男孩被处罚了。）", "c. 及物动词多是一个单词（如上例中的 respect 及 punish），但有时亦由两个或三个单词所构成，此时就称为短语动词，它们共同的特征就是最后一个单词一定是介词。兹列举一些常用的短语动词如下：", "look at", "凝视", "point at", "指着", "rely on", "依赖", "pay attention to", "注意", "look down upon", "轻视", "take care of", "照顾，注意", "例：I cannot rely on him.（我不能依赖他。）", "Everyone looks down upon him.（每个人都轻视他。）", "以上两个例句中的短语动词均视为及物动词，之后皆有宾语，故可使用被动语态。原则和一般及物动词一样。但初学英文的人，将短语动词变成被动语态时，往往漏了介词。", "例：He cannot be relied. (×) → He cannot be relied on. (○)（他不能被依赖。）", "A liar is looked down. (×) → A liar is looked down upon. (○)（说谎的人被人轻视。）"]}, {"num": 2, "title": "Therefore, why not be polite?", "body": ["（因此，何不有礼貌一点呢？）", "why 或 why not之后可直接用动词原形，形成简略", "的问句。", "a.Why+动词原形？", "=Why should I/we+动词原形？", "（我／我们为何要...·？）", "例：Why stay here?", "=Why should 1/we stay here?", "（我／我们为什么要待在这里？）", "Why be quiet?", "= Why should 1/we be quiet?", "（我／我们为什么要安静？）", "b.Why not+动词原形？", "=Why can't you/we+动词原形?", "（你／你们／我们为何不能...·？）", "例：Why not be quiet?", "= Why can't you/we be quiet?", "（你／你们／我们为何不能安静呢？）", "Why not stay here?", "= Why can't you/we stay here?", "（你／你们／我们为何不能待在这里？）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 48, "title_en": "Don't Mention It", "title_zh": "别客气", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Angell", "speaker_zh": "安吉尔", "en": "Excuse me, Chris. Could you pass me the sugar, please?", "zh": "对不起，克里斯·请你把糖递给我，好吗？"}, {"speaker_en": "Chris", "speaker_zh": "克里斯", "en": "Sure. Here you are.", "zh": "没问题·这就是。"}, {"speaker_en": "Angell", "speaker_zh": "安吉尔", "en": "Thanks.", "zh": "谢谢。"}, {"speaker_en": "Chris", "speaker_zh": "克里斯", "en": "Don't mention it.", "zh": "别客气。"}]}, "vocab": [{"num": 1, "word": "Excuse me.", "phonetic": "", "pos": "日常口语", "meaning": "对不起。", "examples": [{"en": "A: Excuse me. Could you show me the way to the station? B: I'm sorry. I'm new here.", "zh": "甲：对不起。你能否告诉我车站怎么个走法？）（乙：抱歉。我刚到这儿来，路不熟。"}], "sub_entries": ["excuse[ik'skjuz]vt.原谅", "\"Excuseme.”是说话者用来表示要打扰对方的客气用", "语。而\"I'msorry.”亦译成“对不起”或“抱歉”", "但\"I'msorry.\"是说话者用来表示帮不上忙或未达到", "对方期望时的用语。"]}, {"num": 2, "word": "Could you pass me the sugar, please?", "phonetic": "", "pos": "日常口语", "meaning": "请你把糖递给我好吗？", "examples": [], "sub_entries": ["=Could you pass the sugar to me, please?", "pass [pes]vt.传递", "sugar[Jug]n.砂糖"]}, {"num": 3, "word": "Don't mention it.", "phonetic": "", "pos": "日常口语", "meaning": "别客气。", "examples": [], "sub_entries": ["=You're welcome.", "=Sure thing.", "mention['menjan ]vt.提及"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ．请选出下列各句中正确的一项", "questions": ["1. Why", "go to the movies tonight?", "(A) not we (B) do not we (C) not (D) don't", "2. He is liked", "(A) by we", "(B)us", "(C) by she (D) by us", "3. Look", "that man over there.", "(A) at", "(B)into", "(C) up", "(D) down", "4.Why", "I be honest?", "(A) not (B) shouldn't", "(C) be", "(D) not be", "5. Bill is very honest. You can rely", "him.", "(A)in(B)at", "(C)on(D) around", "6. Can you please", "(A) pass me the book", "(B) pass the book against me", "(C) pass me to the book", "(D) pass the book give me"], "answers": ["解答>1.(C）2.(D）3.(A）4.(B）5.(C）6.(A)"]}}, {"num": 49, "title_en": "Never Talk to Strangers", "title_zh": "千万别跟陌生人说话", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Something  strange happened  to me yesterday. On my way to school, I met a stranger. He stopped me and said, \"You are Betty, aren't you?\" \"No,\" I replied. He asked, \"You know me, don't you?\" \"l don't,\" I answered. Then he said, \"You owe me $100, don't you?\" I ran away. At that moment, 1 remembered my mother's words: \"Never talk to strangers.\""], "zh": ["昨天有一件怪事发生在我身上。我在上学途中遇见一位陌生了。就在那个时候，我想起母亲对我说过的话：“千万别跟陌生人说话。”"]}, "dialog": null, "vocab": [{"num": 1, "word": "stranger", "phonetic": "[ˈstreɪndʒər]", "pos": "n.", "meaning": "陌生人", "examples": [], "sub_entries": []}, {"num": 2, "word": "strange", "phonetic": "[ˈstreɪndʒ]", "pos": "a.", "meaning": "奇怪的", "examples": [], "sub_entries": []}, {"num": 3, "word": "happen", "phonetic": "[ˈhapan]", "pos": "vi.", "meaning": "发生", "examples": [{"en": "Good things always happen to me.", "zh": "好事总是会发生在我身上。"}], "sub_entries": ["happen to+人", "发生在某人身上"]}, {"num": 4, "word": "on one's way to + 地方名词", "phonetic": "", "pos": "短语", "meaning": "在我往...的途中", "examples": [{"en": "On my way to the grocery store, I saw an old friend.", "zh": "我在往杂货店的途中看见一位老友。"}], "sub_entries": ["*此短语中的所有格代词可任意更换，如your（你", "的）、his（他的）、her（她的）、their（他们", "的）等，形成不同的意思。"]}, {"num": 5, "word": "stop", "phonetic": "[stap]", "pos": "vt.", "meaning": "阻止", "examples": [], "sub_entries": []}, {"num": 6, "word": "reply", "phonetic": "[rɪˈplaɪ]", "pos": "vt.", "meaning": "回答", "examples": [{"en": "I asked Mary to go to the movies with me. She replied, \"I'm too busy.\"", "zh": "我找玛丽和我一起去看电影·她回答说：“我太忙了。”"}], "sub_entries": []}, {"num": 7, "word": "answer", "phonetic": "[ˈens]", "pos": "vt.", "meaning": "回答", "examples": [], "sub_entries": ["*本单词在本文中即等于reply."]}, {"num": 8, "word": "owe", "phonetic": "[o]", "pos": "vt.", "meaning": "欠", "examples": [{"en": "You still owe me fifty dollars.", "zh": "你还欠我50元美金。"}], "sub_entries": ["owe+人+钱", "欠某人（多少）钱"]}, {"num": 9, "word": "run away", "phonetic": "", "pos": "短语", "meaning": "跑走（ran为run的过去式）", "examples": [], "sub_entries": []}, {"num": 10, "word": "at that moment", "phonetic": "", "pos": "短语", "meaning": "在那一刻", "examples": [], "sub_entries": ["moment['momant]n.片刻，瞬间"]}, {"num": 11, "word": "remember", "phonetic": "[rlˈmsmb]", "pos": "vt.", "meaning": "记得", "examples": [{"en": "I'm sorry. I don't remember your name.", "zh": "很抱歉。我不记得你的大名了。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍反问句的句型及用法。", "items": [{"num": 1, "title": "You are Betty, aren't you?", "body": ["（你是贝蒂，对不对？）", "You know me, don't you?（你认识我，对不对？）以上两句均为反问句（亦称附加问句）。反问句形成的 基本原则是：肯定句应以否定反问，否定句则以肯定 反问·句型通常有下列五种：", "a. 句中有be动词时，以该be 动词形成反问。", "例：肯定句：He is polite，isn't he?（他很有礼貌，对不对？）", "否定句: You aren't happy, are you?（你不快乐，对不对？）", "b. 句中有助动词时，以该助动词形成反问。", "例：肯定句：He can do it，can't he?（他能做这件事，对不对？）", "否定句:He won't come, will he?（他不会来，对不对？）", "c. 肯定句中有一般动词时，应按时态及人称，以do、does或did形成反问；否定句中因已有do does 或did，反问部分则仍使用do、does或 did。", "例：肯定句：He studies hard, doesn't he?（他很用功，对不对？）", "否定句：They didn't like it，did they?（他们不喜欢它，对不对？）", "d. 以Let's（Letus 的缩写形）引导的祈使句，其反 问部分固定为 shallwe。", "例: Let's go, shall we?（咱们走吧，好不好？）", "Let's rest for a while, shall we?（咱们休息一下，好不好？）", "e. 以动词原形起首的命令句，其反问部分固定为will you。", "例：Come here, will you?（到这里来，好不好？）", "Be quiet, will you?（安静点，好不好？）"]}, {"num": 2, "title": "使用反问句时，注意下列事项：", "body": ["a. 反问部分的主语始终为人称代词。", "例: John is angry with me, isn't John? (×)", "-→ John is angry with me, isn't he? (○)（约翰生我的气，对不对？）You, John and I are good friends, aren't we?（你、约翰和我都是好朋友，对不对？）", "b. 句中主语若为指示代词this、that、these those时，反问部分则一律使用it或they。", "例：That is good, isn't that?（×)", "→That is good, isn't it? (○)（那个东西不错，对不对？）These are beautiful, aren't these? (×)", "→These are beautiful, aren't they? (○)（这些很美，对不对？）", "c. 句子以 There is/There are 引导时，反问部分仍 使用 isn't there/aren't there。", "例：There is a man there, isn't it? (×)", "→There is a man there, isn't there? (○)（那里有个人，对不对？）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 50, "title_en": "You're Sally, Aren't You?", "title_zh": "你是萨莉，对不对？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "George", "speaker_zh": "乔治", "en": "Excuse me. You're Sally, aren't you?", "zh": "对不起。你是萨莉，对不对？"}, {"speaker_en": "Sally", "speaker_zh": "萨莉", "en": "Yes.", "zh": "对的。"}, {"speaker_en": "George", "speaker_zh": "乔治", "en": "Hi! I'm George. You remember me, don't you?", "zh": "嗨！我是乔治。你还记得我吧，对不对？"}, {"speaker_en": "Sally", "speaker_zh": "萨莉", "en": "No.", "zh": "不记得了。"}, {"speaker_en": "George", "speaker_zh": "乔治", "en": "We met at Bill's party.", "zh": "我们在比尔的宴会上见过面啊。"}, {"speaker_en": "Sally", "speaker_zh": "萨莉", "en": "Now I remember. Nice to see you again.", "zh": "现在我想起来了·很高兴再次见到你。"}]}, "vocab": [{"num": 1, "word": "remember", "phonetic": "[rlˈmemb]", "pos": "vt.", "meaning": "记得，想起", "examples": [{"en": "I can't remember her telephone number.", "zh": "我记不得她的电话号码。"}], "sub_entries": []}, {"num": 2, "word": "Nice to see you again.", "phonetic": "", "pos": "日常口语", "meaning": "很高兴再次见到你。", "examples": [{"en": "A: Nice to see you again, Joe. B: Nice to see you again, too, Mary.", "zh": "甲：很高兴能再次见到你，乔。）（乙：我也很高兴能再次见到你，玛丽。"}], "sub_entries": ["= It's nice to see you again."]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出正确的一项", "questions": ["1. Bob is a hard worker,", "he?", "(A) aren't (B) is", "(C) isn't", "(D) doesn't", "2. They swim very fast,", "they?", "(A) don't (B) doesn't (C) can't", "(D) do", "3.You didn't read that book,", "you?", "(A)didn't(B)did", "(C) do", "(D) don't", "4. Do it,", "you?", "(A)don't(B)do", "(C) didn't", "(D)will", "5. Let's go eat,", "we?", "(A)will", "1(B)won't (C) shall", "(D) shall not"], "answers": ["解答>1.(C）2.(A）3.(B）4.(D）5.(C)"]}}, {"num": 51, "title_en": "My Girlfriend", "title_zh": "我的女友", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My girlfriend always complains. According to her, l should be more ambitious. 1 should work harder and earn more money. She also thinks I should live in a bigger and nicer apartment. In a way, she's right. However, she should be more considerate and less critical. After all, I am trying my best. Besides, money isn't everything."], "zh": ["我的女友老爱发牢骚。根据她的说法，我应当更有进取心。我应当更卖力地工作，挣更多的钱。她也认为我应当住更大更好的公寓·就某方面来说，她的话是对的。不过，她也应当多体谅少批评。毕竟，我正尽力而为。而且，金钱并非万能呀。"]}, "dialog": null, "vocab": [{"num": 1, "word": "complain", "phonetic": "[kamˈplen]", "pos": "vi.", "meaning": "抱怨", "examples": [{"en": "Bob often complains about his work. Mack complainedaboutworking sevendays a week.", "zh": "鲍勃经常抱怨他的工作。）（迈克抱怨说他一星期七天都在工作。"}], "sub_entries": ["complain about+名词/动名词抱怨.…."]}, {"num": 2, "word": "according", "phonetic": "", "pos": "", "meaning": "to+人", "examples": [{"en": "According to Judy, this is a good book.", "zh": "根据朱迪的说法，这是本好书。"}], "sub_entries": ["根据某人的说法", "according[akordig]adv.依照"]}, {"num": 3, "word": "ambitious", "phonetic": "[emˈbijes]", "pos": "a.", "meaning": "有上进心的，野心勃勃的", "examples": [{"en": "Peter is more successful than Bob because he is more ambitious.", "zh": "彼得比鲍勃成功，因为他比鲍勃更有上进心。"}], "sub_entries": []}, {"num": 4, "word": "harder", "phonetic": "[horda]", "pos": "adv.", "meaning": "更努力地（hard的比较级）", "examples": [], "sub_entries": []}, {"num": 5, "word": "earn", "phonetic": "[ɜːrn]", "pos": "vt.", "meaning": "赚得，挣得", "examples": [{"en": "Cathy earns a lot more money than I.", "zh": "凯茜挣得钱比我多。"}], "sub_entries": []}, {"num": 6, "word": "bigger", "phonetic": "[ˈbiɡa]", "pos": "a.", "meaning": "更大的(big 的比较级）", "examples": [], "sub_entries": []}, {"num": 7, "word": "nicer", "phonetic": "[ˈnaisa]", "pos": "a.", "meaning": "更好的（nice的比较级）", "examples": [], "sub_entries": []}, {"num": 8, "word": "apartment", "phonetic": "[aˈpartmant]", "pos": "n.", "meaning": "公寓", "examples": [], "sub_entries": []}, {"num": 9, "word": "in a way", "phonetic": "", "pos": "短语", "meaning": "就某方面而言", "examples": [{"en": "Mother thinks I'm lazy. In a way, she's right.", "zh": "我的母亲认为我很懒·就某方面而言，她是对的。"}], "sub_entries": []}, {"num": 10, "word": "right", "phonetic": "[rait]", "pos": "a.", "meaning": "正确的", "examples": [{"en": "No, Johnny. That is not the right answer.", "zh": "不对，约翰尼·那不是正确的答案。"}], "sub_entries": []}, {"num": 11, "word": "considerate", "phonetic": "[kanˈsidarit]", "pos": "a.", "meaning": "体谅的", "examples": [{"en": "Connie is the most considerate person (that) I know.", "zh": "康妮是我所认识的人里面最体谅人的一个。"}], "sub_entries": []}, {"num": 12, "word": "critical", "phonetic": "[ˈkritikl]", "pos": "a.", "meaning": "批评的", "examples": [{"en": "You shouldn't be so critical of others.", "zh": "你不应该对他人这么挑剔。"}], "sub_entries": ["be criticalof+名词", "批评.…..….，挑剔……··"]}, {"num": 13, "word": "after all", "phonetic": "", "pos": "短语", "meaning": "毕竟", "examples": [{"en": "Don't be mad at him. After all, he was only trying to help.", "zh": "别生他的气。毕竟，他只是想帮忙而已。"}], "sub_entries": []}, {"num": 14, "word": "try one's best", "phonetic": "", "pos": "短语", "meaning": "某人尽全力", "examples": [{"en": "You should try your best to help her.", "zh": "你应该尽全力帮她。"}], "sub_entries": []}, {"num": 15, "word": "besides", "phonetic": "[blˈsaidz]", "pos": "adv.", "meaning": "此外", "examples": [{"en": "I don't want to see that movie. Besides,I have work to do.", "zh": "我不想去看那部电影。此外，我有工作要做。"}], "sub_entries": []}, {"num": 16, "word": "Money isn't everything.", "phonetic": "", "pos": "谚语", "meaning": "金钱并非万能。（谚语）", "examples": [], "sub_entries": ["Money talks.", "有钱能使鬼推磨。（谚语）"]}], "grammar": {"intro": "本课旨在说明比较等级的形态及其用法。比较等级乃由形 容词或副词变化而成。由于副词的比较等级变化与形容词 相同，故本单元不予讨论，仅就形容词的比较等级加以说 明。 请先看下例： It's hot today, but it was hotter yesterday. （今天固然热，但是昨天更热。） She is beautiful, but her younger sister is even more beautiful. （她很美，但她妹妹更美。） He is good, but John is even better. （他不错，但约翰更好。） 以上句中的hotter、morebeautiful及better均属形 容词的比较级。 再请看下列例句： Today is the hottest day of the year. （今天是今年最热的一天。） She is the most beautiful girl in her class. （她是班上最美的女孩子。） He is the best student of all. （他是所有学生里最棒的一位。） 以上句中的hottest、most beautiful、best 均属形容词 的最高级，与定冠词the并用。由上得知，形容词的比较 等级有两种：一为比较级，一为最高级。兹列表如下： 原级 比较 级 最 高 级 beautiful morebeautiful比较美丽的 most beautiful最美丽的 美丽的 hot热的 hotter比较热的 hottest最热的 good好的 better比较好的 best 最好的 我们看了上面的表格后，不禁要问：“hot的比较级为何 不可写成more hot？good的比较级为何不是gooder, 而是better？beautiful的比较级为何是morebeautiful, 而非beautifuler？”", "items": [{"num": 1, "title": "一般而言，形容词的比较等级变化有下列原则：", "body": ["a. 原级是双音节或三音节以上的形容词", "比较级：more+原级 最高级：most+原级 原 级 比 较 级 最 高 级", "beautiful(美丽的）", "more beautiful most beautiful", "considerate(体谅的）", "more considerate most considerate", "b. 原级是单音节的形容词", "比较级：原级+-er 最高级：原级+-est 原 级 比 较 级 最 高 级", "tall(高的）", "taller tallest", "fast(快速的）", "faster fastest 比较级：重复该辅音字母+-er 最高级：重复该辅音字母+-est 原 级 比 较 级 最 高 级", "hot（热的）", "hotter hottest", "fat(肥胖的）", "fatter fattest", "d. 原级是以-e结尾的单音节形容词，或以-le结尾的 双音节形容词 比较级：原级+-r 最高级：原级+-st 原 级 比 较 级 最高级", "wise（有智慧的）", "wiser wisest", "gentle(温和的）", "gentler gentlest", "e. 形容词结尾为“辅音+-y”时 比较级：将y改成i+-er 最高级：将y改成i+-est 原 级 比 较 级 最高级", "pretty（美丽的）", "prettier prettiest", "easy(容易的）", "easier easiest 以上的比较等级变化称作规则变化。但亦有些形容 词则呈不规则变化，如：", "原 级 比 较 级 最 高 级", "good(好的）", "better, 非more good best，非 most good", "bad(坏的）", "worse，非 more bad worst,非most bad 所幸这些不规则变化的形容词并不多。限于篇幅，我们无法一一列出。读者唯有多读英文文章，见到 一个就熟记一个。所有精通英语的人士都曾经过这 个过程。"]}, {"num": 2, "title": "形容词比较级与最高级：less 与 least 的用法", "body": ["在原级的形容词之前冠以副词 less 或 least，则分别表示“较不...”或“最不...”之意。", "cuter(（较不可爱的）", "cutest（最不可爱的）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 52, "title_en": "Sam's OK", "title_zh": "小三子不错", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Father", "speaker_zh": "父亲", "en": "Do you like Ray or Sam?", "zh": "你喜欢小雷还是小三子？"}, {"speaker_en": "Daughter", "speaker_zh": "女儿", "en": "I like Ray.", "zh": "我喜欢小雷。"}, {"speaker_en": "Father", "speaker_zh": "父亲", "en": "Why?", "zh": "为什么？"}, {"speaker_en": "Daughter", "speaker_zh": "女儿", "en": "Sam's OK, but Ray's taller, cuter and more interesting. What about you?", "zh": "小三子固然不错，但小雷个儿较高、较可爱、也较风趣·您觉得呢？"}, {"speaker_en": "Father", "speaker_zh": "父亲", "en": "I like Sam better.", "zh": "我比较喜欢小三子。"}, {"speaker_en": "Daughter", "speaker_zh": "女儿", "en": "Why?", "zh": "为什么？"}, {"speaker_en": "Father", "speaker_zh": "父亲", "en": "He's less proud. Besides, he's richer!", "zh": "他比较不骄傲。而且，他比较有钱！"}]}, "vocab": [{"num": 1, "word": "OK", "phonetic": "[oˈke]", "pos": "a.", "meaning": "不错的（亦可写成okay)", "examples": [], "sub_entries": []}, {"num": 2, "word": "cute", "phonetic": "[kjut]", "pos": "a.", "meaning": "可爱的", "examples": [{"en": "Sally is the cutest child in the kindergarten.", "zh": "萨莉是幼儿园里最可爱的孩子。"}], "sub_entries": []}, {"num": 3, "word": "interesting", "phonetic": "[ˈintristin]", "pos": "a.", "meaning": "令人觉得有趣的，风趣的", "examples": [{"en": "Grace is a very interesting woman. What are you interested in?", "zh": "格雷斯是位非常风趣的女士。）（你对什么有兴趣呢？"}], "sub_entries": ["interested['intristid]a.感到有兴趣的"]}, {"num": 4, "word": "proud", "phonetic": "[praud]", "pos": "a.", "meaning": "骄傲的", "examples": [{"en": "Although you are successful, you should be less proud.", "zh": "虽然你很成功，但你不应该这么骄傲。"}], "sub_entries": []}, {"num": 5, "word": "rich", "phonetic": "[rit]", "pos": "a.", "meaning": "有钱的", "examples": [{"en": "The king is the richest man in the city, but not the happiest.", "zh": "国王是城里最有钱的人，但却不是最快乐的人。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. I am good at basketball, but Peter is", "(A) more good", "(B) better", "(C) best", "(D) most good", "2.Fred is the", "student in the class.", "(A) worst (B) bad (C) most bad (D) more bad", "3. They are all beautiful, but Betty is the", "(A)beautifulest", "(B) prettier", "(C) more beautiful", "(D) most beautiful", "4.Yesterday was cold, but today is", "(A)coldest (B)colder (C)most cold (D）cold", "5. These dogs are not cute, and this one is the", "(A) less cute", "(B)less cuter", "(C) least cute", "(D）least cutest", "6. I like this book. It is very", "(A)interested", "(B) interest", "(C) interests", "(D) interesting"], "answers": ["解答>1.(B）2.(A）3.(D）4.(B）5.(C）6.(D)"]}}, {"num": 53, "title_en": "Country Life", "title_zh": "乡间生活", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My parents prefer to live in the country. The streets there are cleaner. The air is fresher  and the people  are nicer and friendlier. Besides, it is busier and noisier in the city. But above all, it is safer to live in the country. My parents believe in the saying, \"Safety first.\""], "zh": ["我爸妈比较喜欢住在乡下。那儿的街道比较干净·空气较新鲜，人也比较好、比较友善·而且，都市里比较忙碌，也比较言：“安全至上。”"]}, "dialog": null, "vocab": [{"num": 1, "word": "parent", "phonetic": "[ˈperant]", "pos": "n.", "meaning": "父或母", "examples": [], "sub_entries": []}, {"num": 2, "word": "prefer", "phonetic": "[prɪˈfɜːr]", "pos": "vt.", "meaning": "比较喜欢", "examples": [{"en": "I prefer to stay in and rest tonight.", "zh": "今晚我宁愿待在家里休息。"}], "sub_entries": ["prefer to+动词原形", "比较喜欢…·…；宁愿……·."]}, {"num": 3, "word": "country", "phonetic": "[ˈkantri]", "pos": "n.", "meaning": "乡下（与定冠词 the 并用）", "examples": [], "sub_entries": []}, {"num": 4, "word": "street", "phonetic": "[strit]", "pos": "n.", "meaning": "街", "examples": [], "sub_entries": []}, {"num": 5, "word": "clean", "phonetic": "[klin]", "pos": "a.", "meaning": "干净的", "examples": [], "sub_entries": []}, {"num": 6, "word": "air", "phonetic": "[εr]", "pos": "n.", "meaning": "空气", "examples": [], "sub_entries": []}, {"num": 7, "word": "fresh", "phonetic": "[fre{]", "pos": "a.", "meaning": "新鲜的", "examples": [], "sub_entries": []}, {"num": 8, "word": "friendly", "phonetic": "[ˈfrendli]", "pos": "a.", "meaning": "友善的", "examples": [{"en": "I am friendly with my neighbors.", "zh": "我对我的邻居很友善。"}], "sub_entries": ["be friendly with+人", "对某人友善"]}, {"num": 9, "word": "busy", "phonetic": "[ˈbizi]", "pos": "a.", "meaning": "忙碌的", "examples": [{"en": "He is busy to write a letter. (×) → He is busy writing a letter. (○)", "zh": "他正忙着写信。"}], "sub_entries": ["be busy（in)+动名词忙着从事.…."]}, {"num": 10, "word": "noisy", "phonetic": "[ˈnoizi]", "pos": "a.", "meaning": "吵闹的", "examples": [{"en": "The television is too noisy; turn it down.", "zh": "电视声音太大了，关小声点。"}], "sub_entries": []}, {"num": 11, "word": "city", "phonetic": "[ˈsitu]", "pos": "n.", "meaning": "城市", "examples": [], "sub_entries": []}, {"num": 12, "word": "above all", "phonetic": "", "pos": "短语", "meaning": "最重要的是", "examples": [{"en": "The doctor told my father to go on a diet. Above all, he told him to stop smoking.", "zh": "医生叫我父亲节食·最重要的是，他叫他要戒烟。"}], "sub_entries": ["=most important of all", "aboveall是作副词用的介词短语，使用时置于句首，", "之后置逗号，修饰全句。"]}, {"num": 13, "word": "safe", "phonetic": "[sef]", "pos": "a.", "meaning": "安全的", "examples": [], "sub_entries": ["safety['sefti ]n.安全"]}, {"num": 14, "word": "believe in...", "phonetic": "", "pos": "短语", "meaning": "笃信...", "examples": [{"en": "I believe in working hard.", "zh": "我深信辛勤工作是对的。"}], "sub_entries": ["笃信·.…", "believe[br'liv]vi.&vt.相信"]}, {"num": 15, "word": "saying", "phonetic": "[ˈserɡ]", "pos": "n.", "meaning": "格言", "examples": [], "sub_entries": []}], "grammar": {"intro": "", "items": [{"num": 1, "title": "形容词比较级的规则变化", "body": ["本课仍侧重于形容词比较级的变化。如 clean 变成 cleaner（更清洁的）、busy 变成 busier（更忙碌的）、noisy 变成 noisier（更吵闹的）、safe 变成 safer（更安全的）等。"]}, {"num": 2, "title": "prefer的用法", "body": ["a. prefer to+动词原形 比较喜欢.···", "例： I prefer to listen to music.（我比较喜欢听音乐。）", "b. prefer to+动词原形+rather than+动词原形 喜欢.....胜于.….··此处ratherthan视为并列连词，表示“而非”之 意，连接两个动词原形。", "例：I prefer to listen to music rather than watch TV.（我喜欢听音乐胜于看电视。）", "c. prefer+名词+to+名词喜欢..….胜于.….... 此处to是介词，有“针对”的意味，\"prefer A to B\"表示“就A和B而言，比较喜欢A”。", "例：I prefer music to movies.（我喜欢音乐胜于电影。）"]}, {"num": 3, "title": "Besides, it is busier and noisier in the city.", "body": ["（而且，城市里比较忙碌，也比较吵。）此处的it是代词，泛指某地的环境。使用这个it时，句尾一定有一个表示场所的介词短语。中文：房间里很闷。（stuffy['stafi]a.闷热的）英文：In the room is stuffy.（×）理由：in theroom是介词短语，不能作主语。只有 名词或代词方可作主语。改正：It is stuffyin the room.（O）说明：此处It指房间里的环境。"]}, {"num": 4, "title": "...it is safer to live in the country.", "body": ["（...·…住在乡下较安全。）初学英文的人容易将这句中文译成：", "Live in the country is safer.(×)这当然是错误的句子，因为动词不可以直接作主语。动词应变成不定式（即to+动词原形）或动名词（即 动词字尾加-ing）方可作主语·故上句中的动词应变 成Tolive或Living才合语法。即：", "To live in the country is safer. (○)", "=Living in the country is safer.（住在乡下较安全。）但这种不定式或动名词短语所形成的主语往往过大，故写作的人经常用it代替这些过大的主语，不定式或 动名词短语则移至句尾，此时动名词亦常改为不定 式。即：", "To live in the country is safer.(○)", "=It is safer to live in the country.(佳）Living in the country is safer. (○)", "=It is safer livingin the country.（佳）", "=It is safer to live in the country.（佳）了解上面的说明后，我们不妨试译下列中文句子：", "中文：学英文很有趣。英文：Learn English is interesting.（×）-→ Learning English is interesting. (○)", "=It is interesting to learn English.(佳）"]}, {"num": 5, "title": "believe 作及物与不及物动词的区别", "body": ["believe 可作及物或不及物动词。believe 作及物动词时，之后直接接宾语；believe 若作不及物动词时，须接介词 in 之后，方可接宾语。区别如下：", "believe+宾语相信某人/某人的话 believein+宾语坚信某格言／信仰某宗教/相信 某种神的存在（强调信仰或信念）", "例：I believe him.（我相信他。）", "I believe what he says.（我相信他的话。）He believes in Buddhism.（他信奉佛教。）Do you believe in God?（你相信上帝的存在吗？）I believe in the saying, \"Live and learn.\"（我认为：“活到老，学到老。”这句格言很有道 理。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 54, "title_en": "I Like Brighter Colors", "title_zh": "我喜欢较明亮的颜色", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "Do you like my new dress, Mike?", "zh": "迈克，你喜欢我这件新的女式套装吗？"}, {"speaker_en": "Mike", "speaker_zh": "迈克", "en": "Frankly, I like brighter colors better. They make you look younger.", "zh": "坦白说，我比较喜欢明亮一点的颜色。它们会使你看起来年轻些。"}, {"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "Do darker colors make me look older?", "zh": "深一点的颜色会使我看起来年纪大一点啰？"}, {"speaker_en": "Mike", "speaker_zh": "迈克", "en": "Well...yes.", "zh": "咂.…·…·是的。"}, {"speaker_en": "Tracy", "speaker_zh": "特蕾西", "en": "Then, buy me another dress.", "zh": "那么，给我另外买一套吧！"}]}, "vocab": [{"num": 1, "word": "bright", "phonetic": "[brait]", "pos": "a.", "meaning": "明亮的", "examples": [], "sub_entries": []}, {"num": 2, "word": "frankly", "phonetic": "[ˈfræŋkli]", "pos": "adv.", "meaning": "坦白地说", "examples": [{"en": "Frankly, I don't like your idea. =To be frank with you, I don't like your idea.", "zh": "坦白地说，我不喜欢你的构想。"}], "sub_entries": ["此副词常置于句首，之后置逗号，修饰全句。相当于", "tobefrankwithyou（坦白地对你说）。"]}, {"num": 3, "word": "young", "phonetic": "[jaɡ]", "pos": "a.", "meaning": "年轻的", "examples": [], "sub_entries": []}, {"num": 4, "word": "dark", "phonetic": "[dark]", "pos": "a.", "meaning": "暗的", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.", "a bicycle in the mountains is fun.", "(A)Ride", "(B）Riding(C)Rides(D）Rode", "2. It is more relaxing", "in the country.", "(A) to live (B) to living (C) lived", "(D) to lives", "3. I prefer Chinese food", "American food.", "(A) or", "(B)than", "(C) to", "(D) but", "4. David prefers to watch TV rather than", "(A) go to movie", "(B) going to movie", "(C) going to see movie", "(D) go to the movies", "5. Joe is friendly, but Kathy is", "(A） friendlier", "(B） friendlyer", "(C) friendly", "(D) more friendlier", "6.", ",you should work harder.", "(A) To be frankly", "(B) Being frankly", "(C) I am frank with you", "(D) To be frank with you"], "answers": ["解答→1.(B）2.(A）3.(C）4.(D）5.(A）6.(D)"]}}, {"type": "song", "id": "song_03", "title_en": "Stoney", "title_zh": "史东妮", "lyrics": [], "category": "经典英文金曲赏析"}, {"num": 55, "title_en": "More Is Not Always Better", "title_zh": "多未必佳", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Some people have more money than others. However, they're not necessarily happier. On the other hand, some people are as poor as church mice, but they are happy. In a way, these poor people are as rich as kings. Therefore, I always remember my father's words, \"More is not always better.\""], "zh": ["有些人比别人有钱。不过，他们未必就比较快乐。另一方人却像国王一样富有·因此，我始终记得父亲的话：“多未必佳。”"]}, "dialog": null, "vocab": [{"num": 1, "word": "than", "phonetic": "[dan]", "pos": "conj.", "meaning": "比....", "examples": [{"en": "He is more knowledgeable than his father.", "zh": "他比他父亲更有学问。"}], "sub_entries": []}, {"num": 2, "word": "however", "phonetic": "[hauˈev]", "pos": "adv.", "meaning": "不过", "examples": [{"en": "John is neither handsome nor rich. However, he is nice.", "zh": "约翰既不英俊又不富有，不过他人很好。"}], "sub_entries": []}, {"num": 3, "word": "not necessarily", "phonetic": "", "pos": "短语", "meaning": "未必", "examples": [{"en": "The boss isn't necessarily always right.", "zh": "老板未必永远是对的。"}], "sub_entries": ["necessarily[.nesa'seral1]adv.必然地"]}, {"num": 4, "word": "as poor as a church mouse", "phonetic": "", "pos": "短语", "meaning": "一贫如洗，赤贫（与单数主语并用）", "examples": [{"en": "The businessman lost everything he had and is now as poor as a church mouse.", "zh": "那个商人失去所有的东西，现在穷得要命。"}], "sub_entries": ["aspoor aschurch mice（与复数主语并用）", "*穷得像教堂里的老鼠一样，比喻“穷得要命”。", "church[tjat]n.教堂"]}, {"num": 5, "word": "king", "phonetic": "[kin]", "pos": "n.", "meaning": "国王", "examples": [], "sub_entries": []}, {"num": 6, "word": "remember", "phonetic": "[rlˈmemb]", "pos": "vt.", "meaning": "记住", "examples": [{"en": "Mary remembered my birthday.", "zh": "玛丽记得我的生日。"}], "sub_entries": []}, {"num": 7, "word": "words", "phonetic": "[wɜːrdz]", "pos": "n.", "meaning": "（某人所说的）话（word的复数）", "examples": [{"en": "I don't believe his words. He is a liar.", "zh": "我不相信他的话，他是个骗子。"}], "sub_entries": []}, {"num": 8, "word": "more", "phonetic": "[mor]", "pos": "", "meaning": "a．更多的（much 的比较级）&", "examples": [{"en": "I have more friends than you. She is more beautiful than Mary. He has a lot of money, but she has more.", "zh": "我的朋友比你多。）*本句中的more是形容词。（她比玛丽更漂亮。）*本句中的more是副词。（他固然钱很多，但她的钱却更多。）*本句中的more是代词，等于moremoneyo"}], "sub_entries": ["adv.更加&pron.更多的份量"]}], "grammar": {"intro": "本课主要介绍\"more...than..（比.…...更.…...）及 \"as...as...（和....样..….）的用法。", "items": [{"num": 1, "title": "Some people have more money than others.", "body": ["（有些人比别人有钱。）此处的 than为从属连词，引导状语从句，修饰之前 的比较级形容词或副词。本句中的状语从句thanothers修饰其前的比较级形 容词more。than others 原本应为 than others do, do为助动词，代替之前主句中相同的动词have，此 处do已省略·兹将than引导的状语从句中动词省 略的法则陈述如下：", "a. 主句有be动词时，从句亦应使用be 动词，该be 动词通常予以省略。", "例：She is more beautiful than you do.（×)", "-→.She is more beautiful than you are.(○)", "=She is more beautiful than you.（她比你美。）", "b. 主句有一般动词时，从句理应使用相同的动词，但 为了避免重复，该动词应按时态及人称改为do、does 或did；而do、does或did通常亦予以省 略。", "例：He studies harder than I study.（劣，", "study与studies重复。）", "→He studies harder than I do.（佳，由于 study是现在式，故改用do取代。）", "=He studies harder than I.（他比我用功。）He came back earlier than I came back.（劣，cameback 重复。）", "→He came back earlier than I did.（佳，由 于came是过去式，故改用did。）", "=He came back earlier than I.（他比我早回来。）由上得知：", "Some people have more money than 动词 others have.（劣，have重复。）动词", "→ Some people have more money than others do.（佳）", "=Some people have more money than others."]}, {"num": 2, "title": "Some people have more money than others.", "body": ["（有些人比别人有钱。）本句中的others['Aaz]是代词，等于other people。some 亦可作代词，等于 some people。some...others... 有些人...有些人··…", "例: People have different hobbies. Some like", "togo swimming, and others are fond of dancing.（人的爱好各有不同。有些人喜欢游泳，有些人 则喜欢跳舞。）"]}, {"num": 3, "title": "Some people are as poor as church mice.", "body": ["（有些人穷得像教堂里的老鼠一样—一穷得要命。）In a way, these poor people are as rich as kings.（就某方面而言，这些穷人像国王·样富有。）以上两句均使用\"as...s...\"（和....….样地.…..….）这种\"as...as...”的句子结构一定要有形容词或副词方 可使用。因为第一个as是副词，译成““样地”，之后须接 形容词或副词以供该 as 修饰，第二个 as 则为从属连 词，译成“和”，之后接主语及动词，形成状语从句，修饰第一个as。但和 than引导的状语从句一样，第 二个as之后的动词为避免与主句的动词重复而省 略。省略的原则与than 引导的状语从句完全一样。", "a. 主句有be 动词时，从句亦应使用be动词，该be 动词通常予以省略。", "例：She is as beautiful as you do.（×)", "→She is as beautiful as you are.(○)", "=She is as beautiful as you.（她跟你-样美。）", "b. 主句有一般动词时，状语从句里理应使用相同的动 词，但为了避免重复，该动词应按时态及人称改为 do、does或did；而do、does 或did通常亦 予以省略。", "例：He studies as hard as I study.（劣，study", "与 studies 重复。）He studies as hard as I do.（佳，由于 study是现在式，故改由do取代。）", "=He studies as hard as I.（他跟我一样用功。）He came back as early as I came back.（劣，came back 重复。）-→He came back as early as I did.（佳，由 于came是过去式，故用did取代。）", "=He came back as early as I.（他和我一样早回来。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 56, "title_en": "I Want the Cheaper One", "title_zh": "我要买那只便宜的手表", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Why is this watch more expensive than that one?", "zh": "这只手表为什么比那只贵？"}, {"speaker_en": "Salesgirl", "speaker_zh": "女店员", "en": "Because its brand name is more famous.", "zh": "因为它的牌子比较出名。"}, {"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Is it more reliable?", "zh": "它比较可靠吗？"}, {"speaker_en": "Salesgirl", "speaker_zh": "女店员", "en": "No. Not really.", "zh": "不。不见得。"}, {"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Then, I want the cheaper one.", "zh": "那么，我要买那只便宜的手表。"}]}, "vocab": [{"num": 1, "word": "customer", "phonetic": "[ˈkastam]", "pos": "n.", "meaning": "顾客", "examples": [], "sub_entries": []}, {"num": 2, "word": "salesgirl", "phonetic": "[ˈseɪlzɡɜːrl]", "pos": "n.", "meaning": "女售货员，女店员", "examples": [], "sub_entries": []}, {"num": 3, "word": "brand name", "phonetic": "[brendnem]", "pos": "n.", "meaning": "商标名称，牌子", "examples": [], "sub_entries": []}, {"num": 4, "word": "famous", "phonetic": "[femas]", "pos": "a.", "meaning": "有名的", "examples": [{"en": "My sister is a famous singer.", "zh": "我妹妹是个名歌手。"}], "sub_entries": []}, {"num": 5, "word": "reliable", "phonetic": "[rilaiabl]", "pos": "a.", "meaning": "值得信赖的", "examples": [{"en": "Our postman is a reliable person.", "zh": "我们的邮差是位值得信赖的人。"}], "sub_entries": []}, {"num": 6, "word": "cheap", "phonetic": "[tip]", "pos": "a.", "meaning": "便宜的", "examples": [{"en": "Cheap perfume smells terrible.", "zh": "廉价香水闻起来很糟糕。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.Peter is taller than Harry", "(A) is", "(B) does", "(C) is tall", "(D) are", "2. Bobby writes better than I", "(A) does (B)am", "(C) do", "(D)is", "3.Joedid better on the test than we", "(A) do", "(B)have", "(C) did", "(D) are", "4.Sue's hair isn't", "Mary's.", "(A） curly as", "(B) as curly as", "(C) as curly than", "(D) as curly", "5. We worked as hard as they", "(A) did", "(B) are", "(C) have", "(D) does", "6.Kim's car is not as reliable as Peter's because", "it is", "(A) less cheap", "(B）more cheap", "(C) the most cheap", "(D) cheaper"], "answers": ["解答1.(A）2.(C）3.(C）4.(B）5.(A）6.(D)"]}}, {"num": 57, "title_en": "The Elephant and the Whale", "title_zh": "大象与鲸鱼", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["The biggest and strongest animal on land is the elephant. The largest and heaviest animal in the sea is the whale. It's also the biggest eater in the world. It eats a ton of food a day. It looks like a fish, but it is really a mammal. Although the elephant and the whale are both mammals, they are indeed very different."], "zh": ["陆地上最大、最壮的动物就是大象。海中最大、最重的动物则是鲸鱼，它也是世界上吃得最多的动物，它每天要吃一吨的食物。它看起来像鱼，但它实际上是哺乳动物。虽然大象和鲸鱼都是哺乳动物，它们却大不相同。"]}, "dialog": null, "vocab": [{"num": 1, "word": "elephant", "phonetic": "[ˈεlafant]", "pos": "n.", "meaning": "大象", "examples": [], "sub_entries": []}, {"num": 2, "word": "whale", "phonetic": "[hwel/wel]", "pos": "n.", "meaning": "鲸", "examples": [], "sub_entries": []}, {"num": 3, "word": "biggest", "phonetic": "[\"biɡist]", "pos": "", "meaning": "a．最大的（为big 的最高级）", "examples": [], "sub_entries": []}, {"num": 4, "word": "strongest", "phonetic": "[ˈstronɡist]", "pos": "a.", "meaning": "最强壮的（为 strong的最", "examples": [], "sub_entries": ["高级）"]}, {"num": 5, "word": "animal", "phonetic": "[ˈenaml]", "pos": "n.", "meaning": "动物", "examples": [], "sub_entries": []}, {"num": 6, "word": "on land", "phonetic": "", "pos": "短语", "meaning": "在陆地上", "examples": [{"en": "Some mammals live on land, and some live in the sea.", "zh": "有些哺乳动物居住在陆地上，而有些则居住在海洋里。"}], "sub_entries": ["land[lend]n.陆地"]}, {"num": 7, "word": "largest", "phonetic": "[ˈlɑːrdʒɪst]", "pos": "a.", "meaning": "最大的（为large 的最高级）", "examples": [], "sub_entries": ["*此处largest 即等于biggest，皆表体积最大的。"]}, {"num": 8, "word": "heaviest", "phonetic": "[ˈhevist]", "pos": "a.", "meaning": "最重的（为heavy的最高级）", "examples": [{"en": "Can you help me lift this heavy box?", "zh": "你可以帮忙我抬这个很重的箱子吗？"}], "sub_entries": ["heavy['hevi ]a.重的"]}, {"num": 9, "word": "sea", "phonetic": "[siː]", "pos": "n.", "meaning": "海洋", "examples": [], "sub_entries": []}, {"num": 10, "word": "eater", "phonetic": "[ˈito]", "pos": "n.", "meaning": "食者", "examples": [], "sub_entries": []}, {"num": 11, "word": "in the world", "phonetic": "", "pos": "短语", "meaning": "世界上", "examples": [{"en": "My son, Mike，is the cutest boy in the world.", "zh": "我儿子迈克是全世界最可爱的男孩。"}], "sub_entries": ["world[w3ld]n.世界"]}, {"num": 12, "word": "ton", "phonetic": "[tan]", "pos": "n.", "meaning": "吨", "examples": [], "sub_entries": ["a ton of...", "一吨的···"]}, {"num": 13, "word": "fish", "phonetic": "[fjf]", "pos": "n.", "meaning": "鱼", "examples": [], "sub_entries": []}, {"num": 14, "word": "mammal", "phonetic": "[ˈmeml]", "pos": "n.", "meaning": "哺乳动物", "examples": [], "sub_entries": []}, {"num": 15, "word": "indeed", "phonetic": "[nˈdid]", "pos": "adv.", "meaning": "实在", "examples": [{"en": "My teacher is indeed very knowledgeable.", "zh": "我的老师实在是很有学问。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍比较等级中形容词的最高级形及其用法。", "items": [{"num": 1, "title": "The biggest and strongest animal on land is the elephant.", "body": ["（陆地上最大、最壮的动物就是大象。）以上句中的biggest及strongest均为形容词的最高 级。在前面的课文中我们已提到形容词的比较级及最高级 的变化·本课则就形容词的最高级使用时应注意事项 提出说明如下：", "a. 形容词的最高级应与定冠词the并用：", "例： She is a most beautiful girl in her class.（×)", "→She is the most beautiful girl in her class.（o)（她是她班上最美丽的女孩子。）David is a best student in his school.（×）", "→David is the best student in his school.（o)（大卫是他学校中最好的学生。）", "b. 含有比较等级的句子结构中，有三个或三个以上的 比较对象时，方可使用最高级；若只有两个对象相 互比较时，只能使用比较级。", "例: Of the three girls, she is the most beautiful.（这三个女孩子中，她是最美的。）", "Of the ten students, David is the best.（这十个学生中，大卫是最好的一个。）Of the two books, this one is the more interesting.（这两本书中，这一本比较有趣。）Of the two teachers, John is the kinder.（这两位老师中，约翰是比较仁慈的一位。）", "c. 在b项的例句中，均含有\"of the+数字+名词\"", "的介词短语，句中的形容词不论是最高级或比较 级，其前均冠以定冠词the·且由于介词短语已有 名词出现，形容词的最高级或比较级之后相同的名 词就应省略。", "例：Of the two boys, John is better.（×）", "Of the two boys, John is the better boy .（劣，boy与boys重复）", "→ Of the two boys, John is the better. (○)（这两个男孩中，约翰比较好。）d．上列of 引导的介词短语中，数字为 three（三）或以上时，of可由among[a'map]（在·…..…·之 中）取代，但若为two（二）时，只能使用of，而 不可使用among。", "例： Of the five cars, the red one is the prettiest.", "=Among the five cars, the red one is the prettiest.（这五辆汽车中，红色的那一辆最漂亮。）Among the two cars, the red one is the prettier.（x)", "→Of the two cars, the red one is the prettier.(○)（这两辆汽车中，红色的那一辆比较漂亮。）", "e. 形容词的最高级与the之间可置数字（如two three等），与复数名词并用。", "例：John and Mary are the two best_students sin", "our class.（x)", "→John and Mary ar the two best students in our class.（O)（约翰和玛丽是我们班上最好的两个学生。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 58, "title_en": "The Smartest Teacher", "title_zh": "最聪明的老师", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Which country is the biggest in the world?", "zh": "世界上哪个国家最大？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "Russia.", "zh": "俄罗斯。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Which country has the most people in the world?", "zh": "世界上哪个国家有最多的人？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "China.", "zh": "中国。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Who is the smartest teacher in the school?", "zh": "本校中哪一位老师最聪明？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "But...you are the only teacher in the school.", "zh": "但是·…你是本校唯一的老师啊。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "I know.", "zh": "我知道。"}]}, "vocab": [{"num": 1, "word": "Russia", "phonetic": "[ˈrʌʃə]", "pos": "n.", "meaning": "俄罗斯", "examples": [], "sub_entries": []}, {"num": 2, "word": "Which country has the most people in the world?", "phonetic": "", "pos": "日常口语", "meaning": "世界上哪个国家有最多的人？", "examples": [{"en": "He has many friends. I have more friends. She has the most friends. much more most", "zh": "他朋友很多。）（我朋友比较多。）（她朋友最多。）most亦可作形容词much的最高级，后面接不可数名词，变化如下：原级比较级最高级"}, {"en": "→He doesn't have much money. (○) He has a lot of money. (○) I have more money. She has the most money.", "zh": "Hehas much money.（劣）（他钱不多。）（他钱很多。）（我的钱比较多。）（她的钱最多。"}], "sub_entries": ["比较：", "She is the most beautiful girl in her class.", "（她是她班上最美的女孩子。）", "在第二句中，most是副词，译成“最”，修饰后面的", "形容词beautiful·而在第一句中，most是形容词，", "译成“最多的”，修饰后面的名词people。", "由上得知，第一句中的 most 乃形容词 many 的最高", "级，后面接复数名词，变化如下：", "原级", "比较级", "最高级", "many", "more", "most"]}, {"num": 3, "word": "smart", "phonetic": "[smart]", "pos": "a.", "meaning": "聪明的", "examples": [{"en": "My wife is very smart. She married me, didn't she?", "zh": "我太太很聪明，她嫁给我了，不是吗？"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. Among the ten boys in the room, Bill is", "(A) the oldest", "(B)older", "(C) more old", "(D) most old", "2.", "two bicycles, this one is the more expensive.", "(A) Among", "(B) Among the", "(C) Of", "(D) Of the", "3. Miss Lee is", "patient teacher in the school.", "(A）most", "(B)a most (C) the most (D) more", "4.Of the four kids, Little Johnny has the", "toys.", "(A) many", "y(B)most", "(C) much", "(D） mostest", "5. Of the two men, my dad is", "(A) stronger", "(B） strongest", "(C) the strongest", "(D） the stronger", "6. My brother has", "toys, but I have", "toys.", "(A) many, many", "(B) more, many", "(C) many, more", "(D) more, most"], "answers": ["解答=>1.(A）2.(D）3.(C）4.(B）5.(D）6.(C)"]}}, {"num": 59, "title_en": "My Best Friend", "title_zh": "我最好的朋友", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My best friend is the most thoughtful person in the world. When I'm sad, he is the most sympathetic. When I'm sick, he is the most concerned. When I'm in trouble, he is the most helpful. In fact, he is the most dependable person in the world. He is the closest person to me. He is my father."], "zh": ["我最好的朋友是世界上最体贴的人。当我难过时，他最富有同情心了。我生病时，他最为关切。我有困难时，他最帮我了。事实上，他是世界上最值得信赖的人。他是我最亲的人。他就是我父亲。"]}, "dialog": null, "vocab": [{"num": 1, "word": "thoughtful", "phonetic": "[ˈootfal]", "pos": "a.", "meaning": "体贴的", "examples": [{"en": "It was very thoughtful of you to send me a birthday card.", "zh": "你寄给我生日卡片真是体贴。"}], "sub_entries": []}, {"num": 2, "word": "person", "phonetic": "[ˈpasn]", "pos": "n.", "meaning": "人（男性、女性皆可）", "examples": [{"en": "The mayor is the most important person in the city.", "zh": "市长是一个城市中最重要的人。"}], "sub_entries": []}, {"num": 3, "word": "sympathetic", "phonetic": "[simpaˈoetik]", "pos": "a.", "meaning": "同情的", "examples": [], "sub_entries": []}, {"num": 4, "word": "sick", "phonetic": "[sik]", "pos": "a.", "meaning": "生病的", "examples": [{"en": "I was very sick yesterday, so I stayed home from work.", "zh": "昨天我病得很重，所以我待在家里没有去上班。"}], "sub_entries": []}, {"num": 5, "word": "concerned", "phonetic": "[kənˈsɜːrnd]", "pos": "a.", "meaning": "关切的", "examples": [{"en": "I'm very concerned about Bill. He looks sick.", "zh": "我很关切比尔。他看起来像生病了。"}], "sub_entries": ["be concernedabout+人/事物", "关心某人／某事物"]}, {"num": 6, "word": "be in trouble", "phonetic": "", "pos": "短语", "meaning": "处于困难／麻烦中", "examples": [{"en": "Mary is in trouble because she cheated on a test.", "zh": "玛丽有麻烦了，因为她考试作。"}], "sub_entries": ["trouble['trabl]n.困难"]}, {"num": 7, "word": "helpful", "phonetic": "[ˈhelpfal]", "pos": "a.", "meaning": "有帮助的；乐于助人的", "examples": [{"en": "Bob's advice was veryhelpful.", "zh": "鲍勃的建议非常有帮助。"}], "sub_entries": []}, {"num": 8, "word": "dependable", "phonetic": "[drˈpendabl]", "pos": "a.", "meaning": "可信赖的", "examples": [{"en": "My car always breaks down. It is not dependable.", "zh": "我的车子老是出故障。它真是不可靠。"}], "sub_entries": []}, {"num": 9, "word": "closest", "phonetic": "[ˈklosist]", "pos": "", "meaning": "a．最亲的（为close 的最高级）", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课复习形容词最高级的用法。", "items": [{"num": 1, "title": "When I'm sad, he is the most sympathetic.", "body": ["When I'm sick, he is the most concerned. When I'm in trouble, he is the most helpful.（当我难过时，他最富有同情心了。我生病时，他最 为关切。我有困难时，他最帮我了。）以上句中划线部分均省略了person in the world，以 免与本文中第一个句子\"Mybest friend is the most thoughtful person in the world.”的划线部分重 复。"]}, {"num": 2, "title": "sympathetic 与 sympathy 的用法", "body": ["本文中的形容词 sympathetic 乃不及物动词 sympathize['sɪmpəˌθaɪz] 的衍生字，名词则为 sympathy['sɪmpəθɪ]。注意下列的相关用法：", "be sympathetic to+人 同情某人", "=sympathize with+人", "=feel sympathy for + 人", "例: Jane was sympathetic to the starving puppy,", "so she took it home and fed it.（简很同情那只挨饿的小狗，所以她就把它带回 家喂它。）Connie sympathizes with those orphans and their problems.（康妮很同情那些孤儿以及他们的问题。）I felt sympathy for the poor beggar, so 1 gave him some money.（我很同情那位穷乞写，所以我给了他一些 钱。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 60, "title_en": "The Longest River in the World", "title_zh": "世界上最长的河流", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Which is the longest river in the world?", "zh": "世界上最长的河流是哪一条？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "The Nile.", "zh": "尼罗河。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Which is the biggest ocean in the world?", "zh": "世界上最大的海洋是哪-一个？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "The Pacific Ocean.", "zh": "太平洋。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Which is the best school in the village?", "zh": "本村最好的学校是哪一所？"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "But...this is the only school in the village, sir.", "zh": "但是...·…·老师，本校是村里唯…一的…-所学校啊。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "I know.", "zh": "我知道。"}]}, "vocab": [{"num": 1, "word": "river", "phonetic": "", "pos": "n.", "meaning": "河", "examples": [], "sub_entries": []}, {"num": 2, "word": "the Nile", "phonetic": "", "pos": "名词短语", "meaning": "尼罗河（Nile[nail])", "examples": [], "sub_entries": []}, {"num": 3, "word": "ocean", "phonetic": "[ˈofan]", "pos": "n.", "meaning": "海洋", "examples": [], "sub_entries": []}, {"num": 4, "word": "the Pacific Ocean", "phonetic": "[pəˈsɪfɪk]", "pos": "专有名词", "meaning": "太平洋", "examples": [], "sub_entries": ["*表示河川、山脉、海洋等专有名词，在英文中均与", "定冠词the 并用，如：", "theYellow River", "黄河", "the Yangtze River", "长江", "the Himalayas", "喜玛拉雅山脉", "the Atlantic Ocean", "大西洋", "the South China Sea", "（中国）南海", "这些专有名词中有些经常使用，原有的River，", "Ocean 或 Sea 均可省略，如：", "the Nile River-→the Nile", "尼罗河", "theMediterraneanSea ->theMediterranean", "[medato'renian]地中海", "the Pacific Ocean → the Pacific", "太平洋"]}, {"num": 5, "word": "village", "phonetic": "[ˈvɪlɪdʒ]", "pos": "n.", "meaning": "村庄", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.Andrew thinks he's the strongest person", "the world.", "(A) on", "(B)above", "(C) in", "(D)under", "2.That is the", "restaurant in the city.", "(A) worst", "(B)most bad", "(C) baddest", "(D) most worse", "3.Jessica is the", "dancer in our class.", "(A) better", "(B)best", "(C) most good", "(D) most best", "4. This question is the", "one in the book.", "(A) easyest", "(B)most easy", "(C) easier", "(D)easiest", "5. The red book is", "the blue one，but the", "brown book is the", "(A) cheapest, cheaper", "(B） more cheap, most cheap", "(C) cheaper, cheapest", "(D）cheaper than, cheapest", "is bigger than", "(A) Pacific Ocean,Atlantic Ocean", "(B)The Pacific Ocean, Atlantic", "(C）The Pacific Ocean,the Atlantic Ocean", "(D）The.Pacific,Atlantic"], "answers": ["解答1.(C）2.(A）3.(B）4.(D）5.(D）6.(C)"]}}, {"num": 61, "title_en": "The Hare and the Turtle", "title_zh": "兔子与乌龟", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["The hare can run very fast, but the turtle can only walk slowly. One day the hare proudly challenged the turtle to a race. The hare started quickly but stopped to take a nap every now and then. The turtle walked slowly but surely. While the hare was sleeping, the turtle passed him. Finally, the turtle won the race. In the end, he was rewarded for his perseverance. We can all learn a lesson from the turtle."], "zh": ["兔子可以跑得很快，但乌龟只能慢慢地走。有一天兔子骄傲地向乌龟挑战赛跑·兔子开始时跑得很快，但它偶尔会停下来小过了兔子。乌龟终于赢了比赛。最后它因坚忍不拔的精神而获得回报。我们全都可以从乌龟那里得到一个好的教训。"]}, "dialog": null, "vocab": [{"num": 1, "word": "hare", "phonetic": "[her]", "pos": "n.", "meaning": "野兔", "examples": [], "sub_entries": []}, {"num": 2, "word": "turtle", "phonetic": "[ˈtstl]", "pos": "n.", "meaning": "乌龟", "examples": [], "sub_entries": []}, {"num": 3, "word": "walk", "phonetic": "[wok]", "pos": "vi.", "meaning": "步行，散步", "examples": [{"en": "I love walking in the forest.", "zh": "我喜欢在森林里散步。"}], "sub_entries": []}, {"num": 4, "word": "slowly", "phonetic": "[ˈslolr]", "pos": "adv.", "meaning": "缓慢地", "examples": [{"en": "Please speak slowly. My English isn't very good.", "zh": "请说慢一点。我的英文不是很好。"}], "sub_entries": []}, {"num": 5, "word": "proudly", "phonetic": "[ˈpraʊdli]", "pos": "adv.", "meaning": "骄傲地", "examples": [{"en": "Betty smiled proudly when the teacher praised her.", "zh": "当老师称赞贝蒂时，她很骄傲地微笑着。"}], "sub_entries": []}, {"num": 6, "word": "challenge + 人 + to + 比赛/活动", "phonetic": "", "pos": "短语", "meaning": "向某人挑战...", "examples": [{"en": "Bob challenged Peter to a bicycle race and lost.", "zh": "鲍勃向彼得挑战骑自行车比赛，结果输了。）·7.start[start ]vi.开始"}, {"en": "The movie will start in five minutes.", "zh": "电影再过五分钟就要开始了。"}], "sub_entries": ["challenge['tfelind3]vt.向......挑战", "race[res]n.赛跑；比赛"]}, {"num": 7, "word": "race", "phonetic": "[res]", "pos": "n.", "meaning": "赛跑；比赛", "examples": [{"en": "Bob challenged Peter to a bicycle race.", "zh": "鲍勃向彼得挑战骑自行车比赛。"}], "sub_entries": []}, {"num": 8, "word": "quickly", "phonetic": "[ˈkwɪkli]", "pos": "adv.", "meaning": "迅速地", "examples": [{"en": "You're driving too quickly; slow down.", "zh": "你开得太快了，开慢一点。"}], "sub_entries": []}, {"num": 9, "word": "take a nap", "phonetic": "", "pos": "短语", "meaning": "小睡片刻", "examples": [{"en": "I'm feeling tired. I'm going to take a nap.", "zh": "我觉得很累。我要去小睡一下。"}], "sub_entries": ["nap[nap]n.小睡"]}, {"num": 10, "word": "every now and then", "phonetic": "", "pos": "短语", "meaning": "偶尔", "examples": [{"en": "A: How often do you visit your grandmother? B: Every now and then.", "zh": "甲：你多久去看一次你的祖母？）（乙：偶尔去看一次。"}], "sub_entries": []}, {"num": 11, "word": "surely", "phonetic": "[ˈʃʊrlɪ]", "pos": "adv.", "meaning": "稳定地", "examples": [], "sub_entries": []}, {"num": 12, "word": "pass", "phonetic": "[paes]", "pos": "vt.", "meaning": "经过，通过", "examples": [{"en": "After you pass the library, turn left.", "zh": "你在经过图书馆后就向左转。"}], "sub_entries": []}, {"num": 13, "word": "won", "phonetic": "[wan]", "pos": "vt.", "meaning": "赢得（为win[win]的过去式）", "examples": [], "sub_entries": []}, {"num": 14, "word": "in the end", "phonetic": "", "pos": "短语", "meaning": "最后", "examples": [], "sub_entries": [": James always smoked cigarettes. In the end,", "he died of cancer.", "（詹姆士总是在抽烟·最后，他死于癌症。）"]}, {"num": 15, "word": "reward", "phonetic": "[rˈword]", "pos": "vt.", "meaning": "报酬，奖赏", "examples": [{"en": "The boss rewarded me for doing a good job.", "zh": "老板因我工作表现良好而奖赏我。"}], "sub_entries": []}, {"num": 16, "word": "perseverance", "phonetic": "[ˌpɜːrsəˈvɪrəns]", "pos": "n.", "meaning": "毅力", "examples": [{"en": "If you have perseverance, you can learn anything.", "zh": "如果你有毅力，你就可以学会任何一件事。"}], "sub_entries": []}, {"num": 17, "word": "learn a lesson", "phonetic": "", "pos": "短语", "meaning": "得到一个教训", "examples": [{"en": "I learned a lesson from my older brother's failures.", "zh": "我从我哥哥的失败中学到教训。"}], "sub_entries": ["learn[l3n.]vt.学习", "lesson['lesn]n.教训"]}], "grammar": {"intro": "本课主要介绍副词的功能及用法。", "items": [{"num": 1, "title": "One day the hare proudly challenged the turtle to a race.", "body": ["（有一天兔子骄傲地向乌龟挑战赛跑。）", "oneday是表示时间的状语，可指过去或将来的某一", "天。换言之，one day可使用于过去时或将来时的句", "子中。", "例：One day I had dinner with her at that", "restaurant.（过去时）", "（有一天我曾和她在那家餐厅吃晚饭。）", "One day the little boy will be a great man.", "（将来时）", "（有一天这个小男孩会成为伟人。）", "注意：", "a.someday", "将来有一天（用于将来时）", "例： Someday the little boy will be a great", "man.", "=One day the little boy will be a great", "man.", "（有一天这个小男孩会成为伟人。）", "b.theotherday", "前几天（用于过去时）", "例: The other day I met him at the train station.", "（前几天我曾在火车站遇见他。）", "以上这些副词或状语可置于句首或句尾。故上列各例", "句均可改写为：", "I had dinner with her at that restaurant one day.", "The little boy will be a great man one day.", "The little boy will be a great man someday.", "I met him at the train station the other day."]}, {"num": 2, "title": "In the end, he was rewarded for his perseverance.", "body": ["（最后它因坚韧不拔的精神而获得回报。）", "in the end", "到最后", "=at last", "in the beginning", "起初", "=at first", "例： In the beginning of the race I was energetic,", "but in the end, I was exhausted.", "（比赛开始时我精力充沛，但到最后，我筋疲力", "尽。）"]}, {"num": 3, "title": "本文中的诸多动词均有副词修饰。如：", "body": ["本文中的诸多动词均有副词修饰。如：", "a. The hare can run very fast, but the turtle can only walk slowly.", "b. The turtle walked slowly but surely.", "一般而言，副词有下列几个主要功能：", "a. 修饰形容词，此时置于该形容词之前：", "例：She is very [adv.] beautiful [adj.].（她很美。）", "b. 修饰副词，此时置于该副词之前：", "例：He worked quite [adv.] hard [adv.].（他工作相当努力。）", "c. 修饰动词，此时多置于该动词之后：", "例：He walked [vi.] slowly [adv.].（他走得很慢。）", "John speaks [vt.] English well [adv.].（约翰英语说得很好。）", "注意：very虽是副词，却无法修饰动词，只能修饰形容词或副词；但very much却可修饰动词，使用时置于句尾。", "例：He is very [adv.] polite [adj.].（他很有礼貌。）", "He speaks Japanese very [adv.] well [adv.].（他日语说得很好。）", "I very like him. (×)", "→ I like [vt.] him very much [adv.]. (○)（我很喜欢他。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}, {"num": 3, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 62, "title_en": "Practice Makes Perfect", "title_zh": "熟能生巧", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Can you help me gift-wrap this, please?", "zh": "请你帮我把这个东西用礼品纸包起来好吗？"}, {"speaker_en": "Salesgirl", "speaker_zh": "女店员", "en": "Sure.(after a while)", "zh": "好啊。（过了一会儿）"}, {"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Wow! You did that beautifully.", "zh": "哇！你包得好美啊。"}, {"speaker_en": "Salesgirl", "speaker_zh": "女店员", "en": "Well, I practice daily.", "zh": "嗯，我每天都在练习嘛。"}, {"speaker_en": "Customer", "speaker_zh": "顾客", "en": "Practice makes perfect, right?", "zh": "熟能生巧，对吗？"}, {"speaker_en": "Salesgirl", "speaker_zh": "女店员", "en": "Certainly!", "zh": "那是当然的啰！"}]}, "vocab": [{"num": 1, "word": "Can you help me gift-wrap this, please?", "phonetic": "", "pos": "日常口语", "meaning": "请你帮我把这个东西用礼品纸包起来好吗？", "examples": [{"en": "My wife and I gift-wrapped our children's Christmas gifts last night. b. Can you help me gift-wrap this, please? =Can you help me to gift-wrap this, please?", "zh": "昨晚我和太太把要给孩子们的圣诞礼物包装起来。）本句help为及物动词，之后接“人”为宾语，可再接虚词to引导的动词不定式作宾语补足语，但to往往予以省略。即：help+人+to+动词原形=help+人+动词原形"}, {"en": "I helped him to write the letter. =I helped him write the letter.", "zh": "我帮他写这封信。"}], "sub_entries": ["a.gift-wrap['gift.rap]vt.将.….…包装成礼品"]}, {"num": 2, "word": "wow", "phonetic": "[wau]", "pos": "int.", "meaning": "哇！", "examples": [], "sub_entries": []}, {"num": 3, "word": "practice", "phonetic": "[ˈpraektis]", "pos": "n.", "meaning": "&vi.练习]", "examples": [], "sub_entries": []}, {"num": 4, "word": "daily", "phonetic": "[ˈdeɪli]", "pos": "adv.", "meaning": "每天(=every day)", "examples": [{"en": "Dave jogs daily at 6:30 in the morning.", "zh": "大卫每天早上六点半都去慢跑。"}], "sub_entries": []}, {"num": 5, "word": "Practice", "phonetic": "", "pos": "", "meaning": "makes perfect．熟能生巧。（谚语）", "examples": [], "sub_entries": ["perfect['p3fikt]a.完美的"]}, {"num": 6, "word": "certainly", "phonetic": "[ˈsɜːrtnli]", "pos": "adv.", "meaning": "当然(=sure)", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. The other day I", "a very good movie.", "(A) will see", "(B) saw", "(C) watch (D) see", "2. Roger believes that someday he", "an", "English professor.", "(A) will be", "(B)will", "(C) was", "(D) is", "3. Steve", "fast.", "(A) very read", "(B) reading very", "(C) read much", "(D) reads very", "4. My father works slowly and", "(A) very happy", "(B)happy", "(C) happily", "(D) is happily", "5. In the beginning, Chris was very sad;", "in", "the end, he was happy.", "(A) so (B) but (C) moreover (D) as a result", "6. He helped me", "the problem.", "(A)handle", "(B) handled", "(C) handling", "(D) to handled", "()9 （)（)（)（)（)1"], "answers": []}}, {"num": 63, "title_en": "Saving a Drowning Boy", "title_zh": "救难记", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Ray was walking on the beach one summer day when he heard a little boy shout, \"Help! Help!\" The boy was drowning. Without thinking, Ray dove into the water. Soon he was swimming back to shore with the boy. Crowds of people were watching eagerly. After a while the boy was breathing again. Then the boy sat up and said to Ray, \"You are my hero.\""], "zh": ["某个夏日雷正在海滩上散步，这时他听到一个小男孩大叫：“救命啊！救命啊！”这个男孩快要淹死了。雷不加思索地就跳进了水里。不久他便带着小男孩游回岸上。成群的人们正焦急地注视着。过了一会儿这个男孩又开始呼吸了·接着这个男孩坐了起来，对雷说：“你是我的英雄。”"]}, "dialog": null, "vocab": [{"num": 1, "word": "save", "phonetic": "[sev]", "pos": "vt.", "meaning": "拯救", "examples": [{"en": "The fireman saved the child from the burning building.", "zh": "那个消防队员将这个小孩从起火的大楼中救出。"}], "sub_entries": []}, {"num": 2, "word": "drowning", "phonetic": "[ˈdraunin]", "pos": "a.", "meaning": "激水的", "examples": [{"en": "Last year, ten people drowned in this lake.", "zh": "去年有十个人淹死在这湖里。"}], "sub_entries": ["drown[draun ]vi.溺水"]}, {"num": 3, "word": "walk", "phonetic": "[wok]", "pos": "vi.", "meaning": "散步", "examples": [{"en": "I love walking through the city at night.", "zh": "我喜欢晚上在城市里散步。"}], "sub_entries": []}, {"num": 4, "word": "on the beach", "phonetic": "", "pos": "短语", "meaning": "在海滩上", "examples": [], "sub_entries": ["beach[bitf]n.海滩，海边"]}, {"num": 5, "word": "shout", "phonetic": "[ʃaʊt]", "pos": "vt.", "meaning": "&vi.喊叫，大叫", "examples": [{"en": "The teacher entered the noisy classroom and shouted,\"Shut up!\" The angry mother shouted at her son.", "zh": "老师走进闹哄哄的教室大叫：“闭嘴！”）（那愤怒的母亲对着她儿子大叫。"}], "sub_entries": ["shout at+人）", "对着某人大叫"]}, {"num": 6, "word": "help", "phonetic": "[help]", "pos": "vi.", "meaning": "救命", "examples": [{"en": "A: Help! There's a cockroach in my room! B: Well, just step on it and kill it.", "zh": "甲：救命啊！我的房间里有只蟑螂！）（乙：，把它踩死就好了。"}], "sub_entries": []}, {"num": 7, "word": "dive", "phonetic": "[daiv]", "pos": "vi.", "meaning": "跳水", "examples": [{"en": "I can swim, but I'm afraid to dive.", "zh": "我会游泳，但我不敢跳水。"}], "sub_entries": ["动词三态：dive，dove/dived，dove/dived。"]}, {"num": 8, "word": "shore", "phonetic": "[∫or]", "pos": "n.", "meaning": "（海）岸", "examples": [{"en": "There is a place by the shore that is great for fish ing.", "zh": "岸边有一处钓鱼的好地方。"}], "sub_entries": []}, {"num": 9, "word": "crowd", "phonetic": "[kraud]", "pos": "n.", "meaning": "群", "examples": [{"en": "Crowds of fans waited at the airport for the singer to arrive.", "zh": "成群的歌迷在机场等候该歌手抵达。"}], "sub_entries": ["crowds of...", "成群的…….….", "a crowd of...", "-一群的…….…"]}, {"num": 10, "word": "watch", "phonetic": "[watf]", "pos": "vi.", "meaning": "&vt.注视，看", "examples": [{"en": "I seldom watch TV.", "zh": "我很少看电视。"}], "sub_entries": []}, {"num": 11, "word": "eagerly", "phonetic": "[ˈiːɡərli]", "pos": "adv.", "meaning": "焦急地；渴望地", "examples": [{"en": "The children eagerly jumped into the swimming pool.", "zh": "那些孩子迫不及待地跳人游泳池里。"}], "sub_entries": []}, {"num": 12, "word": "after a while", "phonetic": "", "pos": "短语", "meaning": "一会儿之后（介词短语，作副词）", "examples": [{"en": "A: The child is crying again. B: Don't worry. After a while he will stop.", "zh": "甲：那孩子又哭了。）（乙：别担心。过一会儿他就停了。"}], "sub_entries": ["while[hwal／wail]n.段时间"]}, {"num": 13, "word": "breathe", "phonetic": "[brio]", "pos": "vi.", "meaning": "&vt.呼吸", "examples": [{"en": "There's too much cigarette smoke in here;I can't breathe.", "zh": "这里的烟味太重了，我无法呼吸。"}], "sub_entries": ["breathe the fresh air", "呼吸新鲜空气"]}, {"num": 14, "word": "hero", "phonetic": "[ˈhiro]", "pos": "n.", "meaning": "英雄", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课强调过去进行时的型态及其功能。", "items": [{"num": 1, "title": "Ray was walking on the beach...", "body": ["（雷正在海滩上散步····.(The boy was drowning.（这个男孩快要淹死了。）以上两句的划线部分均为过去进行时。过去进行时与 现在进行时的型态与功能大致相同，只不过，过去进 行时强调过去进行的状态。", "a. 型态", "主语+was/were+现在分词: I was sleeping at five.（五点钟时我正在睡觉。）They were watching TV when I called.（我打电话时，他们正在看电视。）", "b. 功能", "1）表示过去某个时刻正在发生的动作。", "例：What was he doing then?（他那时正在做什么？）", "When I walked in, he was eating.（我进来时，他正在吃东西。）", "2）leave（离开）、come（来）、go（去）等表 示“来”或“去”的动词可用于过去进行时的 句中，表示过去即将发生的事情。", "例: He told me that he was leaving soon.", "=Hetold me thathrewould leave soon.", "=He told me that he would be leaving soon.（他告诉我他很快就要离开了。）", "He said that he was coming this afternoon.", "=He said that he would come this afternoon.", "=He said that he would be coming this afternoon.（他说他今天下午要来。）本课阅读原文中\"Theboywas drowning.\"亦属此 用法。", "比较：", "The boy was drowning.（这男孩快要淹死了。）The boy was drowned.（这男孩已经淹死了。）"]}, {"num": 2, "title": "Ray was walking on the beach one summer day when he heard a little boy shout, \"Help! Help!\"", "body": ["（某个夏日雷正在海滩上散步，这时他听到-个小男 孩大叫：“救命啊！救命啊！”）", "a. 本句使用了下列句型：", "主语+was/were+现在分词+when 所引导的过去 时状语从句", "...正在….…这时...就.…···: I was having dinner when he came.（我正在吃晚饭，这时他就来了。）I was taking a shower when the phone rang.（我正在淋浴，这时电话铃就响了。）", "b....he heard a little boy shout, \"Help! Help!\"", "（......他听到一个小男孩大叫：“救命啊！救命啊!\"）", "注意：", "本句中，及物动词heard（听到）接了宾语a littleboy，另接动词原形shout作宾语补足语。英 语中，表“看”（如 see）、“听”（如hear）“感觉”（如feel）等三類及物动，接了宾鼎之 後，可用動原形、現在分或過去分词作宾語补 足語。兹分頂明如下：", "1）以动词原形作补足语 旨在强调确有事情发生。", "例: I saw him steal my money.（我看到他偷了我的钱。）", "I heard him sing.（我听到他唱歌。）I felt him touch my hand.（我感觉他碰了我的手。）\"...he heard a little boy shout...\"即属此用 法。", "2）以现在分词作补足语 旨在强调事情正在发生。", "例： I saw him stealing my money.（我看到他正在偷我的钱。）", "I heard him singing.（我听到他正在唱歌。）I felt him touching my hand.（我感觉他正在碰我的手。）", "3）以过去分词作补足语 旨在强调被动语态。", "例：I saw him punished.（我看到他被处罚了。）", "I heard him dragged away.（我听到他被拖走的声音。）I felt my hand lifted.（我感觉我的手被抬了起来。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 64, "title_en": "Dan's a Good Swimmer", "title_zh": "丹很会游泳", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Lucy", "speaker_zh": "露西", "en": "Dan's a good swimmer, isn't he?", "zh": "丹很会游泳，是不是？"}, {"speaker_en": "Lewis", "speaker_zh": "刘易斯", "en": "Yes. In fact, he's a lifeguard.", "zh": "是啊。事实上'他是个救生员。"}, {"speaker_en": "Lucy", "speaker_zh": "露西", "en": "Wow! Can he teach me the butterfly and the backstroke?", "zh": "哇！他能教我蝶泳和仰泳吗？"}, {"speaker_en": "Lewis", "speaker_zh": "刘易斯", "en": "Yes. He can also teach you the free style and the breaststroke.", "zh": "能。他还能教你自由式和蛙式。"}, {"speaker_en": "Lucy", "speaker_zh": "露西", "en": "Great!", "zh": "太棒了！"}]}, "vocab": [{"num": 1, "word": "swimmer", "phonetic": "[ˈswima]", "pos": "n.", "meaning": "游泳者", "examples": [], "sub_entries": []}, {"num": 2, "word": "lifeguard", "phonetic": "[laif.ɡard]", "pos": "n.", "meaning": "救生员", "examples": [], "sub_entries": []}, {"num": 3, "word": "butterfly", "phonetic": "[ˈbato.flar]", "pos": "n.", "meaning": "本字原指“蝴蝶”，此处指", "examples": [], "sub_entries": ["“蝶泳”（游泳）"]}, {"num": 4, "word": "backstroke", "phonetic": "[ˈbækstroʊk]", "pos": "n.", "meaning": "仰泳（游泳）", "examples": [], "sub_entries": []}, {"num": 5, "word": "free style", "phonetic": "[ˈfri stail]", "pos": "n.", "meaning": "自由式（游泳）", "examples": [], "sub_entries": []}, {"num": 6, "word": "breaststroke", "phonetic": "[ˈbreststrok]", "pos": "n.", "meaning": "蛙式（游泳）", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.Sally and Mike", "comicbookslastnight.", "(A) was seeing", "(B) was reading", "(C) were reading", "(D) were seeing", "2.1", "on the computer when my wife called", "me on the phone.", "(A) were typing", "(B) typed", "(C) was typed", "(D) was typing", "3.1", "a child", "off his bicycle.", "(A) see, fell", "(B) saw, fall", "(C) saw, fell", "(D) see, fall", "4. The students were talking when the teacher", "into the room.", "(A) coming (B) comes (C) came (D) comed", "5. I thought you", "soon.", "(A) leaving", "(B) would leaving", "(C) would be leave", "(D) would be leaving", "6. She isn't as beautiful as Mary,", "？", "(A) is she", "(B)isn't she", "(C) is he", "(D) does she"], "answers": ["解答>1.(C）2.(D）3.(B）4.(C）5.(D）6.(A)"]}}, {"num": 65, "title_en": "The Fortune-teller", "title_zh": "算命师", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My friend Mike is a fortune-teller. He often tells me many things about my future. First, I will become a father next year. Then, 1 will get a promotion and earn a lot of money. Two years later, I will buy a new car. Soon after that, l will be able to afford a new house. I'm not superstitious, but I hope he's right."], "zh": ["我的朋友迈克是个算命师。他经常会告诉我许多有关我前途的事。首先，我明年就要当爸爸了·然后，我会获得提升并且挣大钱。两年后，我会买部新车。之后没多久，我就会有能力买幢新房子。我并不迷信，但我希望他说的是真的。"]}, "dialog": null, "vocab": [{"num": 1, "word": "fortune-teller", "phonetic": "[ˈfortfon.telo]", "pos": "n.", "meaning": "算命师，算命先生", "examples": [], "sub_entries": []}, {"num": 2, "word": "tell", "phonetic": "[tel]", "pos": "vt.", "meaning": "告诉", "examples": [], "sub_entries": []}, {"num": 3, "word": "about", "phonetic": "[aˈbaut]", "pos": "prep.", "meaning": "有关", "examples": [{"en": "Chris told me about a dream he had last night.", "zh": "克里斯告诉我有关他昨晚做的梦。"}], "sub_entries": []}, {"num": 4, "word": "future", "phonetic": "[ˈfjutfa]", "pos": "n.", "meaning": "前途，未来", "examples": [{"en": "What will you do in the future?", "zh": "你将来想做什么？"}], "sub_entries": []}, {"num": 5, "word": "become", "phonetic": "[brˈkam]", "pos": "vt.", "meaning": "成为", "examples": [{"en": "Eventually, Sally and Susie became good friends.", "zh": "萨莉和苏西终成好友。"}], "sub_entries": []}, {"num": 6, "word": "get a promotion", "phonetic": "", "pos": "短语", "meaning": "（职位上的）提升", "examples": [{"en": "After this project Ted and Carl will get a promotion.", "zh": "这项计划完成后，特德和卡尔将会获得提升。"}], "sub_entries": ["promotion[ pra'mofan ] n.提升"]}, {"num": 7, "word": "earn", "phonetic": "[ɜːrn]", "pos": "vt.", "meaning": "挣（钱）", "examples": [{"en": "My wife earns more money than I.", "zh": "我太太挣的钱比我多。"}], "sub_entries": []}, {"num": 8, "word": "later", "phonetic": "[leto]", "pos": "adv.", "meaning": "稍后，后来", "examples": [{"en": "I started to attend university when I was eighteen. Four years later I graduated.", "zh": "我18岁时开始念大学。四年后我毕业了。"}], "sub_entries": ["此单词使用时，通常置于时间名词之后，如：", "five years later", "五年后", "two days later", "两天后"]}, {"num": 9, "word": "be", "phonetic": "", "pos": "", "meaning": "able to+动词原形", "examples": [{"en": "I'm sorry. I won't be able to go to your birthday party.", "zh": "很抱歉，我无法去参加你的生日宴会。"}], "sub_entries": ["能够….·….", "=can+动词原形"]}, {"num": 10, "word": "afford", "phonetic": "[aˈford]", "pos": "vt.", "meaning": "买得起", "examples": [{"en": "I can't afford that shirt. It's too expensive.", "zh": "我买不起那件衬衫，它太贵了。"}], "sub_entries": []}, {"num": 11, "word": "superstitious", "phonetic": "[supaˈstifes]", "pos": "a.", "meaning": "迷信的", "examples": [{"en": "A: If you break a mirror, you will have seven years of bad luck. B: Oh, you're just superstitious.", "zh": "甲：如果你打破镜子，你将会有连续七年的恶运。）（乙：哦，你真是迷信。"}], "sub_entries": []}], "grammar": {"intro": "本课主要介绍一般将来时的型态及用法。", "items": [{"num": 1, "title": "First, I will become a father next year.", "body": ["（首先，我明年就要当爸爸了。）Then, I will get a promotion and earn a lot of money.（然后，我会获得提升并且挣大钱。）以上两句均为一般将来时的句子结构。兹就这种句子 结构及其使用时机叙述如下：", "a. 句子结构", "主语+will/shall+动词原形", "例：He will come this afternoon.（他今天下午会来。）", "Wewill/shall call on our teacher tomorrow.（我们明天会去拜访我们的老师。）英式的习惯用法为：主语若为第一人称代词（I、we）时，之后使用shall，其余第二人称或第三人称 的主语一律使用will，但美式用法则为不论第几人 称的主语一律使用will。即：", "英式：I shall do it.（我将会做这件事。）We shall do it.（我们将会做这件事。）You will do it.（你／你们将会做这件 事。）He will do it.（他将会做这件事。）She will do it.（她将会做这件事。）It will do it.（它将会做这件事。）Theywill doit.（他们将会做这件事。）美式：I will do it.（我将会做这件事。）We will do it.（我们将会做这件事。）Youwill doit．（你／你们将会做这件 事。）由于美式的用法较英式统一，因此现今的趋势多偏 向美式用法·b．一般将来时使用的时机：", "一般将来时表示未来会发生的动作或状态。这个动 作或状态可能会在最近或很久以后才会发生，均须 借助动词will来表现·这个will就相当中文的“将要”或“会”之意。", "例：中文：我十年后会娶你。", "英文: I will marry you ten years later. 中文：他很快就会来。英文：He will come soon.", "c. 其他注意事项：", "1）will与作主语的代词并用时，可采下列的缩写 形：", "I will -→ I'll He will →He'll They will → They'll", "2）will与not并用时，可缩写成won't[won't]", "例：Iwill not→Iwon't"]}, {"num": 2, "title": "Soon after that, I will be able to afford a new house.", "body": ["（之后没多久，我就有能力买幢新房子。）", "a. afford是及物动词，表示“买得起\"”、“负担得 起”，之后可用名词或虚词to引导的不定式短语 作其宾语。而afford之前一定要有助动词can·", "例：I afford that car.（x）", "→I can afford that car.(○)（我买得起那部车子。）I don't afford totakethe trip with you.（×）", "→I can't afford to take the trip withyou.(○)（我没有钱和你一起去旅游。）", "b. afford 若使用于一般将来时，理应说成：", "I will can afford that car.（×)因will与can均为助动词不能并存，此时应将 can改成beableto，即成：", "I will be able to afford that car someday.(○)（有一天我会买得起那部车子。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 66, "title_en": "Will It Leave on Time?", "title_zh": "它会准时开吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Girl", "speaker_zh": "女孩", "en": "Excuse me. When will the next train leave?", "zh": "抱·请问下一班火车何时开？"}, {"speaker_en": "Man", "speaker_zh": "男士", "en": "In ten minutes.", "zh": "十分钟后。"}, {"speaker_en": "Girl", "speaker_zh": "女孩", "en": "Willit leave on time?", "zh": "它会准时开吗？"}, {"speaker_en": "Man", "speaker_zh": "男士", "en": "It always does.", "zh": "它总是很准时的。"}, {"speaker_en": "Girl", "speaker_zh": "女孩", "en": "Thank you.", "zh": "谢谢你。"}]}, "vocab": [{"num": 1, "word": "in ten minutes", "phonetic": "", "pos": "短语", "meaning": "十分钟后", "examples": [{"en": "The next train will leave in ten minutes.", "zh": "下班火车十分钟后会离开。）in+一段时间一段时间之后（用于-一般将来时）=一段时间+later"}, {"en": "I'll be there Jin five minutes. fiveminuteslater. I'llfinish it in two hours. Itwo hours later.", "zh": "我五分钟后会到那儿。）（我两个小时后会做完这件事。"}], "sub_entries": []}, {"num": 2, "word": "on time", "phonetic": "", "pos": "短语", "meaning": "准时", "examples": [{"en": "Carl always comes to work on time.", "zh": "卡尔总是准时来上班。"}], "sub_entries": []}, {"num": 3, "word": "It always leaves on time.", "phonetic": "", "pos": "日常口语", "meaning": "它总是很准时。", "examples": [{"en": "A:You went to Nanjing the other day, didn't you? B: Yes, I did. Nanjing the other day 。", "zh": "甲：你前几天到南京去了，对不对？）（乙：对，我是到南京去了。）*此处did代替前面提过的wentto"}], "sub_entries": ["=It always leaves on time.", "此处does是助动词，代替前句出现过的相同动词及", "其他词类。"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Three years later, I", "to America.", "(A) will go (B) go (C) will going (D) will", "2.Peter will be here", "(A) after ten minute (B) after ten minutes", "(C) in ten minute", "(D)in ten minutes", "3. I know the party", "be a success.", "(A） is", "(B）will", "(C) can will（", "(D）was", "4. 1 hate Bobby. I", "go to dinner with him.", "(A)will", "(B)won't", "(C) not", "(D)willn't", "5.", "you go to a movie with me tonight?", "(A） Want", "(B)", "Have (C) Does (D) Will", "6. Class will", "(A)on five minutes", "(B) starting in five minutes", "(C) start in ten minutes", "(D) start on ten minutes"], "answers": ["解答1.(A）2.(D）3.(B）4(B）5.(D）6.(C)"]}}, {"num": 67, "title_en": "Getting Married", "title_zh": "结婚", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My girlfriend and l are going to get married this year. We are going to have a big wedding party. All our friends and relatives are going to come. We are going to have a traditional wedding. After the wedding we are going to live with my parents. We are going to be one big happy family."], "zh": ["我和女友今年将结婚。我们将举行盛大的婚宴。我们所有的亲朋好友都会来参加。我们将要举行传统的婚礼。婚礼后我们要和我的父母亲一起住。我们将成为一个快乐的大家庭。"]}, "dialog": null, "vocab": [{"num": 1, "word": "girlfriend", "phonetic": "[ˈɡal.frend]", "pos": "n.", "meaning": "女朋友", "examples": [], "sub_entries": ["boyfriend['boifrend]n.男朋友"]}, {"num": 2, "word": "get married", "phonetic": "", "pos": "短语", "meaning": "结婚", "examples": [{"en": "Susie and Roger are getting married next summer.", "zh": "苏西和罗杰将在明年夏天结婚。"}], "sub_entries": ["married['merid]a.结婚的"]}, {"num": 3, "word": "wedding party", "phonetic": "[ˈwediy porti]", "pos": "n.", "meaning": "婚宴", "examples": [], "sub_entries": []}, {"num": 4, "word": "relative", "phonetic": "[ˈrelativ]", "pos": "n.", "meaning": "亲戚", "examples": [], "sub_entries": []}, {"num": 5, "word": "traditional", "phonetic": "[traˈdifanl]", "pos": "a.", "meaning": "传统的", "examples": [{"en": "It's traditional in America to eat turkey on Christmas Day.", "zh": "在美国圣诞节时吃火鸡是项传统。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍\"begoingto+动词原形”作一般将来时的用 法。", "items": [{"num": 1, "title": "My girlfriend and I are going to get married this year.", "body": ["（我和女友今年将结婚。）", "We are going to have a big wedding party.（我们将举行盛大的婚宴。）以上两句为一般将来时的句子结构，其中aregoing to就等于will。即：", "主语+will+动词原形", "=主语+be going to+动词原形", "例：I will leave soon.", "=I am going to leave soon.（我很快就会离开。）", "He will be there in five minutes.", "=He is going to be there in five minutes.（他五分钟后就会到那儿。）", "注意：", "will与begoing to虽然意思相同，可相互取代，不 过begoingto多指短期内会发生的动作或状态，而 will则可指短期内或长期以后会发生的动作或状态。短期内：", "例: He is going to climb mountains with us this weekend.", "=He will climb mountains with us this weekend.（这个周末他会跟我们爬山去。）长期以后：", "例: He is going to marry the girl ten years later.（劣）", "→He will marry the girl ten years later.(佳）（十年后他会娶那个女孩。）"]}, {"num": 2, "title": "will 与 be going to 的使用时机区别", "body": ["句中若有表示某种条件下会产生某种现象时，宜使用 will，而非 be going to。", "例：He is_going to lose everything without your", "help.（劣）->He will lose everything without your help.（佳）（若没有你的帮忙，他会失去-切。）I am going to get angry if you don't come.（劣）-> I will get angry if you don't come.（佳）（你若不来，我会生气的。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 68, "title_en": "Are You Going to Come?", "title_zh": "你会来吗？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Candy", "speaker_zh": "凯蒂", "en": "Are you going to come to my wedding?", "zh": "你会来参加我的婚礼吗？"}, {"speaker_en": "Joe", "speaker_zh": "乔", "en": "Of course.", "zh": "当然会。"}, {"speaker_en": "Candy", "speaker_zh": "凯蒂", "en": "Good. Are you going to bring your girlfriend?", "zh": "太好了。你会带你女朋友一起来吗？"}, {"speaker_en": "Joe", "speaker_zh": "乔", "en": "Yes. She likes weddings.", "zh": "会。她很喜欢参加婚礼。"}, {"speaker_en": "Candy", "speaker_zh": "凯蒂", "en": "So when are you going to get married?", "zh": "那么你们什么时候结婚呢？"}, {"speaker_en": "Joe", "speaker_zh": "乔", "en": "We haven't decided yet.", "zh": "我们尚未决定。"}]}, "vocab": [{"num": 1, "word": "decide", "phonetic": "[dɪˈsaɪd]", "pos": "vt. & vi.", "meaning": "决定", "examples": [{"en": "Have you decided where you will go for your vacation?", "zh": "你已经决定要去哪里度假了吗？"}, {"en": "Let me know what you have decided by tomorrow.", "zh": "明天以前让我知道你的决定。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1.If you study, you", "well on the test.", "(A)will do", "(B) going to", "(C) will", "(D) will doing", "2. They", "have a party tonight.", "(A) going to", "(B) are will", "(C) are going", "(D) are going to", "3.Mary is very sick. She", "attend class today.", "(A) going to", "(B) is going to", "(C) isn't going to", "(D) isn't", "4. Paul should come today, but maybe he", "(A)will", "(B)won't", "(C) wilin't", "(D) is going to", "5.What time", "they arrive?", "(A) going to", "(B)won't(C)are", "(D) will"], "answers": ["解答>1.(A）2.(D）3.(C）4.(B）5.(D)"]}}, {"num": 69, "title_en": "Running a Bookstore", "title_zh": "经营书店", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Tom will be retiring next year. He will be opening a small bookstore. His wife will be helping him run the store. It will be a small family business, so they won't be needing too much money. He won't be making a lot of money, but it'll be enough."], "zh": ["汤姆明年就要退休了。他将开一家小书店。他的太太会帮他经营这家店。这将是一个小型的家庭事业，所以他们并不需要太多资金。他将不会挣很多钱，但那样就够用了。"]}, "dialog": null, "vocab": [{"num": 1, "word": "retire", "phonetic": "[rɪˈtaɪr]", "pos": "vi.", "meaning": "退休", "examples": [{"en": "When I'm sixty, I'll retire.", "zh": "60岁时，我将要退休。"}], "sub_entries": []}, {"num": 2, "word": "open", "phonetic": "[ˈoʊpən]", "pos": "vt.", "meaning": "开业", "examples": [{"en": "Peter opened a small English class for beginners.", "zh": "彼得为初学者开了一个小型的英文班。"}], "sub_entries": []}, {"num": 3, "word": "bookstore", "phonetic": "[ˈbʊkstɔːr]", "pos": "n.", "meaning": "书店", "examples": [], "sub_entries": []}, {"num": 4, "word": "help", "phonetic": "[help]", "pos": "vt.", "meaning": "帮助", "examples": [{"en": "Help your brother wash the car.", "zh": "去帮忙你哥哥洗车。"}], "sub_entries": []}, {"num": 5, "word": "run", "phonetic": "[rʌn]", "pos": "vt.", "meaning": "经营", "examples": [{"en": "It's my dream to run my own business someday.", "zh": "我的梦想是将来有一天自己创业。"}], "sub_entries": []}, {"num": 6, "word": "family business", "phonetic": "[ˈfæməli ˈbɪznɪs]", "pos": "n.", "meaning": "家庭事业", "examples": [], "sub_entries": []}, {"num": 7, "word": "need", "phonetic": "[nid]", "pos": "vt.", "meaning": "需要", "examples": [{"en": "The poor boy needs some clothes.", "zh": "那可怜的男孩需要一些衣服。"}], "sub_entries": []}, {"num": 8, "word": "make a lot of money", "phonetic": "", "pos": "短语", "meaning": "挣很多钱", "examples": [{"en": "Bob got a new job in a big bank and is making a lot of money.", "zh": "鲍勃在一家大银行找到新工作，并且正在挣大钱。"}], "sub_entries": ["= earn a lot of money", "make [mek] vt. 挣（钱）"]}], "grammar": {"intro": "本课介绍将来进行时的型态及用法。\nTom will be retiring next year.（汤姆明年将要退休。）\nHe will be opening a small bookstore.（他将开一家小书店。）\n以上两句使用了将来进行时。兹就其句子结构及使用时机叙述如下：", "items": [{"num": 1, "title": "句子结构：主语 + will be + 现在分词", "body": ["例：He will be leaving soon.（他很快就会离开。）", "We will be coming tomorrow.（我们明天会来。）"]}, {"num": 2, "title": "使用时机：", "body": ["a. 表示短期内即将发生的动作：", "此时 will be 译成“将要”或“将会”。将来进行时亦可用一般将来时（will + 动词原形 或 be going to + 动词原形）来取代；只不过是将来进行时更强调短期内即将发生的动作。", "例：He will be visiting us tomorrow.", "= He is going to visit us tomorrow.", "= He will visit us tomorrow.（他明天会来看我们。）", "b. 表示在将来某一时刻将会进行的动作：", "此时宜使用将来进行时，will be 译成“会在”。", "例：I'll be watching TV this time tomorrow.（我明天这个时候会在看电视。）", "He'll be studying in the library this afternoon.（今天下午他会在图书馆看书。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 70, "title_en": "When Will You Be Moving?", "title_zh": "你什么时候搬家？", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "When will you be moving?", "zh": "你什么时候搬家？"}, {"speaker_en": "Chuck", "speaker_zh": "查克", "en": "Next week.", "zh": "下星期。"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "When will we be seeing you again?", "zh": "我们什么时候会再见到你呢？"}, {"speaker_en": "Chuck", "speaker_zh": "查克", "en": "Maybe next year.", "zh": "也许明年吧。"}, {"speaker_en": "Tina", "speaker_zh": "蒂娜", "en": "Don't forget to write.", "zh": "别忘了写信啊。"}, {"speaker_en": "Chuck", "speaker_zh": "查克", "en": "I won't. Goodbye. Tina.", "zh": "我不会忘记的·再见了，蒂娜。"}]}, "vocab": [{"num": 1, "word": "move", "phonetic": "[muv]", "pos": "vi.", "meaning": "搬家（=move house，非 move", "examples": [{"en": "Irene moved back to the country to be with her family. The Lee family is moving house.", "zh": "艾琳搬回乡下和她的家人一起住。）（李家正在搬家。"}], "sub_entries": ["the house)"]}, {"num": 2, "word": "maybe", "phonetic": "[ˈmeɪbi]", "pos": "adv.", "meaning": "也许", "examples": [{"en": "May be he'll be coming tomorrow.(×) - Maybe he'll be coming tomorrow. (○) = Perhaps he'll be coming tomorrow. May be you are right. (×) → Maybe you are right. (○) =Perhaps you are right. You maybe right. (×) → You may be right. (○)", "zh": "也许他明天会来。）（也许你是对的。）（你也许是对的。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.", "we'll be playing basketball tomorrow.", "(A) Maybe", "(B)May be", "(C) Might", "(D) Perhaps be", "2. She", "thewinnerof therace.", "(A)maybe", "(B) may be", "(C) might", "(D) perhaps be", "3.Bobby", "his homework tonight.", "(A) will be", "(B) is going to", "(C) doing", "(D) will be doing", "4.Paul", "totravel this summer.", "(A) is going", "(B)will be", "(C) will", "(D) will being", "5.1", "tonight.", "(A）not will work", "(B)will work not", "(C) will to not work", "Som 2q 1.uom (a)", "6.", "Sally and Joe are girlfriend and boyfriend.", "(A) Could be", "(B) Perhaps be", "(C) Perhaps", "(D) May be"], "answers": ["解答>1.(A）2.(B）3.(D）4.(A）5.(D）6.(C)"]}}, {"num": 71, "title_en": "Working Hard", "title_zh": "努力学习", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["My best friend Billy and I decided to learn English last year. We promised each other to work hard. We never failed to attend class. Billy always remembered to do his homework. I never forgot to do mine, either. Our English is pretty good now. It only proves that there's no gain without pain."], "zh": ["我和挚友比利去年决心要学英文。我们彼此允诺要努力学习。我们从不缺课。比利总是会记得做功课。而我也从未忘记做自己的功课。我们的英文现在很不错了·这就证明了一分耕耘，一分收获的道理。"]}, "dialog": null, "vocab": [{"num": 1, "word": "promise", "phonetic": "[ˈpramis]", "pos": "vt.", "meaning": "允诺，答应", "examples": [{"en": "I promised my teacher to do my homework.", "zh": "我答应老师会做功课。"}], "sub_entries": ["promise+人+to+动词原形", "尤诺某人做·····"]}, {"num": 2, "word": "each other", "phonetic": "", "pos": "短语", "meaning": "彼此(指两者之间）", "examples": [{"en": "We helped each other study for the test. We must help one another in times of trouble.", "zh": "我们互相帮忙准备考试。）（有困难时我们必须互相帮助。"}], "sub_entries": ["one another", "彼此(指三者或三者以上）", "*oneanother只能用于指三者或三者以上，而就严", "谨文法而言，eachother只能用于指两者之间。", "但现今美语口语用法里，也常用eachother来指", "三者或三者以上。"]}, {"num": 3, "word": "fail", "phonetic": "[fel]", "pos": "vt.", "meaning": "无法做到，失败", "examples": [], "sub_entries": ["fail to+动词原形", "未能··", "neverfailto+动词原形", "定会·"]}, {"num": 4, "word": "attend", "phonetic": "[aˈtend]", "pos": "vt.", "meaning": "参加", "examples": [{"en": "Frank will be attending high school in Beijing next fall.", "zh": "明年秋天弗兰克将要去北京念高中。"}], "sub_entries": ["attend class", "上课", "=go to class", "attendschool", "上学", "=go to school"]}, {"num": 5, "word": "remember", "phonetic": "[rˈmemb]", "pos": "vt.", "meaning": "记得", "examples": [], "sub_entries": ["remember to +动词原形", "记得要·····"]}, {"num": 6, "word": "homework", "phonetic": "[ˈhoʊmwɜːrk]", "pos": "n.", "meaning": "家庭作业（不可数）", "examples": [], "sub_entries": []}, {"num": 7, "word": "forgot", "phonetic": "[foˈɡat]", "pos": "vt.", "meaning": "忘记（为 forget [ fa'get l 的过", "examples": [], "sub_entries": ["去式）", "forget to +动词原形", "忘了要····"]}, {"num": 8, "word": "pretty", "phonetic": "[ˈpritr]", "pos": "adv.", "meaning": "颇，相当", "examples": [], "sub_entries": ["s   s", "（我班上的新同学相当聪明。）"]}, {"num": 9, "word": "prove", "phonetic": "[pruv]", "pos": "vt.", "meaning": "证明", "examples": [{"en": "The clever lawyer proved the man was a thief.", "zh": "那聪明的律师证明这男子是小偷。"}], "sub_entries": []}, {"num": 10, "word": "gain", "phonetic": "[ɡen]", "pos": "n.", "meaning": "收获", "examples": [], "sub_entries": []}, {"num": 11, "word": "pain", "phonetic": "[pen]", "pos": "n.", "meaning": "劳苦", "examples": [], "sub_entries": []}, {"num": 12, "word": "There is no gain without pain.", "phonetic": "", "pos": "谚语", "meaning": "一分耕耘，一分收获。（谚语）", "examples": [], "sub_entries": []}], "grammar": {"intro": "本课介绍动词不定式的用法。", "items": [{"num": 1, "title": "My best friend Billy and I decided to learn English last year.", "body": ["（我和挚友比利去年决心要学英文。）", "We promised each other to work hard.（我们彼此允诺要努力学习。）以上两句的划线部分是动词不定式。动词不定式乃由 虚词to加动词原形形成，具有名词、形容词、副词 的功能。", "a. 名词：", "1）作主语", "例: To work with him is pleasant.", "=It is pleasant to work with him.（与他共事很愉快。）", "2）作宾语 此时所使用的动词均有“愿望”、“决心”等 含意、如decide（决心要.….…·）、wish（希 望..…）、want（要.….…）、desire（想要 ...….）、promise（允诺….…）、plan（计 划….….等。", "例： I decided to visit him tomorrow.（我决定明天去看他。）", "He is planning to study abroad.（他正计划要出国念书。）He promised (me) to write the letter.（他答应（我）要写这封信。）", "3）置于be动词之后，作表语 此时主语亦多为表示“愿望、决心”等名词。", "例：My only wish before I leave is to see her one more time.（我离开前，唯一的愿望就是再见她-面。）", "His plan is to marry her soon.（他的计划就是要很快娶到她。）", "b. 形容词", "此时动词不定式置于被修饰的名词之后，修饰该名 词。", "例： I have some work to do.", "n.（我有一些工作要做。）", "That's not the right way to learn English.", "n.（那并不是学英文的正确方法。）", "c. 副词", "此时动词不定式可置于完整的句子之前或之后，表 示目的。", "例：完整句 He worked hard.（他用功。）", "加人动词不定式", "To pass the exam, he worked hard.", "=He worked hard to pass the exam.（为了考试能及格，他很用功。）"]}, {"num": 2, "title": "neverfailto+动词原形", "body": ["例：My son never fails to call me up on Sunday mornings.（我儿子总会在星期天早上打电话给我。）", "fail to+动词原形 未能····.", "例：Paul failed to get intomedical school.（保罗未能进人医学院就读。）"]}, {"num": 3, "title": "remember to + 动词原形（记得要...）", "body": ["remember to + 动词原形 表示“记得要去做某事”（动作尚未发生）。", "例：Son, remember to turn off the light.（儿子，记得把电灯关掉。）", "remember+动名词 记得曾经....·", "例：Do you remember losing this ring many years ago?（你记得多年前曾遗失这只戒指吗？）"]}, {"num": 4, "title": "forget to + 动词原形（忘了要...）", "body": ["forget to + 动词原形 表示“忘记要去做某事”（该做而未做）。", "例： Don't forget to meet Sally after school.（别忘了下课后与萨莉碰面。）", "forget+动名词 忘了曾经…···", "例: I'll never forget seeing my son graduate.（我永远不会忘记看到我儿子毕业。）"]}, {"num": 5, "title": "Our English is pretty good now.", "body": ["（我们的英文现在很不错了。）pretty可作形容词或副词·作形容词时，表示“美丽 的”；作副词时，则表示“颇”、“相当”的意思，比very语气稍弱些。", "例: Who's that pretty girl over there?", "a.", "n.（那里那位漂亮女孩是谁？）", "It's pretty hot today. adv. a.（今天天气相当热。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 72, "title_en": "Remember to Wash", "title_zh": "别忘了漱洗", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Don't forget to brush your teeth before you go to bed!", "zh": "睡觉前别忘了要刷牙！"}, {"speaker_en": "Micky", "speaker_zh": "米其", "en": "Yes, Mom.", "zh": "是的，母亲。"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "And remember to wash your hands before meals.", "zh": "而且吃饭前要记得洗手。"}, {"speaker_en": "Micky", "speaker_zh": "米其", "en": "Yes, Mom. Anything else?", "zh": "是的，母亲·还有其他的事吗？"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Yes, remind me to tell your sister the same thing.", "zh": "有的，要提醒我告诉你妹妹同样的事。"}]}, "vocab": [{"num": 1, "word": "meal", "phonetic": "[mil]", "pos": "n.", "meaning": "一餐", "examples": [{"en": "I usually eat three meals a day.", "zh": "我一天通常吃三餐。"}], "sub_entries": []}, {"num": 2, "word": "remind", "phonetic": "[rˈmaind]", "pos": "vt.", "meaning": "提醒", "examples": [{"en": "Please remind me to call him tomorrow.", "zh": "请提醒我明天打电话给他。"}], "sub_entries": ["remind+人+to+动词原形", "提醒某人去做…··"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ。请选出下列各句中正确的一项", "questions": ["1. Vivian", "love stories.", "(A) likes to read", "(B) likes to reading", "(C) is like to read", "(D) is like reading", "2. Billy lives", "far away from here.", "(A) pretty", "(B) smart", "(C) cute", "(D）ugly", "3. Todd's dream", "a novel.", "(A) wants to write", "(B) wants writing", "(C) is to write", "(D) enjoys to write", "4. I'm sorry. I don't", "your name.", "(A) forget", "(B) remember", "(C) hear", "(D) look", "5. Please", "clean your room when you get", "home.", "(A) remember", "(B) remember to", "(C) don't forget", "(D)to remember to", "6. I might", "so please remind me to call", "Roger.", "(A) remember", "(B) not forget", "(C) forgot", "(D) forget"], "answers": ["解答>1.(A）2.(A）3.(C）4.(B）5.(B）6.(D)"]}}, {"num": 73, "title_en": "Joe's Restaurant", "title_zh": "乔的餐厅", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Joe is learning how to cook. He has to learn because he wants to start a small restaurant. His mother is teaching him. She used to be a chef at a big restaurant. With her help, he ought to have no problem. I'm sure Joe's restaurant is going to be the best restaurant in town."], "zh": ["乔正在学习如何烹饪。他必须要学，因为他想要开一家小餐厅。他母亲正在教他。她曾在一家大餐厅当过厨师。有了她的帮助：他应当不会有什么问题。我确信乔的餐厅将成为镇上最好的餐厅。"]}, "dialog": null, "vocab": [{"num": 1, "word": "learn", "phonetic": "[lɜːrn]", "pos": "vt.", "meaning": "&vi.学习", "examples": [{"en": "Sam learned three foreign languages in university. The smart young boy learns very fast.", "zh": "萨姆在大学里学了三种外语。）（那个聪明的年轻男孩学东西很快。"}], "sub_entries": []}, {"num": 2, "word": "cook", "phonetic": "[kuk]", "pos": "vi.", "meaning": "烹饪", "examples": [{"en": "My mother is cooking in the kitchen.", "zh": "妈妈正在厨房煮饭。"}], "sub_entries": []}, {"num": 3, "word": "start", "phonetic": "[start]", "pos": "vt.", "meaning": "开始（本文中指“设立”）", "examples": [], "sub_entries": []}, {"num": 4, "word": "teach", "phonetic": "[titf]", "pos": "vt.", "meaning": "教", "examples": [{"en": "I need someone to teach me English composition.", "zh": "我需要个人来教我英文作文。"}], "sub_entries": []}, {"num": 5, "word": "used to + 动词原形", "phonetic": "", "pos": "短语", "meaning": "过去常常...", "examples": [{"en": "I used to run five kilometers every morning.", "zh": "我以前每天早上都跑五公里。"}], "sub_entries": ["以前曾经··.", "used[just]vi.惯常，向来（恒用过去式）"]}, {"num": 6, "word": "chef", "phonetic": "[ʃɛf]", "pos": "n.", "meaning": "主厨，厨师", "examples": [], "sub_entries": []}, {"num": 7, "word": "ought", "phonetic": "", "pos": "", "meaning": "to+动词原形", "examples": [{"en": "Don't get so angry; you ought to be more patient.", "zh": "别这么生气，你应当更有耐心些。"}], "sub_entries": ["应当···", "ought['ot]aux.应当"]}, {"num": 8, "word": "problem", "phonetic": "[ˈprablam]", "pos": "n.", "meaning": "问题", "examples": [{"en": "Fred's computer has a problem, so he's using a typewriter.", "zh": "弗雷德的电子计算机出了问题，因此他正在用打字机。"}], "sub_entries": []}, {"num": 9, "word": "be sure + that从句", "phonetic": "", "pos": "句型", "meaning": "确信...，确定...", "examples": [{"en": "Kate, be sure (that) you turn off the radio before going to sleep.", "zh": "凯特，你在上床前一定要把收音机关掉。"}], "sub_entries": ["确定··"]}, {"num": 10, "word": "in town", "phonetic": "", "pos": "短语", "meaning": "在城镇中", "examples": [{"en": "Is this the only shoe store in town?", "zh": "这是镇上唯一的一家鞋店吗？"}], "sub_entries": ["town[taun]n.城镇"]}], "grammar": {"intro": "本课续介绍动词不定式的用法。", "items": [{"num": 1, "title": "以下是有关动词不定式的两个重要用法：", "body": ["a. Joe is learning how to cook.（乔正在学习如何烹饪。）", "此处how tocook 称做名词短语，由“疑问词+动词不定式”形成·如：", "where to go 到哪儿去 when to do it 什么时候做这件事 how to do it 如何做这件事 what to do 做什么 whom to talk to 要跟谁说话 which to buy 要买哪一个", "注意：", "1）以上这些名词短语中，where、when、how 均为疑问副词，修饰之后的动词不定式。而 what、whom、which则为疑问代词，要作动 词不定式中及物动词的宾语，如上列名词短语 中：what作do之宾语，which作buy的宾 语。但疑问代词之后的动词不定式是不及物动 词时，则该名词短语之后应有介词，使该疑问代 词作该介词之宾语，如\"whom to talk to\"中，whom即作介词to的宾语。", "2）名词短语具有名词的功能，在句中通常作及物 动词的宾语。在\"Joe is learning how to cook.\"一句中，howtocook即作及物动词 learn 的现在进行式islearning 的宾语。", "例：He knows how to handle the problem.", "vt. 名词短语（他懂得如何处理这个问题。）I don't know whom to work with. vt. 名词短语（我不知道要跟谁工作。）", "b. She used to be a chef at a big restaurant.（她曾在一家大餐厅当过厨师。）", "此处usedto表示“过去曾经….…”的意思。句型 如下：", "主语+used to+动词原形", "例：Theyused tolivethere.（他们以前曾在那里住过。）", "I used to study Japanese.（我以前曾经学过日文。）He used to be my student, but he is my colleague now.（他以前是我的学生，但现在却成了我的同 事。）"]}, {"num": 2, "title": "I'm sure Joe's restaurant is going to be the best restaurant in town.", "body": ["（我确信乔的餐厅将成为镇上最好的餐厅。）本句原为\"I'm sure that Joe's restaurant is going tobe thebest restaurant in town.\"。that 是连词，引导的从句修饰之前的形容词sure，故称状语从句，that经常予以省略。", "例：I am sure (that) he will be coming this afternoon.", "=I believe (that) he will be coming this afternoon.（我相信今天下午他会来。）", "注意：", "在\"Ibelieve\"之后由that引导的从句，因作及物动 词believe的宾语，故称名词性从句，that亦可省 略。"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 74, "title_en": "You Ought to Learn to Swim", "title_zh": "你应当学习游泳", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Adam", "speaker_zh": "亚当", "en": "Do you know how to swim?", "zh": "你知道怎么游泳吗？"}, {"speaker_en": "Eva", "speaker_zh": "夏娃", "en": "No, I don't.", "zh": "不，我不知道。"}, {"speaker_en": "Adam", "speaker_zh": "亚当", "en": "You ought to learn.", "zh": "你应当学习。"}, {"speaker_en": "Eva", "speaker_zh": "夏娃", "en": "Why?", "zh": "为什么？"}, {"speaker_en": "Adam", "speaker_zh": "亚当", "en": "Well, maybe you'll have to save me one day.", "zh": "嗯；也许有一天你将必须救我·"}]}, "vocab": [{"num": 1, "word": "maybe", "phonetic": "[ˈmebi]", "pos": "adv.", "meaning": "也许", "examples": [{"en": "He maybe can do it. (×) →Maybe he can do it.(○)", "zh": "也许他能做这件事）b.maybe 与 maybe不一样，前者是副词，后者则为\"助动词may（也许）+be动词（是）”。比较下列各句："}, {"en": "Maybe you are right. You maybe right. (×) → You may be right. (○)", "zh": "也许你是对的。）（你也许是对的。"}], "sub_entries": ["a.使用本单词时应置于句首。"]}, {"num": 2, "word": "save", "phonetic": "[sev]", "pos": "vt.", "meaning": "拯救", "examples": [{"en": "In the movie, the hero saved the woman from drowning.", "zh": "在这部电影中，那位英雄救了溺水的女士。"}], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1.I don't know", "to speak with.", "(A) where(B)how", "(C)when (D） whom", "2.Wehaven't decided", "to go for lunch yet.", "(A)whom", "(B)where(C）what", "(D) which", "3.", "it will rain today.", "(A) May be", "(B)Maybe", "(C) Might be", "(D) Could be", "4. I'm", "we'll have a good time.", "(A) think that", "(B) believe", "(C) sure", "(D) believe that", "5.This", "the best restaurant in town.", "(A) may be", "(B)maybe", "(C) perhaps", "(D）might"], "answers": ["解答=1.(D）2.(B）3.(B）4.(C）5.（A)"]}}, {"num": 75, "title_en": "Michael's Dream", "title_zh": "迈克的梦想", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Michael wanted to be a musician, but his mother wanted him to be a doctor. Michael didn't want to make his mother feel sad, so he decided to obey her. Rather than play music, he studied medicine. Unfortunately, Michael failed to graduate from medical school. However, he isn't sad because he is now a famous musician."], "zh": ["迈克想要当音乐家，但他的母亲却希望他成为一名医生。迈克不想使他的母亲感到难过，因此他决定听她的话。他没有演奏音乐而改学医去了。不幸的是，迈克未能从医学院毕业。然而，他并不难过，因为他现在成了一位知名的音乐家。"]}, "dialog": null, "vocab": [{"num": 1, "word": "musician", "phonetic": "[mjuˈzijan]", "pos": "n.", "meaning": "音乐家", "examples": [], "sub_entries": []}, {"num": 2, "word": "doctor", "phonetic": "[ˈdokto]", "pos": "n.", "meaning": "医生", "examples": [], "sub_entries": []}, {"num": 3, "word": "decide", "phonetic": "[drˈsaid]", "pos": "vt.", "meaning": "决定", "examples": [{"en": "Joe had a sore throat, so he decided to stay home from school.", "zh": "乔喉咙痛，因此他决定待在家里而不去学校。"}], "sub_entries": []}, {"num": 4, "word": "obey", "phonetic": "[aˈbe]", "pos": "vt.", "meaning": "服从", "examples": [{"en": "When driving, you must obey the traffic regulations.", "zh": "开车时，你必须遵守交通规则。"}], "sub_entries": []}, {"num": 5, "word": "rather ..", "phonetic": "", "pos": "than.", "meaning": "而不.….….，而非...·.", "examples": [{"en": "Rather than play pool, we went bowling.", "zh": "我们没去打撞球而去打保龄球。"}], "sub_entries": []}, {"num": 6, "word": "medicine", "phonetic": "[ˈmedasn]", "pos": "n.", "meaning": "医学", "examples": [], "sub_entries": []}, {"num": 7, "word": "unfortunately", "phonetic": "[ʌnˈfɔːrtʃənətli]", "pos": "adv.", "meaning": "不幸地", "examples": [{"en": "We wanted to go to the beach; unfortunately, it was raining.", "zh": "我们想去海边，不幸的是天空正在下雨。"}], "sub_entries": []}, {"num": 8, "word": "graduate ..", "phonetic": "", "pos": "from.", "meaning": "毕业于.…··.", "examples": [{"en": "After I graduated from university, I got a job in a trading company.", "zh": "大学毕业后，我在一家贸易公司找到一份工作。"}], "sub_entries": ["graduate['grad3uet ]vi.毕业"]}, {"num": 9, "word": "medical", "phonetic": "[ˈmedikl]", "pos": "a.", "meaning": "医学的", "examples": [], "sub_entries": ["medical school", "医学院"]}, {"num": 10, "word": "famous", "phonetic": "[femas]", "pos": "a.", "meaning": "有名的", "examples": [{"en": "This restaurant is famous for its steamed dumplings.", "zh": "这家餐厅以其蒸饺而闻名。"}], "sub_entries": []}], "grammar": {"intro": "本课继续介绍有关动词不定式的其他重要用法，并介绍知 觉动词的用法。", "items": [{"num": 1, "title": "Michael wanted to be a musician...", "body": ["（迈克想要当音乐家·…·…．）...so he decided to obey her.（...因此他决定听她的话。）以上两句的动词wanted（想要）及decided（决 定）均为表示意愿的及物动词过去式，之后须接动词 不定式（即to+动词原形）作其宾语。常用的此类表示意愿的动词有：want、decide、expect（期望）、desire（渴望）、plan（计划）、wish（希望）、hope（希望）、try（设法）、attempt（企图）等。", "例: I wish to jog with him tomorrow morning.（我希望明天早上跟他慢跑去。）", "When do you plan to take the trip?（你计划什么时候去旅行？）", "注意：", "think表示“想”或“认为”，应使用that引导的名 词性从句作宾语，不可使用动词不定式作宾语。", "例： I think to buy a bike for my son. (×)", "→I think(that)I'llbuyabike formyson.（0)（我想我会买一辆自行车给我儿子。）", "比较：", "I want to buy a bike for my son.(○)（我想要买一辆自行车给我儿子。）"]}, {"num": 2, "title": "Michael didn't want to make his mother feel sad.", "body": ["（迈克不想使他的母亲感到难过··之后接宾语hismother，再以动词原形feel及形 容词sad形成的短语作宾语补足语。此类句型如 下：", "make+人+动词原形", "例：Mother made me clean the house.（妈妈叫我打扫房子。）", "make接宾语时，之后亦可置名词或形容词作宾语 补足语，此时make表示“使／令....…变成／成 为··…”的意思，句型如下：", "make+人/物+名词/形容词: The music made me happy.（这音乐合我快乐。）The teacher has made John a good boy.（老师使约翰变成了好孩子。）His help has made our plan quite successful.（他的帮助使我们的计划相当成功。）", "b. feel sad 感到难过的 此处feel表示“感到”的意思，是一种意思不完 全的不及物动词，之后须接形容词作主语补足语。此类知觉动词一共有五个，句型如下：", "feel（感到）", "+形容词", "smell（闻起来）", "taste（尝起来）", "look（看起来）", "sound（听起来）", ": The food smells really good.", "a.（这食物闻起来真香。）", "Though he is sixty, he looks young.", "a.（虽然他已60岁了，但他看起来很年轻。）", "The idea sounds good.", "a.（这个主意听起来不错。）"]}, {"num": 3, "title": "Rather than play music, he studied medicine.", "body": ["（他没有演奏音乐而改学医去了。）此处ratherthan为并列连词，表示“而非”的意 思，用以连接彼此为并列关系的单词、短语或从句 等。", "例：He is lazy rather than diligent.", "a.", "a.（他是懒惰，而非勤奋。）", "Mary is a student rather than a teacher.", "n.", "n.（玛丽是学生而非老师。）", "He is interested in swimming rather than 介词短语(in) dancing. 介词短语（他对游泳而非舞蹈有兴趣。）He failed because he was lazy rather than 状语从句 because he was stupid. 状语从句（他失败是因为他懒惰而不是因为他愚蠢。）", "注意：", "a. rather than 亦可连接两个有并列关系的动词，句 型如下：", "rather than+动词原形，主语+动词.... 非但不··…反而···:Rather than work hard, he plays around all the time.", "=Instead of working hard, he plays around all the time.（他非但不用功，反而一直都在鬼混。）本课阅读中的\"Rather thanplaymusic，he studied medicine.”即属此用法。", "b. ratherthan亦可连接两个有并列关系的主语，之 后的动词则应按第一个主语作变化。", "例:He rather than I am wrong.（×)", "-→He rather than I is wrong. (○)（是他错，而非我错。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 76, "title_en": "I Want to Be a Doctor", "title_zh": "我想当医生", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Mother", "speaker_zh": "母亲", "en": "What do you want to be when you grow up?", "zh": "你长大以后想要当什么？"}, {"speaker_en": "Child", "speaker_zh": "孩子", "en": "I want to be a doctor.", "zh": "我想当医生。"}, {"speaker_en": "Mother", "speaker_zh": "母亲", "en": "Why?", "zh": "为什么？"}, {"speaker_en": "Child", "speaker_zh": "孩子", "en": "I want to help sick people.", "zh": "我想要帮助生病的人。"}]}, "vocab": [], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ.请选出下列各句中正确的一项", "questions": ["1. Billy expects", "his grandparents soon.", "(A)visit", "(B）to visit", "(C) visiting", "(D) paying a visit to", "2. My boss", "me work all weekend.", "(A) made", "(B) make", "(C) wanted making", "(D) wanted", "3.", "eat at home, we ate in a restaurant.", "(A) To", "(B)Instead", "(C) To not", "(D) Rather than", "4.I think", "camping this weekend.", "(A) to go", "(B) going", "(C) 1'11 to", "(D) that I'll go", "5.He rather than I", "successful.", "(A) is", "(B) are", "(C) am", "(D) have been"], "answers": ["解答→1.(B）2.(A）3.(D）4.(D）5.(A)"]}}, {"num": 77, "title_en": "Rome Wasn't Built in a Day", "title_zh": "罗马不是一天造成的", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Learning English is like building a house. Laying a strong foundation is the first and most important step. In other words, you should read and speak English every day. Memorizing new words and phrases is also helpful. Like building a house, learning English takes some time. So don't be impatient. Remember, \"Rome wasn't built in a day.\""], "zh": ["学英文就像盖房子一样。定扎实的基础是第一步也是最重要的一步。换句话说，你应该每天读英文和说英文。记新的单词和短语也是很有帮助的。就像盖房子一样，学英文需要一些时"]}, "dialog": null, "vocab": [{"num": 1, "word": "build", "phonetic": "[bild]", "pos": "vt.", "meaning": "建造", "examples": [{"en": "It is said that the house was built more than two hundred years ago.", "zh": "据说这幢房子是200多年前建的。"}], "sub_entries": ["动词三态：build，built，built。"]}, {"num": 2, "word": "lay a strong foundation", "phonetic": "", "pos": "短语", "meaning": "奠定坚实的基础", "examples": [{"en": "When you build a house, you need to lay a strong foundation.", "zh": "盖房子时你需要先打下稳固的基础。"}], "sub_entries": ["lay[le]vt.安放", "动词三态：lay、laid、laid。", "foundation[faun'defan ]n.基础"]}, {"num": 3, "word": "important", "phonetic": "[imˈportnt]", "pos": "a.", "meaning": "重要的", "examples": [{"en": "I have an important exam in history class tomorrow.", "zh": "明天我的历史课有一场重要的考试。"}], "sub_entries": []}, {"num": 4, "word": "step", "phonetic": "[step]", "pos": "n.", "meaning": "步骤", "examples": [], "sub_entries": []}, {"num": 5, "word": "in other words", "phonetic": "", "pos": "短语", "meaning": "换句话说", "examples": [{"en": "I have to work late tonight; in other words, I can't go to the movies with you.", "zh": "今晚我必须工作到很晚，换句话说，我不能和你一起去看电影。"}], "sub_entries": []}, {"num": 6, "word": "memorize", "phonetic": "[ˈmema.raiz]", "pos": "vt.", "meaning": "记，背", "examples": [{"en": "I can memorize every single word he said.", "zh": "我可以背下他所说的每个字。"}], "sub_entries": []}, {"num": 7, "word": "phrase", "phonetic": "[frez]", "pos": "n.", "meaning": "短语", "examples": [], "sub_entries": []}, {"num": 8, "word": "helpful", "phonetic": "[ˈhelpfal]", "pos": "a.", "meaning": "有帮助的", "examples": [{"en": "My teacher gave me many helpful suggestions on how to improve my English.", "zh": "我的老师就如何改进我的英文方面给了我很多有帮助的建议。"}], "sub_entries": []}, {"num": 9, "word": "impatient", "phonetic": "[imˈpefant]", "pos": "a.", "meaning": "不耐烦的，没耐性的", "examples": [{"en": "Don't be so impatient with Johnny; he's just a child.", "zh": "别对约翰尼这么没耐性，他只是个孩子。"}], "sub_entries": []}], "grammar": {"intro": "本课介绍动名词的用法。 动名词与现在分词的形态完全一样，均由动词加-ing 形 成，但功能不同。兹叙述如下：", "items": [{"num": 1, "title": "现在分词", "body": ["a. 与be动词并用，形成进行时，表示“正在·…... 的意思。", "例: He is swimming now.（他现在正在游泳。）", "b. 作形容词，表示“令人......的”的意思。", "例: Who is that charming girl over there?（那边那位迷人的女孩子是谁？）", "The question is confusing.（这个问题令人迷惑。）"]}, {"num": 2, "title": "动名词", "body": ["动名词可视为名词，功能与名词一样，有下列用法：", "a. 作主语", "名词：", "The boy is his son.（那男孩是他的儿子。）动名词：", "Swimming is my hobby.（游泳是我的爱好。）", "b. 作及物动词或介词的宾语", "名词：", "No one enjoyed that movie.（没人喜欢那部电影。）He is interested in music.（他对音乐有兴趣。）动名词：", "I enjoy listening to music.（我喜欢听音乐。）I am sick of talking to him.（我讨厌跟他说话。）", "c. 作表语：（置于be动词之后，作主语补足语）", "名词：", "He is my teacher.（他是我的老师。）动名词：", "My hobby is swimming.（我的爱好是游泳。）", "d. 作定语：（置于名词之前作形容词，修饰该名词）", "名词：", "Can I borrow your chemistry book?", "n.", "n.（你的化学课本可不可以借给我？）", "动名词：", "I lost my walking stick. 动名词n.（我把我的拐杖弄丢了。）"]}, {"num": 3, "title": "动名词与现在分词的分辨：", "body": ["初学英语的读者见到be动词之后或名词之前有词尾 为-ing的单词时，不易分辨该单词是现在分词或动 名词·其实我们可藉由中文的翻译来破解这个迷惑。", "a.“be动词+词尾为-ing的单词”若可译成“正 在·…·”时，则该单词是现在分词，形成进行时的 句子结构·", "例：英文：He is swimming.", "中译：他正在游泳。说明：swimming是现在分词。b．“be 动词+词尾为-ing 的单词”若译成“今 人·…··的”时，则该单词仍是现在分词，作形容 词，在句中作主语补足语。", "例：英文：The question is confusing.", "中译：这问题令人迷惑。说明：此处confusing是现在分词。", "c.“be动词+词尾为-ing的单词”若译成“是…”时，则该单词是动名词，且该动名词可与主 语互换位置。", "例：英文：Hishobby is swimming.", "中译：他的爱好是游泳。说明：swimming是动名词。", "His hobby is swimming.", "= Swimming is his hobby.（游泳是他的爱好。）", "d. 在“词尾为-ing的单词+名词”中，若该单词 译成“令人...…·的”时，或“主动会...····的”时，则该单词是现在分词作形容词，修饰之后的名词。", "例：英文：He asked a confusing question.", "a.", "n. 中译：他问了一个令人迷惑的问题。英文：He knows many words, so we call him a walking dictionary.", "a.", "n. 中译：他认识许多字，因此我们称他为“活 字典”。说明：此处confusing表示“令人迷惑的”walking则表示“会走路的”，即“活的”之意。confusing与walking 均为现在分词。", "e. 在“词尾为-ing的单词+名词”中，若该单词译 成“供·…··之用的”时，则该单词是动名词，仍作 形容词，修饰之后的名词。", "例：英文：I lost my walking stick.", "a.", "n. 中译：我把我那供来走路用的棍子弄丢了。即：我把我的拐杖弄丢了。说明：此处walking是动名词。现在我们且来自我测验一下，籍由译文分辨下列各 句中词尾为-ing的单词，何者是动名词，何者是 现在分词。", "1). He is smoking.", "2). His bad habit is smoking.", "3). There is a swimming pool near my house.", "4). I enjoy swimming with them.", "5). Mary is swimming with us.", "6). The news is exciting.", "1).他正在抽烟。（smoking 是现在分词）", "2)．他的不良爱好是抽烟。（smoking 是动名词）", "3)．我家附近有一座游泳池。（swimming 是动名 词，译成“供来游泳的”）", "4).我喜欢跟他们游泳。（swimming是动名词，作 及物动词enjoy的宾语）", "5)．玛丽正在跟我们游泳。（swimming是现在分 词）", "6).这消息金人兴奋。（exciting 是现在分词）"]}, {"num": 4, "title": "动名词短语作主语时的谓语单复数", "body": ["及物动词变成动名词时，之后仍应接宾语。该动名词短语作主语时，不论其宾语是单数、复数或不可数名词，谓语动词一律用单数形式。", "例：Writing English is easy for him.", "动名词", "n.（对他来说，写英文很容易。）", "Climbing mountains is my hobby. 动名词", "n.（爬山是我的爱好。）"]}]}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 78, "title_en": "Don't Be Discouraged", "title_zh": "不要泄气", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Your written English is fairly good, but your spoken English needs improvement.", "zh": "你的英文笔试还不错，但你的英文口试需要加强了。"}, {"speaker_en": "Student", "speaker_zh": "学生", "en": "I know, but speaking English is difficult.", "zh": "我知道，但说英文好难啊。"}, {"speaker_en": "Teacher", "speaker_zh": "老师", "en": "Don't be discouraged. Practice makes perfect.", "zh": "不要泄气。熟能生巧。"}]}, "vocab": [{"num": 1, "word": "written English", "phonetic": "[ˈrɪtn ˈɪŋɡlɪʃ]", "pos": "n.", "meaning": "英文笔试，书面英文", "examples": [], "sub_entries": []}, {"num": 2, "word": "spoken English", "phonetic": "[ˈspoʊkən ˈɪŋɡlɪʃ]", "pos": "n.", "meaning": "英文口试，口头英文", "examples": [], "sub_entries": []}, {"num": 3, "word": "improvement", "phonetic": "[ɪmˈpruːvmənt]", "pos": "n.", "meaning": "改善，进步", "examples": [{"en": "\"I don't see any improvement in your work,\" the boss said.", "zh": "老板说：“我看不出你的工作有任何改善。”"}], "sub_entries": []}, {"num": 4, "word": "discouraged", "phonetic": "[dɪsˈkɜːrɪdʒd]", "pos": "a.", "meaning": "泄气的，沮丧的", "examples": [{"en": "Jim was discouraged by his exam result.", "zh": "吉姆对他的考试成绩感到很沮丧。"}], "sub_entries": []}, {"num": 5, "word": "Practice makes perfect.", "phonetic": "", "pos": "（谚语）", "meaning": "熟能生巧。", "examples": [], "sub_entries": []}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ·请选出下列各句中正确的一项", "questions": ["1. Frank really", "to his pen pal.", "(A)enjoy writing", "(B) enjoy to write", "(C) enjoys writing", "(D) enjoys to write", "2. I'm tired", "you to clean your room.", "(A) of telling", "(B) to tell", "(C) of tell", "(D) for telling", "3.", "a bicycle is good exercise.", "(A) Riding", "(B）Driving", "(C) Sitting", "(D) Going on", "4. I've been thinking", "a computer.", "(A) to buy", "(B)buying", "(C) of buying", "(D) in buying", "5.Playing basketball with my friends", "a lot", "of fun.", "(A) are", "(B) is", "(C) am", "(D)were"], "answers": ["解答1.(C）2.(A）3.(A）4.(C）5.(B)"]}}, {"num": 79, "title_en": "Showing Off", "title_zh": "炫耀", "type": "reading", "category": "精读短文与语法核心", "reading": {"en": ["Many people are fond of showing off. They always insist on footing the bill when they are out with friends. They always think of impressing people with their wealth. They seem to think that money can buy friends. In fact, it can't. Instead of trying to show off, they should be themselves."], "zh": ["有很多人喜欢炫耀。当他们和朋友外出时总是争着付帐。他可以买到朋友。但事实上，钱无法买到朋友。他们不应炫耀，而应做真正的自我。"]}, "dialog": null, "vocab": [{"num": 1, "word": "show off", "phonetic": "", "pos": "短语", "meaning": "炫耀", "examples": [{"en": "I think people who show off are silly.", "zh": "我认为爱炫耀的人是很愚蠢的。"}], "sub_entries": []}, {"num": 2, "word": "be fond of...", "phonetic": "", "pos": "短语", "meaning": "喜欢...", "examples": [{"en": "My mother is not only fond of cooking; she's also a wonderful cook.", "zh": "我母亲不只喜欢烹饪，她还是很棒的厨师。"}], "sub_entries": ["喜欢··", "fond[fand]a.喜欢的"]}, {"num": 3, "word": "insist on + 动名词", "phonetic": "", "pos": "短语", "meaning": "坚持...", "examples": [{"en": "Whenever I take my son out to dinner, he insists on eating hamburgers.", "zh": "每当我带我儿子外出晚餐时，他总是坚持要吃汉堡包。"}], "sub_entries": ["坚持要··.", "insist[in'sist]vi.坚持"]}, {"num": 4, "word": "foot the bill", "phonetic": "", "pos": "短语", "meaning": "付帐", "examples": [{"en": "He didn't have enough money to foot the bill.", "zh": "他没有足够的钱付帐。"}], "sub_entries": []}, {"num": 5, "word": "impress + 人 + with + 事物", "phonetic": "", "pos": "短语", "meaning": "以某事给某人留下深刻印象", "examples": [{"en": "Bob impressed us with his knowledge of world history.", "zh": "鲍勃对世界史的知识使我们印象深刻。"}], "sub_entries": ["以某事物使人印象深刻", "impress[im'pres]vt.使印象深刻"]}, {"num": 6, "word": "wealth", "phonetic": "[wslo]", "pos": "n.", "meaning": "财富", "examples": [{"en": "The king has great wealth.", "zh": "这个国王拥有大笔的财富。"}], "sub_entries": []}, {"num": 7, "word": "seem to + 动词原形", "phonetic": "", "pos": "短语", "meaning": "似乎...，好像...", "examples": [{"en": "John seems to be happy, but I can't be sure.", "zh": "约翰似乎很快乐，但我不能肯定。"}], "sub_entries": ["似乎····", "seem[sim]vi.似乎"]}, {"num": 8, "word": "instead of + 动名词/名词", "phonetic": "", "pos": "短语", "meaning": "而不是...，代替...", "examples": [{"en": "Instead of riding bicycles, let's go for a walk.", "zh": "咱们不要骑自行车，改去散步吧。"}], "sub_entries": ["非但不…反而", "instead[in'sted]adv.代替"]}, {"num": 9, "word": "be oneself", "phonetic": "", "pos": "短语", "meaning": "做真实的自我", "examples": [{"en": "Don't be nervous about your interview; just be yourself and you'll do fine.", "zh": "别担心你的面试，你只要表现出真正的自我就会做得很好。"}], "sub_entries": []}], "grammar": {"intro": "本课强调动名词可作介词的宾语之用法。 Many people are fond of showing off. （有很多人喜欢炫耀。） They always insist on footing the bill when they are out with friends. （他们与朋友外出时总是争着付帐。） 以上两句中 showingoff 及footing thebill均为动名 词短语，分别作介词of及on的宾语。 在前一-课中，我们已说明动名词除可作及物动词的宾语 外，亦可作介词的宾语。 例：I'm looking forward to seeing you again soon. （我期盼很快再与你见面。） *look forward to 期盼（to是介词，故之后 应接动名词作其宾语。） He's thinking about getting married this year. （他正考虑今年要结婚。）", "items": []}, "substitution": [{"num": 1, "en": "", "zh": "", "pairs": []}, {"num": 2, "en": "", "zh": "", "pairs": []}], "exercises": null}, {"num": 80, "title_en": "I'm Good at Cooking", "title_zh": "我擅长烹饪", "type": "dialogue", "category": "情境实战会话", "reading": null, "dialog": {"turns": [{"speaker_en": "Marty", "speaker_zh": "马蒂", "en": "Are you good at sewing?", "zh": "你对缝纫很在行吗？"}, {"speaker_en": "Becky", "speaker_zh": "贝基", "en": "No, but I'm good at cooking. What about you?", "zh": "不，但我对烹饪很在行。你呢？"}, {"speaker_en": "Marty", "speaker_zh": "马蒂", "en": "I'm not good at cooking, but I'm fond of eating.", "zh": "我对烹饪不在行，但我却很喜欢吃。"}]}, "vocab": [{"num": 1, "word": "cooking", "phonetic": "[ˈkukiɡ]", "pos": "n.", "meaning": "烹饪", "examples": [{"en": "My sister's cooking is terrible. Mother cooked some dumplings for lunch.", "zh": "我姐姐的烹饪很糟糕。）（妈妈午餐时煮了些水饺。"}], "sub_entries": ["cook[kuk ]vt.& vi.烹饪"]}, {"num": 2, "word": "be ..", "phonetic": "", "pos": "at.", "meaning": "精通于·…·，擅长于", "examples": [{"en": "Frank is good at playing the piano but is terrible at singing.", "zh": "弗兰克擅长弹钢琴，但歌却唱得很难听。"}], "sub_entries": []}, {"num": 3, "word": "sewing", "phonetic": "[ˈsoiɡ]", "pos": "n.", "meaning": "缝纫", "examples": [{"en": "Mother sewed the buttons onto one of my shirts.", "zh": "妈妈把钮扣缝在我的-件衬衫上面。"}], "sub_entries": ["sew[so]vt.缝（衣服）"]}], "grammar": null, "substitution": [], "exercises": {"prompt": "Ⅲ：请选出下列各句中正确的一项", "questions": ["1. Bob is bad", "baseball.", "(A) at play", "(B) playing", "(C) at playing", "(D) and plays", "2. John is thinking", "changing his major.", "(A)about", "(B)in", "(C) on", "(D) for", "3. Instead of studying with his friends, he studied", "(A) by himself", "(B)of his own", "(C) by hisself", "(D) on himself", "4.Rather than", "to work, Bill took a bus.", "(A) walking", "(B) to walk", "(C) of walking", "(D) walk", "5. Are you afraid", "him the truth?", "(A) to telling", "(B) of telling", "(C) of tell", "(D) telling", "6.Charlie is", "playing basketball. In fact,", "he's the best player in our school.", "(A) really good for", "(B) good really in", "(C) very good about (D) very good at"], "answers": ["解答>1.(C）2.(A）3.(A）4.(D）5.(B）6.(D)"]}}, {"type": "song", "id": "song_04", "title_en": "Tennessee Waltz", "title_zh": "田纳西华尔兹", "lyrics": [], "category": "经典英文金曲赏析"}];